INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u1-C1','kor',1,1,'u1',1,'자음자와 모음자 가르기 — 자음자(ㄱ, ㄴ, ㅁ, ㅊ …)와 모음자(ㅏ, ㅜ, ㅣ …)를 가르고, 받침이 없는 글자를 자음자와 모음자로 나누기, 소리 없는 ㅇ도 자음자 자리에 온다는 것 알기(『국어』 107·112~115쪽)',ARRAY['2국04-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u1-C2','kor',1,1,'u1',1,'받침이 없는 글자 만들기 — 자음자 하나와 모음자 하나를 모아 글자를 만들고 소리를 이어 읽기(ㄴ+ㅏ, ㅁ+ㅜ → 나무), 모음자 방향·획 수가 바뀌면 다른 글자가 됨을 알기(『국어』 107·120~121쪽)',ARRAY['2국04-01']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u1-C3','kor',1,1,'u1',3,'글자의 짜임 — 자음자는 글자에서 왼쪽이나 위쪽, 모음자는 오른쪽이나 아래쪽에 있음(가지·기차는 옆으로, 포도·고추는 위아래로), 같은 자음자라도 짝 모음자에 따라 자리가 달라짐(『국어』 114~117쪽)',ARRAY['2국04-01']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u1-C4','kor',1,1,'u1',5,'기본 음절표 읽기 — 왼쪽 자음자 줄과 위쪽 모음자 칸이 만나는 곳의 글자를 찾고, 빈칸을 채우거나 음절표에서 글자를 찾아 낱말을 완성하기(시소·모자·두부·타조·코·파도, 『국어』 118~119쪽)',ARRAY['2국04-01']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u1-C5','kor',1,1,'u1',7,'바른 자세로 읽고 쓰기·획순 — 허리를 펴고 책과 눈 사이를 알맞게 띄워 또박또박 읽기, 연필을 바르게 잡고 다른 손으로 공책을 눌러 쓰기, 자음자 먼저·위에서 아래로·왼쪽에서 오른쪽으로(『국어』 122~126쪽)',ARRAY['2국03-01']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u1-C6','kor',1,1,'u1',9,'여러 가지 모음자 — ㅐ ㅔ ㅒ ㅖ와 두 모음자가 합쳐진 ㅘ ㅙ ㅚ ㅝ ㅞ ㅟ ㅢ를 알고, 낱말 속에서 찾거나 그 모음자로 글자 만들기(모래·그네·얘기·시계·사과·돼지·참외·병원·스웨터·가위·의자, 『국어』 127~139쪽)',ARRAY['2국04-01']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u1-C7','kor',1,1,'u1',13,'글자를 모아 낱말 만들고 또박또박 읽기 — 자음자·모음자를 보고 낱말 알아맞히기, 글자를 차례대로 모아 낱말 만들기, 뜻이 없는 낱말까지 짐작하지 않고 또박또박 읽기(『국어』 140~145쪽, 지도서 평가 2)',ARRAY['2국02-01']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u1-C8','kor',1,1,'u1',9,'자음자와 모음자의 이름 — 모음자의 이름은 그 소리와 같고(ㅐ 애, ㅚ 외, ㅝ 워), 자음자는 이름이 따로 있음(ㅌ 티읕, ㅅ 시옷); 이름을 바르게 말하기(『국어활동』 16쪽, 지도서 평가 2)',ARRAY['2국04-01']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X01','kor',1,'u1',ARRAY['K1-1-u1-C1','K1-1-u1-C3']::text[],'자음자와 모음자를 가르지 못하거나, 글자 속에서 자음자 자리에 모음자를(모음자 자리에 자음자를) 고른다','자음자 카드와 모음자 카드를 두 줄로 나누어 놓고, 글자 하나마다 「자음자 하나, 모음자 하나」를 짚어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X02','kor',1,'u1',ARRAY['K1-1-u1-C1','K1-1-u1-C2','K1-1-u1-C6']::text[],'모음자의 방향을 바꾸어 본다(ㅏ↔ㅓ, ㅗ↔ㅜ, ㅑ↔ㅕ)','짧은 획이 긴 획의 어느 쪽에 붙었는지 손가락으로 짚기 — 「바깥쪽이면 ㅏ, 안쪽이면 ㅓ」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X03','kor',1,'u1',ARRAY['K1-1-u1-C2','K1-1-u1-C6']::text[],'짧은 획 하나가 더 있고 없음을 놓친다(ㅏ↔ㅑ, ㅓ↔ㅕ, ㅗ↔ㅛ, ㅜ↔ㅠ)','짧은 획 개수를 「하나·둘」 소리 내어 세어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X04','kor',1,'u1',ARRAY['K1-1-u1-C1','K1-1-u1-C2']::text[],'닮은 자음자를 헷갈린다(ㄱ↔ㅋ, ㄷ↔ㅌ, ㅂ↔ㅍ, ㅈ↔ㅊ, ㅇ↔ㅎ)','획이 하나 더 있는지 견주어 보고, 두 소리를 번갈아 크게 내 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X05','kor',1,'u1',ARRAY['K1-1-u1-C3']::text[],'글자의 짜임 자리를 헷갈린다(가로로 긴 모음자를 옆에, 세로로 긴 모음자를 아래에 둔다)','「파·오이는 자음자가 왼쪽이나 위쪽, 고추·고구마는 모음자가 아래쪽이나 오른쪽」 — 교과서 115쪽 말을 소리 내어 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X06','kor',1,'u1',ARRAY['K1-1-u1-C2','K1-1-u1-C4','K1-1-u1-C7']::text[],'모음자 카드를 돌려 다른 모음자로 읽는다(ㅏ↔ㅗ, ㅓ↔ㅜ, ㅡ↔ㅣ)','「자음자와 모음자를 다른 방향으로 돌리지 않아요」(교과서 141쪽) — 카드 윗면에 별표를 붙이고 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X07','kor',1,'u1',ARRAY['K1-1-u1-C4']::text[],'기본 음절표에서 옆 칸·옆 줄의 글자를 고른다(줄과 칸이 만나는 곳을 놓친다)','왼손 손가락은 자음자 줄, 오른손 손가락은 모음자 칸 — 두 손가락이 만나는 칸') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X08','kor',1,'u1',ARRAY['K1-1-u1-C2','K1-1-u1-C7']::text[],'모음자는 보지 않고 자음자만 보고 글자나 낱말을 고른다','「자음자가 같아도 모음자가 다르면 다른 글자」 — 모음자에 동그라미 치고 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X09','kor',1,'u1',ARRAY['K1-1-u1-C7']::text[],'글자를 모으는 차례를 바꾸어 다른 낱말을 만든다(비누→누비, 휴지→지휴)','카드를 왼쪽부터 손가락으로 하나씩 짚으며 소리 내어 모으기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X10','kor',1,'u1',ARRAY['K1-1-u1-C5']::text[],'바른 읽기 자세를 가르지 못한다(턱 괴기·엎드리기·책에 얼굴 붙이기)','허리 펴기 · 두 발 바닥에 · 책과 눈 사이 알맞게 — 세 가지를 손가락으로 세며 앉아 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X11','kor',1,'u1',ARRAY['K1-1-u1-C5']::text[],'바른 쓰기 자세·연필 잡기를 가르지 못한다(공책 들고 쓰기·몸 기울이기·주먹으로 쥐기)','연필 잡은 손, 공책 누른 손, 곧은 허리 — 세 가지를 짝과 서로 봐 주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X12','kor',1,'u1',ARRAY['K1-1-u1-C5']::text[],'획순을 거꾸로 쓴다(모음자를 먼저, 아래에서 위로, 오른쪽에서 왼쪽으로)','「위에서 아래로, 왼쪽에서 오른쪽으로, 자음자 먼저」 세 마디를 말하며 공중에 크게 써 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X13','kor',1,'u1',ARRAY['K1-1-u1-C6']::text[],'ㅐ와 ㅔ, ㅒ와 ㅖ를 헷갈린다(그네→그내, 시계→시게)','ㅐ는 ㅏ와 ㅣ, ㅔ는 ㅓ와 ㅣ가 붙은 모양 — 앞의 모음자를 먼저 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X14','kor',1,'u1',ARRAY['K1-1-u1-C6']::text[],'두 모음자가 합쳐진 모음자(ㅘ ㅙ ㅚ ㅝ ㅞ ㅟ ㅢ)에서 한쪽만 본다(사과→사가, 의자→이자)','합친 모음자를 두 카드로 떼어 놓았다가 다시 붙여 보기 — 「ㅗ 더하기 ㅏ는 ㅘ」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X15','kor',1,'u1',ARRAY['K1-1-u1-C5','K1-1-u1-C7']::text[],'글자를 하나하나 읽지 않고 그림·첫 글자로 짐작하거나 빨리만 읽는다(뜻이 없는 낱말을 아는 낱말로 바꿔 읽는다)','그림을 가리고 손가락으로 글자를 하나씩 짚으며 읽기 — 빠르기보다 정확하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X16','kor',1,'u1',ARRAY['K1-1-u1-C1']::text[],'「오·이·의」처럼 소리 없는 ㅇ이 앞에 오는 글자를 모음자 하나로 된 글자라고 여긴다','「오」 카드를 둘로 잘라 보기 — 위에 ㅇ, 아래에 ㅗ, 두 카드가 있어야 글자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X17','kor',1,'u1',ARRAY['K1-1-u1-C8']::text[],'자음자·모음자의 이름을 헷갈린다(ㅐ를 「에」, ㅚ를 「위」, ㅌ을 「트」라고 부른다)','모음자는 소리가 곧 이름 — 거울을 보고 입 모양을 따라 하며 이름 말하기, 자음자는 「기역, 니은 …」 차례로 외기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_basic#1','kor',1,1,'u1','L01','g1_1_kor_u1_L01_basic','lesson_basic','K1-1-u1-C1',1,'mc','auto','동물 친구들이 든 카드 가운데 모음자는 어느 것인가요?',ARRAY['K1-1-u1-X01']::text[],true,'{"seq":1,"concept":"K1-1-u1-C1","difficulty":1,"kind":"mc","stem":"동물 친구들이 든 카드 가운데 모음자는 어느 것인가요?","options":[{"t":"ㅏ","correct":true},{"t":"ㄴ","mis":"K1-1-u1-X01"},{"t":"ㅊ","mis":"K1-1-u1-X01"}],"explanation":["ㅏ는 모음자예요.","ㄴ·ㅊ은 자음자예요.","모음자는 ㅏ·ㅜ·ㅣ처럼 막대 모양이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 동물 친구들이 든 카드 가운데 모음자는 어느 것인가요?","options":[{"t":"ㅜ","correct":true},{"t":"ㄱ","mis":"K1-1-u1-X01"},{"t":"ㅁ","mis":"K1-1-u1-X01"}],"explanation":["ㅜ는 모음자예요.","ㄱ·ㅁ은 자음자예요.","모음자는 막대 모양이에요."]},{"stem":"이번에는 다른 보기예요. 동물 친구들이 든 카드 가운데 모음자는 어느 것인가요?","options":[{"t":"ㅣ","correct":true},{"t":"ㄴ","mis":"K1-1-u1-X01"},{"t":"ㅊ","mis":"K1-1-u1-X01"}],"explanation":["ㅣ는 모음자예요.","ㄴ·ㅊ은 자음자예요.","모음자는 막대 모양이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_basic#2','kor',1,1,'u1','L01','g1_1_kor_u1_L01_basic','lesson_basic','K1-1-u1-C1',1,'mc','auto','동물 친구들이 든 카드 가운데 자음자는 어느 것인가요?',ARRAY['K1-1-u1-X01']::text[],true,'{"seq":2,"concept":"K1-1-u1-C1","difficulty":1,"kind":"mc","stem":"동물 친구들이 든 카드 가운데 자음자는 어느 것인가요?","options":[{"t":"ㅊ","correct":true},{"t":"ㅏ","mis":"K1-1-u1-X01"},{"t":"ㅜ","mis":"K1-1-u1-X01"}],"explanation":["ㅊ은 자음자예요.","ㅏ·ㅜ는 모음자예요.","자음자는 글자의 첫소리를 내요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 동물 친구들이 든 카드 가운데 자음자는 어느 것인가요?","options":[{"t":"ㅁ","correct":true},{"t":"ㅣ","mis":"K1-1-u1-X01"},{"t":"ㅏ","mis":"K1-1-u1-X01"}],"explanation":["ㅁ은 자음자예요.","ㅣ·ㅏ는 모음자예요.","자음자는 글자의 첫소리를 내요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_basic#3','kor',1,1,'u1','L01','g1_1_kor_u1_L01_basic','lesson_basic','K1-1-u1-C2',1,'mc','auto','자음자 ㄴ과 모음자 ㅏ가 만나면 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":3,"kind":"mc","stem":"자음자 ㄴ과 모음자 ㅏ가 만나면 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㄴ","v":"ㅏ","s":null,"lay":true},"options":[{"t":"나","correct":true},{"t":"너","mis":"K1-1-u1-X02"},{"t":"냐","mis":"K1-1-u1-X03"}],"explanation":["자음자 ㄴ과 모음자 ㅏ가 만나면 「나」예요.","ㅏ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":1,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅈ"],"vows":["ㅏ","ㅓ","ㅣ"],"mis":{"flip":"X02","stroke":"X03","cons":"X04"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_basic#4','kor',1,1,'u1','L01','g1_1_kor_u1_L01_basic','lesson_basic','K1-1-u1-C1',1,'mc','auto','「무」에서 자음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X04']::text[],true,'{"seq":4,"kind":"mc","stem":"「무」에서 자음자는 어느 것인가요?","asset":{"type":"jamo","s":"무","eq":false,"lay":"blank"},"options":[{"t":"ㅁ","correct":true},{"t":"ㅜ","mis":"K1-1-u1-X01"},{"t":"ㅂ","mis":"K1-1-u1-X04"}],"explanation":["「무」는 자음자 ㅁ과 모음자 ㅜ가 만난 글자예요.","자음자는 ㅁ이에요 — 위쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C1","difficulty":1,"variant_rule":{"jamo":{"ask":"cons","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ"],"mis":{"role":"X01","cons":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_basic#5','kor',1,1,'u1','L01','g1_1_kor_u1_L01_basic','lesson_basic','K1-1-u1-C2',2,'mc','auto','카드 ㄴ · ㅏ · ㅁ · ㅜ 를 모아 만든 낱말은 어느 것인가요?',ARRAY['K1-1-u1-X02']::text[],true,'{"seq":5,"concept":"K1-1-u1-C2","difficulty":2,"kind":"mc","stem":"카드 ㄴ · ㅏ · ㅁ · ㅜ 를 모아 만든 낱말은 어느 것인가요?","options":[{"t":"나무","correct":true},{"t":"너무","mis":"K1-1-u1-X02"},{"t":"나모","mis":"K1-1-u1-X02"}],"explanation":["ㄴ+ㅏ = 나, ㅁ+ㅜ = 무 — 나무예요.","「너무」는 ㅏ를 ㅓ로, 「나모」는 ㅜ를 ㅗ로 바꿨어요.","카드 모양 그대로 모아요."],"asset":{"type":"scene","icon":"🌳"},"variant_rule":{"alt":[{"stem":"카드 ㄱ · ㅣ · ㅊ · ㅏ 를 모아 만든 낱말은 어느 것인가요?","options":[{"t":"기차","correct":true},{"t":"기처","mis":"K1-1-u1-X02"},{"t":"차기","mis":"K1-1-u1-X09"}],"explanation":["ㄱ+ㅣ = 기, ㅊ+ㅏ = 차 — 기차예요.","「기처」는 ㅏ를 ㅓ로 바꿨고, 「차기」는 차례가 바뀌었어요.","카드 모양 그대로, 차례대로."],"asset":{"type":"scene","icon":"🚂"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_basic#6','kor',1,1,'u1','L01','g1_1_kor_u1_L01_basic','lesson_basic','K1-1-u1-C1',2,'mc','auto','「차」에서 모음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X02']::text[],true,'{"seq":6,"kind":"mc","stem":"「차」에서 모음자는 어느 것인가요?","asset":{"type":"jamo","s":"차","eq":false,"lay":"blank"},"options":[{"t":"ㅏ","correct":true},{"t":"ㅊ","mis":"K1-1-u1-X01"},{"t":"ㅓ","mis":"K1-1-u1-X02"}],"explanation":["「차」는 자음자 ㅊ과 모음자 ㅏ가 만난 글자예요.","모음자는 ㅏ예요 — 오른쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C1","difficulty":2,"variant_rule":{"jamo":{"ask":"vow","cons":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅈ"],"vows":["ㅏ","ㅓ","ㅑ","ㅕ"],"mis":{"role":"X01","flip":"X02","stroke":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_basic#7','kor',1,1,'u1','L01','g1_1_kor_u1_L01_basic','lesson_basic','K1-1-u1-C1',2,'mc','auto','모음자 길 찾기에서 ㅗ 칸에 왔어요. ㅗ가 들어간 낱말은 어느 것인가요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":7,"concept":"K1-1-u1-C1","difficulty":2,"kind":"mc","stem":"모음자 길 찾기에서 ㅗ 칸에 왔어요. ㅗ가 들어간 낱말은 어느 것인가요?","options":[{"t":"오이","correct":true},{"t":"우유","mis":"K1-1-u1-X02"},{"t":"요요","mis":"K1-1-u1-X03"}],"explanation":["「오이」의 「오」에 ㅗ가 있어요.","「우유」는 ㅜ·ㅠ, 「요요」는 ㅛ가 있어요.","짧은 획의 방향과 개수를 봐요."],"variant_rule":{"alt":[{"stem":"모음자 길 찾기에서 ㅏ 칸에 왔어요. ㅏ가 들어간 낱말은 어느 것인가요?","options":[{"t":"바다","correct":true},{"t":"머리","mis":"K1-1-u1-X02"},{"t":"야구","mis":"K1-1-u1-X03"}],"explanation":["「바다」의 두 글자에 ㅏ가 있어요.","「머리」는 ㅓ, 「야구」는 ㅑ가 있어요.","짧은 획의 방향과 개수를 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_basic#8','kor',1,1,'u1','L01','g1_1_kor_u1_L01_basic','lesson_basic','K1-1-u1-C1',2,'mc','auto','땅따먹기에서 말이 ㅂ 땅에 들어갔어요. ㅂ이 들어간 낱말은 어느 것인가요?',ARRAY['K1-1-u1-X04']::text[],true,'{"seq":8,"concept":"K1-1-u1-C1","difficulty":2,"kind":"mc","stem":"땅따먹기에서 말이 ㅂ 땅에 들어갔어요. ㅂ이 들어간 낱말은 어느 것인가요?","options":[{"t":"바지","correct":true},{"t":"파리","mis":"K1-1-u1-X04"},{"t":"피자","mis":"K1-1-u1-X04"}],"explanation":["「바지」의 「바」에 ㅂ이 있어요.","「파리」·「피자」에는 ㅂ과 닮은 ㅍ이 있어요.","닮은 자음자는 획을 견주어요."],"variant_rule":{"alt":[{"stem":"땅따먹기에서 말이 ㄱ 땅에 들어갔어요. ㄱ이 들어간 낱말은 어느 것인가요?","options":[{"t":"고구마","correct":true},{"t":"코","mis":"K1-1-u1-X04"},{"t":"키위","mis":"K1-1-u1-X04"}],"explanation":["「고구마」에 ㄱ이 있어요.","「코」·「키위」에는 ㄱ과 닮은 ㅋ이 있어요.","닮은 자음자는 획을 견주어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_basic#9','kor',1,1,'u1','L01','g1_1_kor_u1_L01_basic','lesson_basic','K1-1-u1-C1',2,'ox','auto','자음자 하나만 있어도 받침이 없는 글자를 만들 수 있어요.',ARRAY['K1-1-u1-X01']::text[],true,'{"seq":9,"concept":"K1-1-u1-C1","difficulty":2,"kind":"ox","stem":"자음자 하나만 있어도 받침이 없는 글자를 만들 수 있어요.","answer":"X","reason_options":[{"t":"받침이 없는 글자는 자음자와 모음자가 만나야 하니까","correct":true},{"t":"자음자가 글자의 소리를 다 내니까","mis":"K1-1-u1-X01"}],"mis":"K1-1-u1-X01","explanation":["자음자 ㄴ만으로는 글자가 되지 않아요.","ㄴ에 모음자 ㅏ가 와야 「나」가 돼요.","글자 = 자음자 + 모음자."],"variant_rule":{"alt":[{"stem":"모음자 ㅏ 하나만 있으면 「나」를 만들 수 있어요.","answer":"X","reason_options":[{"t":"「나」에는 자음자 ㄴ도 있어야 하니까","correct":true},{"t":"모음자가 글자의 소리를 다 내니까","mis":"K1-1-u1-X01"}],"explanation":["「나」는 ㄴ과 ㅏ가 만난 글자예요.","모음자 하나로는 「나」가 되지 않아요.","글자 = 자음자 + 모음자."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_basic#10','kor',1,1,'u1','L01','g1_1_kor_u1_L01_basic','lesson_basic','K1-1-u1-C2',3,'mc','auto','「무」를 만들려면 어떤 두 카드가 있어야 할까요?',ARRAY['K1-1-u1-X02','K1-1-u1-X04']::text[],true,'{"seq":10,"concept":"K1-1-u1-C2","difficulty":3,"kind":"mc","stem":"「무」를 만들려면 어떤 두 카드가 있어야 할까요?","options":[{"t":"ㅁ과 ㅜ","correct":true},{"t":"ㅁ과 ㅗ","mis":"K1-1-u1-X02"},{"t":"ㅂ과 ㅜ","mis":"K1-1-u1-X04"}],"explanation":["「무」는 자음자 ㅁ과 모음자 ㅜ가 만난 글자예요.","ㅗ면 「모」, ㅂ이면 「부」가 돼요.","자음자 하나 + 모음자 하나."],"variant_rule":{"alt":[{"stem":"「기」를 만들려면 어떤 두 카드가 있어야 할까요?","options":[{"t":"ㄱ과 ㅣ","correct":true},{"t":"ㄱ과 ㅡ","mis":"K1-1-u1-X06"},{"t":"ㅋ과 ㅣ","mis":"K1-1-u1-X04"}],"explanation":["「기」는 ㄱ과 ㅣ가 만난 글자예요.","ㅡ면 「그」, ㅋ이면 「키」가 돼요.","자음자 하나 + 모음자 하나."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_challenge#1','kor',1,1,'u1','L01','g1_1_kor_u1_L01_challenge','lesson_challenge','K1-1-u1-C1',2,'mc','auto','카드 ㄱ · ㅣ · ㅊ · ㅏ 를 자음자와 모음자로 바르게 나눈 것은 어느 것인가요?',ARRAY['K1-1-u1-X01']::text[],false,'{"seq":1,"concept":"K1-1-u1-C1","difficulty":2,"kind":"mc","stem":"카드 ㄱ · ㅣ · ㅊ · ㅏ 를 자음자와 모음자로 바르게 나눈 것은 어느 것인가요?","options":[{"t":"자음자 ㄱ · ㅊ / 모음자 ㅣ · ㅏ","correct":true},{"t":"자음자 ㄱ · ㅏ / 모음자 ㅊ · ㅣ","mis":"K1-1-u1-X01"},{"t":"자음자 ㅣ · ㅏ / 모음자 ㄱ · ㅊ","mis":"K1-1-u1-X01"}],"explanation":["ㄱ·ㅊ은 자음자, ㅣ·ㅏ는 모음자예요.","다른 것은 자음자와 모음자가 섞이거나 바뀌었어요.","막대 모양은 모음자."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_challenge#2','kor',1,1,'u1','L01','g1_1_kor_u1_L01_challenge','lesson_challenge','K1-1-u1-C2',2,'mc','auto','자음자 ㅊ과 모음자 ㅏ가 만나면 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":2,"kind":"mc","stem":"자음자 ㅊ과 모음자 ㅏ가 만나면 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㅊ","v":"ㅏ","s":null,"lay":true},"options":[{"t":"차","correct":true},{"t":"처","mis":"K1-1-u1-X02"},{"t":"챠","mis":"K1-1-u1-X03"}],"explanation":["자음자 ㅊ과 모음자 ㅏ가 만나면 「차」예요.","ㅏ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":2,"variant_rule":{"jamo":{"ask":"build","cons":["ㅊ","ㅈ","ㄱ","ㅋ","ㄷ","ㅌ"],"vows":["ㅏ","ㅓ","ㅑ","ㅕ"],"mis":{"flip":"X02","stroke":"X03","cons":"X04"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_challenge#3','kor',1,1,'u1','L01','g1_1_kor_u1_L01_challenge','lesson_challenge','K1-1-u1-C1',3,'mc','auto','「기」에서 모음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X06']::text[],true,'{"seq":3,"kind":"mc","stem":"「기」에서 모음자는 어느 것인가요?","asset":{"type":"jamo","s":"기","eq":false,"lay":"blank"},"options":[{"t":"ㅣ","correct":true},{"t":"ㄱ","mis":"K1-1-u1-X01"},{"t":"ㅡ","mis":"K1-1-u1-X06"}],"explanation":["「기」는 자음자 ㄱ과 모음자 ㅣ가 만난 글자예요.","모음자는 ㅣ예요 — 오른쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C1","difficulty":3,"variant_rule":{"jamo":{"ask":"vow","cons":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅈ"],"vows":["ㅣ","ㅡ","ㅏ","ㅗ"],"mis":{"role":"X01","rot":"X06"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_challenge#4','kor',1,1,'u1','L01','g1_1_kor_u1_L01_challenge','lesson_challenge','K1-1-u1-C2',3,'error','auto','윤호가 땅따먹기에서 자음자 ㅎ과 모음자 ㅏ를 모아 「아」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u1-X04','K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":4,"concept":"K1-1-u1-C2","difficulty":3,"kind":"error","stem":"윤호가 땅따먹기에서 자음자 ㅎ과 모음자 ㅏ를 모아 「아」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"자음자를 ㅇ으로 바꾸어 썼어요 — ㅎ과 ㅏ는 「하」예요","correct":true,"mis_target":"K1-1-u1-X04"},{"t":"모음자를 잘못 썼어요 — ㅎ과 ㅏ는 「허」예요","mis":"K1-1-u1-X02"},{"t":"짧은 획이 하나 모자라요 — ㅎ과 ㅏ는 「햐」예요","mis":"K1-1-u1-X03"}],"explanation":["ㅎ과 ㅇ은 닮았지만 다른 자음자예요.","ㅎ + ㅏ = 하, ㅇ + ㅏ = 아.","자음자 모양을 꼼꼼히 견주어요."],"variant_rule":{"alt":[{"stem":"서아가 자음자 ㄷ과 모음자 ㅗ를 모아 「토」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"자음자를 ㅌ으로 바꾸어 썼어요 — ㄷ과 ㅗ는 「도」예요","correct":true,"mis_target":"K1-1-u1-X04"},{"t":"모음자를 잘못 썼어요 — ㄷ과 ㅗ는 「두」예요","mis":"K1-1-u1-X02"},{"t":"짧은 획이 하나 모자라요 — ㄷ과 ㅗ는 「됴」예요","mis":"K1-1-u1-X03"}],"explanation":["ㄷ과 ㅌ은 닮았지만 다른 자음자예요.","ㄷ + ㅗ = 도, ㅌ + ㅗ = 토.","자음자 모양을 꼼꼼히 견주어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_challenge#5','kor',1,1,'u1','L01','g1_1_kor_u1_L01_challenge','lesson_challenge','K1-1-u1-C1',3,'mc','auto','「바다 · 나무 · 기차」 가운데 모음자 ㅏ가 두 번 들어 있는 낱말은 어느 것인가요?',ARRAY['K1-1-u1-X08']::text[],true,'{"seq":5,"concept":"K1-1-u1-C1","difficulty":3,"kind":"mc","stem":"「바다 · 나무 · 기차」 가운데 모음자 ㅏ가 두 번 들어 있는 낱말은 어느 것인가요?","options":[{"t":"바다","correct":true},{"t":"나무","mis":"K1-1-u1-X08"},{"t":"기차","mis":"K1-1-u1-X08"}],"explanation":["「바」와 「다」 모두 ㅏ가 있어요.","「나무」는 ㅏ와 ㅜ, 「기차」는 ㅣ와 ㅏ예요.","글자마다 모음자를 하나씩 봐요."],"variant_rule":{"alt":[{"stem":"「오이 · 포도 · 우유」 가운데 모음자 ㅗ가 두 번 들어 있는 낱말은 어느 것인가요?","options":[{"t":"포도","correct":true},{"t":"오이","mis":"K1-1-u1-X08"},{"t":"우유","mis":"K1-1-u1-X02"}],"explanation":["「포」와 「도」 모두 ㅗ가 있어요.","「오이」는 ㅗ와 ㅣ, 「우유」는 ㅜ와 ㅠ예요.","글자마다 모음자를 하나씩 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_challenge#6','kor',1,1,'u1','L01','g1_1_kor_u1_L01_challenge','lesson_challenge','K1-1-u1-C2',3,'sa','auto','자음자 ㄱ과 모음자 ㅣ가 만나면 어떤 글자가 되나요?','{}'::text[],true,'{"seq":6,"kind":"sa","stem":"자음자 ㄱ과 모음자 ㅣ가 만나면 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㄱ","v":"ㅣ","s":null},"answer":["기"],"explanation":["자음자 ㄱ과 모음자 ㅣ가 만나면 「기」예요.","ㅣ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":3,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅣ","ㅡ"],"mis":{"rot":"X06","cons":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_challenge#7','kor',1,1,'u1','L01','g1_1_kor_u1_L01_challenge','lesson_challenge','K1-1-u1-C1',3,'ox','auto','「오이」의 「오」는 모음자 ㅗ 하나로만 된 글자예요.',ARRAY['K1-1-u1-X16']::text[],true,'{"seq":7,"concept":"K1-1-u1-C1","difficulty":3,"kind":"ox","stem":"「오이」의 「오」는 모음자 ㅗ 하나로만 된 글자예요.","answer":"X","reason_options":[{"t":"「오」는 위에 자음자 ㅇ, 아래에 모음자 ㅗ가 있으니까","correct":true},{"t":"ㅇ은 소리가 없어서 자음자가 아니니까","mis":"K1-1-u1-X16"}],"mis":"K1-1-u1-X16","explanation":["「오」에도 자음자 ㅇ이 있어요.","ㅇ은 소리가 나지 않지만 자음자 자리를 채워요.","아·오·이도 자음자 + 모음자."],"variant_rule":{"alt":[{"stem":"「오이」의 「이」는 모음자 ㅣ 하나로만 된 글자예요.","answer":"X","reason_options":[{"t":"「이」는 왼쪽에 자음자 ㅇ, 오른쪽에 모음자 ㅣ가 있으니까","correct":true},{"t":"ㅇ은 소리가 없어서 자음자가 아니니까","mis":"K1-1-u1-X16"}],"explanation":["「이」에도 자음자 ㅇ이 있어요.","ㅇ은 소리가 나지 않지만 자음자 자리를 채워요.","아·오·이도 자음자 + 모음자."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_challenge#8','kor',1,1,'u1','L01','g1_1_kor_u1_L01_challenge','lesson_challenge','K1-1-u1-C2',4,'mc','auto','같은 자음자에 모음자만 바꾸어 만든 글자끼리 모은 것은 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X04']::text[],true,'{"seq":8,"concept":"K1-1-u1-C2","difficulty":4,"kind":"mc","stem":"같은 자음자에 모음자만 바꾸어 만든 글자끼리 모은 것은 어느 것인가요?","options":[{"t":"가 · 고 · 기","correct":true},{"t":"가 · 나 · 다","mis":"K1-1-u1-X01"},{"t":"가 · 거 · 카","mis":"K1-1-u1-X04"}],"explanation":["「가·고·기」는 모두 ㄱ에 모음자만 달라요.","「가·나·다」는 모음자가 같고 자음자가 달라요. 「카」는 자음자가 ㅋ이에요.","무엇이 같고 무엇이 바뀌었나 견주어요."],"variant_rule":{"alt":[{"stem":"같은 모음자에 자음자만 바꾸어 만든 글자끼리 모은 것은 어느 것인가요?","options":[{"t":"노 · 도 · 로","correct":true},{"t":"노 · 너 · 나","mis":"K1-1-u1-X01"},{"t":"노 · 도 · 두","mis":"K1-1-u1-X02"}],"explanation":["「노·도·로」는 모두 ㅗ에 자음자만 달라요.","「노·너·나」는 자음자가 같고 모음자가 달라요. 「두」는 모음자가 ㅜ예요.","무엇이 같고 무엇이 바뀌었나 견주어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_challenge#9','kor',1,1,'u1','L01','g1_1_kor_u1_L01_challenge','lesson_challenge','K1-1-u1-C1',4,'essay','teacher','「나무」를 자음자와 모음자로 나누어 보고, 어떻게 나누었는지 말해 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u1-C1","difficulty":4,"kind":"essay","stem":"「나무」를 자음자와 모음자로 나누어 보고, 어떻게 나누었는지 말해 보세요.","answer_guide":{"answer":"예: 「나」는 자음자 ㄴ과 모음자 ㅏ, 「무」는 자음자 ㅁ과 모음자 ㅜ로 나누었어요. 글자마다 자음자 하나, 모음자 하나를 찾았어요. — 두 글자를 다 나누고 자음자·모음자를 바르게 말하면 맞아요.","scoring_points":["「나」를 ㄴ과 ㅏ로 나누었는가","「무」를 ㅁ과 ㅜ로 나누었는가","글자마다 자음자 하나·모음자 하나라는 방법을 말했는가"]},"explanation":["나 = ㄴ + ㅏ.","무 = ㅁ + ㅜ.","글자마다 자음자 하나, 모음자 하나."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_challenge#10','kor',1,1,'u1','L01','g1_1_kor_u1_L01_challenge','lesson_challenge','K1-1-u1-C2',4,'mc','auto','카드 ㄴ · ㅁ · ㅏ · ㅜ 가운데 두 장을 골라 만들 수 없는 글자는 어느 것인가요?',ARRAY['K1-1-u1-X02']::text[],true,'{"seq":10,"concept":"K1-1-u1-C2","difficulty":4,"kind":"mc","stem":"카드 ㄴ · ㅁ · ㅏ · ㅜ 가운데 두 장을 골라 만들 수 없는 글자는 어느 것인가요?","options":[{"t":"노","correct":true},{"t":"누","mis":"K1-1-u1-X02"},{"t":"마","mis":"K1-1-u1-X02"}],"explanation":["「노」에는 ㅗ가 있어야 하는데 카드에 ㅗ가 없어요.","「누」는 ㄴ+ㅜ, 「마」는 ㅁ+ㅏ로 만들 수 있어요.","ㅗ와 ㅜ는 방향이 달라요."],"variant_rule":{"alt":[{"stem":"카드 ㄱ · ㅊ · ㅏ · ㅣ 가운데 두 장을 골라 만들 수 없는 글자는 어느 것인가요?","options":[{"t":"거","correct":true},{"t":"기","mis":"K1-1-u1-X02"},{"t":"차","mis":"K1-1-u1-X01"}],"explanation":["「거」에는 ㅓ가 있어야 하는데 카드에 ㅓ가 없어요.","「기」는 ㄱ+ㅣ, 「차」는 ㅊ+ㅏ로 만들 수 있어요.","ㅏ와 ㅓ는 방향이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_basic#1','kor',1,1,'u1','L03','g1_1_kor_u1_L03_basic','lesson_basic','K1-1-u1-C1',1,'mc','auto','「파」에서 자음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X04']::text[],true,'{"seq":1,"kind":"mc","stem":"「파」에서 자음자는 어느 것인가요?","asset":{"type":"jamo","s":"파","eq":false,"lay":"blank"},"options":[{"t":"ㅍ","correct":true},{"t":"ㅏ","mis":"K1-1-u1-X01"},{"t":"ㅂ","mis":"K1-1-u1-X04"}],"explanation":["「파」는 자음자 ㅍ과 모음자 ㅏ가 만난 글자예요.","자음자는 ㅍ이에요 — 왼쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C1","difficulty":1,"variant_rule":{"jamo":{"ask":"cons","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ"],"mis":{"role":"X01","cons":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_basic#2','kor',1,1,'u1','L03','g1_1_kor_u1_L03_basic','lesson_basic','K1-1-u1-C1',1,'mc','auto','「오」에서 모음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X02']::text[],true,'{"seq":2,"kind":"mc","stem":"「오」에서 모음자는 어느 것인가요?","asset":{"type":"jamo","s":"오","eq":false,"lay":"blank"},"options":[{"t":"ㅗ","correct":true},{"t":"ㅇ","mis":"K1-1-u1-X01"},{"t":"ㅜ","mis":"K1-1-u1-X02"}],"explanation":["「오」는 자음자 ㅇ과 모음자 ㅗ가 만난 글자예요.","모음자는 ㅗ예요 — 아래쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C1","difficulty":1,"variant_rule":{"jamo":{"ask":"vow","cons":["ㅇ","ㄱ","ㄴ","ㅁ","ㅅ"],"vows":["ㅗ","ㅜ","ㅏ","ㅣ"],"mis":{"role":"X01","flip":"X02","rot":"X06"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_basic#3','kor',1,1,'u1','L03','g1_1_kor_u1_L03_basic','lesson_basic','K1-1-u1-C3',1,'mc','auto','「고」에서 자음자 ㄱ은 어디에 있나요?',ARRAY['K1-1-u1-X05','K1-1-u1-X01']::text[],true,'{"seq":3,"kind":"mc","stem":"「고」에서 자음자 ㄱ은 어디에 있나요?","asset":{"type":"jamo","s":"고","eq":false},"options":[{"t":"위쪽","correct":true},{"t":"왼쪽","mis":"K1-1-u1-X05"},{"t":"아래쪽","mis":"K1-1-u1-X01"}],"explanation":["「고」는 위아래로 쌓아서 만든 글자예요.","ㅗ는 가로로 길어서 자음자 아래에 쌓여요.","그래서 자음자 ㄱ은 위쪽에 있어요."],"concept":"K1-1-u1-C3","difficulty":1,"variant_rule":{"jamo":{"ask":"place","role":"c","cons":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅈ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ","ㅡ"],"mis":{"place":"X05","role":"X01"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_basic#4','kor',1,1,'u1','L03','g1_1_kor_u1_L03_basic','lesson_basic','K1-1-u1-C3',1,'mc','auto','「파」에서 모음자 ㅏ는 어디에 있나요?',ARRAY['K1-1-u1-X05','K1-1-u1-X01']::text[],true,'{"seq":4,"kind":"mc","stem":"「파」에서 모음자 ㅏ는 어디에 있나요?","asset":{"type":"jamo","s":"파","eq":false},"options":[{"t":"오른쪽","correct":true},{"t":"아래쪽","mis":"K1-1-u1-X05"},{"t":"왼쪽","mis":"K1-1-u1-X01"}],"explanation":["「파」는 옆으로 나란히 만든 글자예요.","ㅏ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","그래서 모음자 ㅏ는 오른쪽에 있어요."],"concept":"K1-1-u1-C3","difficulty":1,"variant_rule":{"jamo":{"ask":"place","role":"v","cons":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅈ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ","ㅡ"],"mis":{"place":"X05","role":"X01"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_basic#5','kor',1,1,'u1','L03','g1_1_kor_u1_L03_basic','lesson_basic','K1-1-u1-C1',2,'mc','auto','채소 가게의 「고구마」에 들어 있는 모음자를 차례대로 모은 것은 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X02']::text[],true,'{"seq":5,"concept":"K1-1-u1-C1","difficulty":2,"kind":"mc","stem":"채소 가게의 「고구마」에 들어 있는 모음자를 차례대로 모은 것은 어느 것인가요?","options":[{"t":"ㅗ · ㅜ · ㅏ","correct":true},{"t":"ㄱ · ㄱ · ㅁ","mis":"K1-1-u1-X01"},{"t":"ㅗ · ㅗ · ㅏ","mis":"K1-1-u1-X02"}],"explanation":["고(ㄱ+ㅗ), 구(ㄱ+ㅜ), 마(ㅁ+ㅏ)예요.","ㄱ·ㄱ·ㅁ은 자음자이고, 「구」의 모음자는 ㅗ가 아니라 ㅜ예요.","글자마다 모음자를 찾아요."],"asset":{"type":"scene","icon":"🍠"},"variant_rule":{"alt":[{"stem":"과일 가게의 「바나나」에 들어 있는 모음자를 차례대로 모은 것은 어느 것인가요?","options":[{"t":"ㅏ · ㅏ · ㅏ","correct":true},{"t":"ㅂ · ㄴ · ㄴ","mis":"K1-1-u1-X01"},{"t":"ㅓ · ㅏ · ㅏ","mis":"K1-1-u1-X02"}],"explanation":["바·나·나 모두 모음자가 ㅏ예요.","ㅂ·ㄴ·ㄴ은 자음자이고, ㅓ는 방향이 반대예요.","글자마다 모음자를 찾아요."],"asset":{"type":"scene","icon":"🍌"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_basic#6','kor',1,1,'u1','L03','g1_1_kor_u1_L03_basic','lesson_basic','K1-1-u1-C2',2,'mc','auto','자음자 ㅁ과 모음자 ㅜ가 만나면 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":6,"kind":"mc","stem":"자음자 ㅁ과 모음자 ㅜ가 만나면 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㅁ","v":"ㅜ","s":null,"lay":true},"options":[{"t":"무","correct":true},{"t":"모","mis":"K1-1-u1-X02"},{"t":"뮤","mis":"K1-1-u1-X03"}],"explanation":["자음자 ㅁ과 모음자 ㅜ가 만나면 「무」예요.","ㅜ는 가로로 길어서 자음자 아래에 쌓여요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":2,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅗ","ㅜ"],"mis":{"flip":"X02","stroke":"X03","rot":"X06"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_basic#7','kor',1,1,'u1','L03','g1_1_kor_u1_L03_basic','lesson_basic','K1-1-u1-C3',2,'mc','auto','자음자가 왼쪽, 모음자가 오른쪽에 있는 글자는 어느 것인가요?',ARRAY['K1-1-u1-X05']::text[],true,'{"seq":7,"concept":"K1-1-u1-C3","difficulty":2,"kind":"mc","stem":"자음자가 왼쪽, 모음자가 오른쪽에 있는 글자는 어느 것인가요?","options":[{"t":"파","correct":true},{"t":"고","mis":"K1-1-u1-X05"},{"t":"추","mis":"K1-1-u1-X05"}],"explanation":["「파」는 ㅍ 오른쪽에 ㅏ가 있어요.","「고」·「추」는 자음자 아래에 모음자가 있어요.","세로로 긴 모음자는 오른쪽에."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 자음자가 왼쪽, 모음자가 오른쪽에 있는 글자는 어느 것인가요?","options":[{"t":"지","correct":true},{"t":"포","mis":"K1-1-u1-X05"},{"t":"무","mis":"K1-1-u1-X05"}],"explanation":["「지」는 ㅈ 오른쪽에 ㅣ가 있어요.","「포」·「무」는 자음자 아래에 모음자가 있어요.","세로로 긴 모음자는 오른쪽에."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_basic#8','kor',1,1,'u1','L03','g1_1_kor_u1_L03_basic','lesson_basic','K1-1-u1-C3',2,'ox','auto','「오이」의 「오」를 둘로 나누면 ㅇ이 위에, ㅗ가 아래에 있어요.',ARRAY['K1-1-u1-X16']::text[],true,'{"seq":8,"concept":"K1-1-u1-C3","difficulty":2,"kind":"ox","stem":"「오이」의 「오」를 둘로 나누면 ㅇ이 위에, ㅗ가 아래에 있어요.","answer":"O","reason_options":[{"t":"ㅗ는 가로로 길어서 자음자 아래에 쌓이니까","correct":true},{"t":"ㅇ은 소리가 없어서 아무 데나 써도 되니까","mis":"K1-1-u1-X16"}],"mis":"K1-1-u1-X05","explanation":["「오」는 위아래로 쌓은 글자예요.","ㅇ이 위, ㅗ가 아래.","소리 없는 ㅇ도 제자리가 있어요."],"variant_rule":{"alt":[{"stem":"「오이」의 「이」를 둘로 나누면 ㅇ이 위에, ㅣ가 아래에 있어요.","answer":"X","reason_options":[{"t":"ㅣ는 세로로 길어서 ㅇ 오른쪽에 나란히 서니까","correct":true},{"t":"ㅇ은 언제나 위에만 쓰니까","mis":"K1-1-u1-X05"}],"explanation":["「이」는 옆으로 나란히 만든 글자예요.","ㅇ이 왼쪽, ㅣ가 오른쪽.","모음자 모양을 보고 자리를 정해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_basic#9','kor',1,1,'u1','L03','g1_1_kor_u1_L03_basic','lesson_basic','K1-1-u1-C1',2,'match','auto','물건 이름 글자와 그 글자를 나눈 것을 바르게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"K1-1-u1-C1","difficulty":2,"kind":"match","stem":"물건 이름 글자와 그 글자를 나눈 것을 바르게 이으세요.","pairs":[{"l":"파","r":"ㅍ + ㅏ"},{"l":"무","r":"ㅁ + ㅜ"},{"l":"오","r":"ㅇ + ㅗ"}],"mis":"K1-1-u1-X01","explanation":["파 = ㅍ + ㅏ, 무 = ㅁ + ㅜ.","오 = ㅇ + ㅗ — 소리 없는 ㅇ도 자음자예요.","글자마다 자음자 하나, 모음자 하나."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 물건 이름 글자와 그 글자를 나눈 것을 바르게 이으세요.","pairs":[{"l":"고","r":"ㄱ + ㅗ"},{"l":"추","r":"ㅊ + ㅜ"},{"l":"이","r":"ㅇ + ㅣ"}],"explanation":["고 = ㄱ + ㅗ, 추 = ㅊ + ㅜ.","이 = ㅇ + ㅣ — 소리 없는 ㅇ도 자음자예요.","글자마다 자음자 하나, 모음자 하나."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_basic#10','kor',1,1,'u1','L03','g1_1_kor_u1_L03_basic','lesson_basic','K1-1-u1-C3',3,'mc','auto','「추」에서 모음자 ㅜ는 어디에 있나요?',ARRAY['K1-1-u1-X05','K1-1-u1-X01']::text[],true,'{"seq":10,"kind":"mc","stem":"「추」에서 모음자 ㅜ는 어디에 있나요?","asset":{"type":"jamo","s":"추","eq":false},"options":[{"t":"아래쪽","correct":true},{"t":"오른쪽","mis":"K1-1-u1-X05"},{"t":"위쪽","mis":"K1-1-u1-X01"}],"explanation":["「추」는 위아래로 쌓아서 만든 글자예요.","ㅜ는 가로로 길어서 자음자 아래에 쌓여요.","그래서 모음자 ㅜ는 아래쪽에 있어요."],"concept":"K1-1-u1-C3","difficulty":3,"variant_rule":{"jamo":{"ask":"place","role":"v","cons":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅈ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ","ㅡ"],"mis":{"place":"X05","role":"X01"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_challenge#1','kor',1,1,'u1','L03','g1_1_kor_u1_L03_challenge','lesson_challenge','K1-1-u1-C3',2,'mc','auto','「파」, 「오이」에서 자음자는 어디에 있나요?',ARRAY['K1-1-u1-X01','K1-1-u1-X05']::text[],true,'{"seq":1,"concept":"K1-1-u1-C3","difficulty":2,"kind":"mc","stem":"「파」, 「오이」에서 자음자는 어디에 있나요?","options":[{"t":"왼쪽이나 위쪽","correct":true},{"t":"오른쪽이나 아래쪽","mis":"K1-1-u1-X01"},{"t":"언제나 가운데","mis":"K1-1-u1-X05"}],"explanation":["파는 ㅍ이 왼쪽, 오는 ㅇ이 위쪽, 이는 ㅇ이 왼쪽이에요.","오른쪽이나 아래쪽은 모음자 자리예요.","자음자는 왼쪽이나 위쪽."],"variant_rule":{"alt":[{"stem":"「고추」, 「고구마」에서 모음자는 어디에 있나요?","options":[{"t":"아래쪽이나 오른쪽","correct":true},{"t":"왼쪽이나 위쪽","mis":"K1-1-u1-X01"},{"t":"언제나 가운데","mis":"K1-1-u1-X05"}],"explanation":["고·추·구는 모음자가 아래쪽, 마는 오른쪽이에요.","왼쪽이나 위쪽은 자음자 자리예요.","모음자는 아래쪽이나 오른쪽."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_challenge#2','kor',1,1,'u1','L03','g1_1_kor_u1_L03_challenge','lesson_challenge','K1-1-u1-C1',2,'mc','auto','「구」에서 모음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X02']::text[],true,'{"seq":2,"kind":"mc","stem":"「구」에서 모음자는 어느 것인가요?","asset":{"type":"jamo","s":"구","eq":false,"lay":"blank"},"options":[{"t":"ㅜ","correct":true},{"t":"ㄱ","mis":"K1-1-u1-X01"},{"t":"ㅗ","mis":"K1-1-u1-X02"}],"explanation":["「구」는 자음자 ㄱ과 모음자 ㅜ가 만난 글자예요.","모음자는 ㅜ예요 — 아래쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C1","difficulty":2,"variant_rule":{"jamo":{"ask":"vow","cons":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅈ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ"],"mis":{"role":"X01","flip":"X02","rot":"X06"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_challenge#3','kor',1,1,'u1','L03','g1_1_kor_u1_L03_challenge','lesson_challenge','K1-1-u1-C3',3,'error','auto','민지가 「무」를 쓸 때 ㅜ를 ㅁ 오른쪽에 붙여 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u1-X05','K1-1-u1-X02','K1-1-u1-X04']::text[],true,'{"seq":3,"concept":"K1-1-u1-C3","difficulty":3,"kind":"error","stem":"민지가 「무」를 쓸 때 ㅜ를 ㅁ 오른쪽에 붙여 썼어요. 무엇이 잘못되었나요?","options":[{"t":"ㅜ는 가로로 길어서 ㅁ 아래에 써야 해요","correct":true,"mis_target":"K1-1-u1-X05"},{"t":"ㅜ 대신 ㅗ를 써야 해요","mis":"K1-1-u1-X02"},{"t":"ㅁ 대신 ㅂ을 써야 해요","mis":"K1-1-u1-X04"}],"explanation":["ㅜ는 가로로 누운 모음자예요.","누운 모음자는 자음자 아래에 쌓아요.","ㅁ을 위에, ㅜ를 아래에."],"variant_rule":{"alt":[{"stem":"지호가 「파」를 쓸 때 ㅏ를 ㅍ 아래에 붙여 썼어요. 무엇이 잘못되었나요?","options":[{"t":"ㅏ는 세로로 길어서 ㅍ 오른쪽에 써야 해요","correct":true,"mis_target":"K1-1-u1-X05"},{"t":"ㅏ 대신 ㅓ를 써야 해요","mis":"K1-1-u1-X02"},{"t":"ㅍ 대신 ㅂ을 써야 해요","mis":"K1-1-u1-X04"}],"explanation":["ㅏ는 세로로 선 모음자예요.","선 모음자는 자음자 오른쪽에 나란히.","ㅍ을 왼쪽에, ㅏ를 오른쪽에."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_challenge#4','kor',1,1,'u1','L03','g1_1_kor_u1_L03_challenge','lesson_challenge','K1-1-u1-C1',3,'mc','auto','「포」에서 자음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X04']::text[],true,'{"seq":4,"kind":"mc","stem":"「포」에서 자음자는 어느 것인가요?","asset":{"type":"jamo","s":"포","eq":false,"lay":"blank"},"options":[{"t":"ㅍ","correct":true},{"t":"ㅗ","mis":"K1-1-u1-X01"},{"t":"ㅂ","mis":"K1-1-u1-X04"}],"explanation":["「포」는 자음자 ㅍ과 모음자 ㅗ가 만난 글자예요.","자음자는 ㅍ이에요 — 위쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C1","difficulty":3,"variant_rule":{"jamo":{"ask":"cons","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ"],"mis":{"role":"X01","cons":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_challenge#5','kor',1,1,'u1','L03','g1_1_kor_u1_L03_challenge','lesson_challenge','K1-1-u1-C3',3,'mc','auto','글자마다 자음자가 위쪽에 있는 낱말끼리 모은 것은 어느 것인가요?',ARRAY['K1-1-u1-X05']::text[],true,'{"seq":5,"concept":"K1-1-u1-C3","difficulty":3,"kind":"mc","stem":"글자마다 자음자가 위쪽에 있는 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"고추 · 무 · 포도","correct":true},{"t":"파 · 가지 · 무","mis":"K1-1-u1-X05"},{"t":"바나나 · 고추","mis":"K1-1-u1-X05"}],"explanation":["고추·무·포도는 모든 글자에서 모음자가 아래에 쌓였어요.","파·가지·바나나는 자음자가 왼쪽에 있어요.","가로로 긴 모음자를 찾아요."],"variant_rule":{"alt":[{"stem":"글자마다 자음자가 왼쪽에 있는 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"파 · 가지 · 바나나","correct":true},{"t":"파 · 포도","mis":"K1-1-u1-X05"},{"t":"고추 · 무","mis":"K1-1-u1-X05"}],"explanation":["파·가지·바나나는 모든 글자에서 모음자가 오른쪽에 섰어요.","포도·고추·무는 자음자가 위쪽에 있어요.","세로로 긴 모음자를 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_challenge#6','kor',1,1,'u1','L03','g1_1_kor_u1_L03_challenge','lesson_challenge','K1-1-u1-C2',3,'mc','auto','ㅊ + ㅜ 는 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":6,"kind":"mc","stem":"ㅊ + ㅜ 는 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㅊ","v":"ㅜ","s":null},"options":[{"t":"추","correct":true},{"t":"초","mis":"K1-1-u1-X02"},{"t":"츄","mis":"K1-1-u1-X03"}],"explanation":["자음자 ㅊ과 모음자 ㅜ가 만나면 「추」예요.","ㅜ는 가로로 길어서 자음자 아래에 쌓여요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":3,"variant_rule":{"jamo":{"ask":"build","cons":["ㅊ","ㅈ","ㄱ","ㄷ","ㅂ","ㅎ"],"vows":["ㅗ","ㅜ","ㅛ","ㅠ"],"mis":{"flip":"X02","stroke":"X03","cons":"X04"},"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_challenge#7','kor',1,1,'u1','L03','g1_1_kor_u1_L03_challenge','lesson_challenge','K1-1-u1-C1',3,'mc','auto','활동지의 「가수」에 들어 있는 자음자를 모두 모은 것은 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X04']::text[],true,'{"seq":7,"concept":"K1-1-u1-C1","difficulty":3,"kind":"mc","stem":"활동지의 「가수」에 들어 있는 자음자를 모두 모은 것은 어느 것인가요?","options":[{"t":"ㄱ · ㅅ","correct":true},{"t":"ㅏ · ㅜ","mis":"K1-1-u1-X01"},{"t":"ㄱ · ㅈ","mis":"K1-1-u1-X04"}],"explanation":["가(ㄱ+ㅏ), 수(ㅅ+ㅜ)예요.","ㅏ·ㅜ는 모음자이고, ㅈ은 ㅅ과 닮은 다른 자음자예요.","글자마다 자음자를 찾아요."],"variant_rule":{"alt":[{"stem":"활동지의 「허수아비」에 들어 있는 모음자를 차례대로 모은 것은 어느 것인가요?","options":[{"t":"ㅓ · ㅜ · ㅏ · ㅣ","correct":true},{"t":"ㅎ · ㅅ · ㅇ · ㅂ","mis":"K1-1-u1-X01"},{"t":"ㅏ · ㅜ · ㅏ · ㅣ","mis":"K1-1-u1-X02"}],"explanation":["허(ㅎ+ㅓ), 수(ㅅ+ㅜ), 아(ㅇ+ㅏ), 비(ㅂ+ㅣ)예요.","ㅎ·ㅅ·ㅇ·ㅂ은 자음자이고, 「허」의 모음자는 ㅓ예요.","글자마다 모음자를 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_challenge#8','kor',1,1,'u1','L03','g1_1_kor_u1_L03_challenge','lesson_challenge','K1-1-u1-C1',4,'mc','auto','「오이」의 두 글자에 똑같이 들어 있는 자음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X16']::text[],true,'{"seq":8,"concept":"K1-1-u1-C1","difficulty":4,"kind":"mc","stem":"「오이」의 두 글자에 똑같이 들어 있는 자음자는 어느 것인가요?","options":[{"t":"ㅇ","correct":true},{"t":"ㅗ","mis":"K1-1-u1-X01"},{"t":"없어요 — 「오」와 「이」는 모음자 하나로 된 글자예요","mis":"K1-1-u1-X16"}],"explanation":["「오」도 「이」도 자음자 ㅇ으로 시작해요.","ㅗ는 모음자예요. 소리가 없어도 ㅇ은 자음자예요.","아·오·이·우에도 ㅇ이 숨어 있어요."],"variant_rule":{"alt":[{"stem":"「우유」의 두 글자에 똑같이 들어 있는 자음자는 어느 것인가요?","options":[{"t":"ㅇ","correct":true},{"t":"ㅜ","mis":"K1-1-u1-X01"},{"t":"없어요 — 「우」와 「유」는 모음자 하나로 된 글자예요","mis":"K1-1-u1-X16"}],"explanation":["「우」도 「유」도 자음자 ㅇ으로 시작해요.","ㅜ는 모음자예요. 소리가 없어도 ㅇ은 자음자예요.","아·오·이·우에도 ㅇ이 숨어 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_challenge#9','kor',1,1,'u1','L03','g1_1_kor_u1_L03_challenge','lesson_challenge','K1-1-u1-C3',4,'essay','teacher','「파」와 「포도」의 「포」는 자음자가 같아요. 그런데 두 글자의 모양이 왜 다를까요?','{}'::text[],false,'{"seq":9,"concept":"K1-1-u1-C3","difficulty":4,"kind":"essay","stem":"「파」와 「포도」의 「포」는 자음자가 같아요. 그런데 두 글자의 모양이 왜 다를까요?","answer_guide":{"answer":"예: 「파」의 ㅏ는 세로로 길어서 ㅍ 오른쪽에 서고, 「포」의 ㅗ는 가로로 길어서 ㅍ 아래에 쌓이기 때문이에요. — 모음자 모양(세로·가로)과 자리(오른쪽·아래)를 함께 말하면 맞아요.","scoring_points":["모음자가 ㅏ와 ㅗ로 다르다고 말했는가","ㅏ는 오른쪽, ㅗ는 아래에 온다고 말했는가","모음자가 세로로 긴지 가로로 긴지로 까닭을 댔는가"]},"explanation":["같은 ㅍ이라도 짝 모음자가 달라요.","ㅏ는 옆으로, ㅗ는 위아래로.","모음자 모양이 자리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_challenge#10','kor',1,1,'u1','L03','g1_1_kor_u1_L03_challenge','lesson_challenge','K1-1-u1-C1',4,'sa','auto','「포도」의 두 글자에 똑같이 들어 있는 모음자를 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"K1-1-u1-C1","difficulty":4,"kind":"sa","stem":"「포도」의 두 글자에 똑같이 들어 있는 모음자를 쓰세요.","answer":["ㅗ"],"explanation":["「포」와 「도」 모두 아래에 ㅗ가 있어요.","자음자는 ㅍ과 ㄷ으로 달라요.","같은 자리를 견주어요."],"variant_rule":{"alt":[{"stem":"「바나나」의 세 글자에 똑같이 들어 있는 모음자를 쓰세요.","answer":["ㅏ"],"explanation":["「바」·「나」·「나」 모두 오른쪽에 ㅏ가 있어요.","자음자는 ㅂ과 ㄴ이에요.","같은 자리를 견주어요."]},{"stem":"「고구마」의 「고」와 「구」에 똑같이 들어 있는 자음자를 쓰세요.","answer":["ㄱ"],"explanation":["「고」와 「구」 모두 위에 ㄱ이 있어요.","모음자는 ㅗ와 ㅜ로 달라요.","같은 자리를 견주어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_basic#1','kor',1,1,'u1','L05','g1_1_kor_u1_L05_basic','lesson_basic','K1-1-u1-C3',1,'mc','auto','「포도」와 「가지」 가운데 위아래로 쌓아서 만든 글자는 어느 것인가요?',ARRAY['K1-1-u1-X05']::text[],true,'{"seq":1,"concept":"K1-1-u1-C3","difficulty":1,"kind":"mc","stem":"「포도」와 「가지」 가운데 위아래로 쌓아서 만든 글자는 어느 것인가요?","options":[{"t":"도","correct":true},{"t":"가","mis":"K1-1-u1-X05"},{"t":"지","mis":"K1-1-u1-X05"}],"explanation":["「도」는 ㄷ 아래에 ㅗ가 쌓였어요.","「가」·「지」는 옆으로 나란히 만든 글자예요.","가로로 긴 모음자는 아래에."],"variant_rule":{"alt":[{"stem":"「기차」와 「포도」 가운데 위아래로 쌓아서 만든 글자는 어느 것인가요?","options":[{"t":"포","correct":true},{"t":"기","mis":"K1-1-u1-X05"},{"t":"차","mis":"K1-1-u1-X05"}],"explanation":["「포」는 ㅍ 아래에 ㅗ가 쌓였어요.","「기」·「차」는 옆으로 나란히 만든 글자예요.","가로로 긴 모음자는 아래에."]},{"stem":"「도토리」에서 위아래로 쌓아서 만든 글자가 아닌 것은 어느 것인가요?","options":[{"t":"리","correct":true},{"t":"도","mis":"K1-1-u1-X05"},{"t":"토","mis":"K1-1-u1-X05"}],"explanation":["「리」는 ㄹ 오른쪽에 ㅣ가 있어요.","「도」·「토」는 위아래로 쌓은 글자예요.","모음자 모양을 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_basic#2','kor',1,1,'u1','L05','g1_1_kor_u1_L05_basic','lesson_basic','K1-1-u1-C4',1,'mc','auto','음절표에서 ? 칸에 들어갈 글자는 무엇인가요?',ARRAY['K1-1-u1-X06','K1-1-u1-X07']::text[],true,'{"seq":2,"kind":"mc","stem":"음절표에서 ? 칸에 들어갈 글자는 무엇인가요?","asset":{"type":"syl_table","cons":["ㄱ","ㄴ","ㄷ"],"vows":["ㅏ","ㅗ","ㅣ"],"q":[2,0]},"options":[{"t":"다","correct":true},{"t":"도","mis":"K1-1-u1-X06"},{"t":"디","mis":"K1-1-u1-X07"}],"explanation":["? 칸은 자음자 ㄷ 줄과 모음자 ㅏ 칸이 만나는 곳이에요.","ㄷ과 ㅏ가 만나면 「다」예요.","왼쪽 자음자 줄을 따라가다 위쪽 모음자 칸에서 멈춰요."],"concept":"K1-1-u1-C4","difficulty":1,"variant_rule":{"jamo":{"ask":"table","cons":["ㄱ","ㄴ","ㄷ","ㅁ","ㅂ","ㅅ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ"],"mis":{"grid":"X07","rot":"X06"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_basic#3','kor',1,1,'u1','L05','g1_1_kor_u1_L05_basic','lesson_basic','K1-1-u1-C4',1,'mc','auto','음절표에서 ? 칸에 들어갈 글자는 무엇인가요?',ARRAY['K1-1-u1-X02','K1-1-u1-X07']::text[],true,'{"seq":3,"kind":"mc","stem":"음절표에서 ? 칸에 들어갈 글자는 무엇인가요?","asset":{"type":"syl_table","cons":["ㄱ","ㅁ","ㅅ"],"vows":["ㅏ","ㅓ","ㅣ"],"q":[1,1]},"options":[{"t":"머","correct":true},{"t":"마","mis":"K1-1-u1-X02"},{"t":"미","mis":"K1-1-u1-X07"}],"explanation":["? 칸은 자음자 ㅁ 줄과 모음자 ㅓ 칸이 만나는 곳이에요.","ㅁ과 ㅓ가 만나면 「머」예요.","왼쪽 자음자 줄을 따라가다 위쪽 모음자 칸에서 멈춰요."],"concept":"K1-1-u1-C4","difficulty":1,"variant_rule":{"jamo":{"ask":"table","cons":["ㄱ","ㄴ","ㄷ","ㅁ","ㅂ","ㅅ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ"],"mis":{"grid":"X07","flip":"X02"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
