INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_basic#6','kor',1,1,'u1','L05','g1_1_kor_u1_L05_basic','lesson_basic','K1-1-u1-C3',2,'mc','auto','「리」에서 자음자 ㄹ은 어디에 있나요?',ARRAY['K1-1-u1-X05','K1-1-u1-X01']::text[],true,'{"seq":6,"kind":"mc","stem":"「리」에서 자음자 ㄹ은 어디에 있나요?","asset":{"type":"jamo","s":"리","eq":false},"options":[{"t":"왼쪽","correct":true},{"t":"위쪽","mis":"K1-1-u1-X05"},{"t":"오른쪽","mis":"K1-1-u1-X01"}],"explanation":["「리」는 옆으로 나란히 만든 글자예요.","ㅣ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","그래서 자음자 ㄹ은 왼쪽에 있어요."],"concept":"K1-1-u1-C3","difficulty":2,"variant_rule":{"jamo":{"ask":"place","role":"c","cons":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅈ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ","ㅡ"],"mis":{"place":"X05","role":"X01"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_basic#7','kor',1,1,'u1','L05','g1_1_kor_u1_L05_basic','lesson_basic','K1-1-u1-C7',2,'mc','auto','글자 「비」와 「누」를 차례대로 모으면 어떤 낱말이 될까요?',ARRAY['K1-1-u1-X09','K1-1-u1-X02']::text[],true,'{"seq":7,"concept":"K1-1-u1-C7","difficulty":2,"kind":"mc","stem":"글자 「비」와 「누」를 차례대로 모으면 어떤 낱말이 될까요?","options":[{"t":"비누","correct":true},{"t":"누비","mis":"K1-1-u1-X09"},{"t":"비나","mis":"K1-1-u1-X02"}],"explanation":["「비」 다음에 「누」 — 비누.","차례가 바뀌면 「누비」가 돼요.","왼쪽부터 차례대로 모아요."],"variant_rule":{"alt":[{"stem":"글자 「도」와 「토」와 「리」를 차례대로 모으면 어떤 낱말이 될까요?","options":[{"t":"도토리","correct":true},{"t":"토도리","mis":"K1-1-u1-X09"},{"t":"도터리","mis":"K1-1-u1-X02"}],"explanation":["도 → 토 → 리, 도토리.","차례가 바뀌면 다른 말이 돼요.","왼쪽부터 차례대로 모아요."]},{"stem":"글자 「기」와 「차」를 차례대로 모으면 어떤 낱말이 될까요?","options":[{"t":"기차","correct":true},{"t":"차기","mis":"K1-1-u1-X09"},{"t":"기초","mis":"K1-1-u1-X06"}],"explanation":["「기」 다음에 「차」 — 기차.","차례가 바뀌면 「차기」가 돼요.","왼쪽부터 차례대로 모아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_basic#8','kor',1,1,'u1','L05','g1_1_kor_u1_L05_basic','lesson_basic','K1-1-u1-C3',2,'ox','auto','「도토리」에서 「도」와 「리」는 짜임이 같아요.',ARRAY['K1-1-u1-X05']::text[],true,'{"seq":8,"concept":"K1-1-u1-C3","difficulty":2,"kind":"ox","stem":"「도토리」에서 「도」와 「리」는 짜임이 같아요.","answer":"X","reason_options":[{"t":"「도」는 위아래로, 「리」는 옆으로 만든 글자니까","correct":true},{"t":"한 낱말의 글자는 짜임이 모두 같으니까","mis":"K1-1-u1-X05"}],"mis":"K1-1-u1-X05","explanation":["도: ㄷ 아래에 ㅗ.","리: ㄹ 오른쪽에 ㅣ.","글자마다 모음자를 보고 짜임을 봐요."],"variant_rule":{"alt":[{"stem":"「포도」에서 「포」와 「도」는 짜임이 같아요.","answer":"O","reason_options":[{"t":"두 글자 모두 자음자 아래에 ㅗ가 쌓였으니까","correct":true},{"t":"자음자가 달라서 짜임도 다르니까","mis":"K1-1-u1-X05"}],"explanation":["포: ㅍ 아래에 ㅗ.","도: ㄷ 아래에 ㅗ.","짜임은 모음자 모양이 정해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_basic#9','kor',1,1,'u1','L05','g1_1_kor_u1_L05_basic','lesson_basic','K1-1-u1-C4',2,'mc','auto','기본 음절표에서 ㅈ 줄을 따라 차례대로 읽은 것은 어느 것인가요?',ARRAY['K1-1-u1-X07','K1-1-u1-X02']::text[],true,'{"seq":9,"concept":"K1-1-u1-C4","difficulty":2,"kind":"mc","stem":"기본 음절표에서 ㅈ 줄을 따라 차례대로 읽은 것은 어느 것인가요?","options":[{"t":"자 · 저 · 조 · 주","correct":true},{"t":"나 · 자 · 타","mis":"K1-1-u1-X07"},{"t":"자 · 저 · 주 · 조","mis":"K1-1-u1-X02"}],"explanation":["ㅈ 줄은 자·저·조·주예요.","「나·자·타」는 ㅏ 칸을 위에서 아래로 읽은 거예요.","줄은 옆으로 읽어요."],"asset":{"type":"syl_table","cons":["ㄴ","ㅈ","ㅌ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ"]},"variant_rule":{"alt":[{"stem":"기본 음절표에서 ㅌ 줄을 따라 차례대로 읽은 것은 어느 것인가요?","options":[{"t":"타 · 터 · 토 · 투","correct":true},{"t":"나 · 자 · 타","mis":"K1-1-u1-X07"},{"t":"타 · 터 · 투 · 토","mis":"K1-1-u1-X02"}],"explanation":["ㅌ 줄은 타·터·토·투예요.","「나·자·타」는 ㅏ 칸을 위에서 아래로 읽은 거예요.","줄은 옆으로 읽어요."],"asset":{"type":"syl_table","cons":["ㄴ","ㅈ","ㅌ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_basic#10','kor',1,1,'u1','L05','g1_1_kor_u1_L05_basic','lesson_basic','K1-1-u1-C4',3,'mc','auto','기본 음절표에서 글자를 찾아 그림에 알맞은 낱말 「타□」를 완성하면 □에 들어갈 글자는?',ARRAY['K1-1-u1-X02','K1-1-u1-X06']::text[],true,'{"seq":10,"concept":"K1-1-u1-C4","difficulty":3,"kind":"mc","stem":"기본 음절표에서 글자를 찾아 그림에 알맞은 낱말 「타□」를 완성하면 □에 들어갈 글자는?","options":[{"t":"조","correct":true},{"t":"주","mis":"K1-1-u1-X02"},{"t":"자","mis":"K1-1-u1-X06"}],"explanation":["그림은 「타조」예요.","ㅈ 줄과 ㅗ 칸이 만나는 「조」를 찾아요.","모음자 방향을 바르게 봐요."],"asset":{"type":"scene","icon":"🐦","text":"다리가 길고 빨리 달리는 큰 새"},"variant_rule":{"alt":[{"stem":"기본 음절표에서 글자를 찾아 그림에 알맞은 낱말 「□도」를 완성하면 □에 들어갈 글자는?","options":[{"t":"파","correct":true},{"t":"퍼","mis":"K1-1-u1-X02"},{"t":"포","mis":"K1-1-u1-X06"}],"explanation":["그림은 「파도」예요.","ㅍ 줄과 ㅏ 칸이 만나는 「파」를 찾아요.","모음자 방향을 바르게 봐요."],"asset":{"type":"scene","icon":"🌊"}},{"stem":"기본 음절표에서 글자를 찾아 그림에 알맞은 낱말 「두□」를 완성하면 □에 들어갈 글자는?","options":[{"t":"부","correct":true},{"t":"보","mis":"K1-1-u1-X02"},{"t":"푸","mis":"K1-1-u1-X04"}],"explanation":["그림은 「두부」예요.","ㅂ 줄과 ㅜ 칸이 만나는 「부」를 찾아요.","자음자와 모음자를 다 봐요."],"asset":{"type":"scene","icon":"🍲"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_challenge#1','kor',1,1,'u1','L05','g1_1_kor_u1_L05_challenge','lesson_challenge','K1-1-u1-C3',2,'mc','auto','「도」에서 모음자 ㅗ는 어디에 있나요?',ARRAY['K1-1-u1-X05','K1-1-u1-X01']::text[],true,'{"seq":1,"kind":"mc","stem":"「도」에서 모음자 ㅗ는 어디에 있나요?","asset":{"type":"jamo","s":"도","eq":false},"options":[{"t":"아래쪽","correct":true},{"t":"오른쪽","mis":"K1-1-u1-X05"},{"t":"위쪽","mis":"K1-1-u1-X01"}],"explanation":["「도」는 위아래로 쌓아서 만든 글자예요.","ㅗ는 가로로 길어서 자음자 아래에 쌓여요.","그래서 모음자 ㅗ는 아래쪽에 있어요."],"concept":"K1-1-u1-C3","difficulty":2,"variant_rule":{"jamo":{"ask":"place","role":"v","cons":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅈ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ","ㅡ"],"mis":{"place":"X05","role":"X01"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
