INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_challenge#3','kor',1,1,'u1','L05','g1_1_kor_u1_L05_challenge','lesson_challenge','K1-1-u1-C3',3,'mc','auto','ㄱ에 어떤 모음자를 붙이면 위아래로 쌓은 글자가 될까요?',ARRAY['K1-1-u1-X05']::text[],true,'{"seq":3,"concept":"K1-1-u1-C3","difficulty":3,"kind":"mc","stem":"ㄱ에 어떤 모음자를 붙이면 위아래로 쌓은 글자가 될까요?","options":[{"t":"ㅠ","correct":true},{"t":"ㅕ","mis":"K1-1-u1-X05"},{"t":"ㅣ","mis":"K1-1-u1-X05"}],"explanation":["ㅠ는 가로로 길어서 ㄱ 아래에 쌓여요 — 규.","ㅕ·ㅣ는 세로로 길어서 옆에 서요.","가로로 긴 모음자를 찾아요."],"variant_rule":{"alt":[{"stem":"ㅅ에 어떤 모음자를 붙이면 옆으로 나란한 글자가 될까요?","options":[{"t":"ㅑ","correct":true},{"t":"ㅛ","mis":"K1-1-u1-X05"},{"t":"ㅡ","mis":"K1-1-u1-X05"}],"explanation":["ㅑ는 세로로 길어서 ㅅ 오른쪽에 서요 — 샤.","ㅛ·ㅡ는 가로로 길어서 아래에 쌓여요.","세로로 긴 모음자를 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_challenge#4','kor',1,1,'u1','L05','g1_1_kor_u1_L05_challenge','lesson_challenge','K1-1-u1-C4',3,'error','auto','기본 음절표의 ㅁ 줄 ㅗ 칸에 「노」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u1-X07','K1-1-u1-X02','K1-1-u1-X06']::text[],true,'{"seq":4,"concept":"K1-1-u1-C4","difficulty":3,"kind":"error","stem":"기본 음절표의 ㅁ 줄 ㅗ 칸에 「노」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"자음자 줄을 잘못 보았어요 — ㅁ 줄이면 「모」예요","correct":true,"mis_target":"K1-1-u1-X07"},{"t":"모음자 칸을 잘못 보았어요 — ㅗ 칸이면 「무」예요","mis":"K1-1-u1-X02"},{"t":"카드를 돌려 보았어요 — 「마」라고 써야 해요","mis":"K1-1-u1-X06"}],"explanation":["ㅁ 줄과 ㅗ 칸이 만나면 「모」예요.","「노」는 ㄴ 줄의 글자예요.","줄은 자음자, 칸은 모음자."],"asset":{"type":"syl_table","cons":["ㄴ","ㅁ","ㅅ"],"vows":["ㅏ","ㅗ","ㅣ"]},"variant_rule":{"alt":[{"stem":"기본 음절표의 ㅅ 줄 ㅣ 칸에 「니」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"자음자 줄을 잘못 보았어요 — ㅅ 줄이면 「시」예요","correct":true,"mis_target":"K1-1-u1-X07"},{"t":"모음자 칸을 잘못 보았어요 — ㅣ 칸이면 「사」예요","mis":"K1-1-u1-X06"},{"t":"닮은 자음자를 썼어요 — 「지」라고 써야 해요","mis":"K1-1-u1-X04"}],"explanation":["ㅅ 줄과 ㅣ 칸이 만나면 「시」예요.","「니」는 ㄴ 줄의 글자예요.","줄은 자음자, 칸은 모음자."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_challenge#5','kor',1,1,'u1','L05','g1_1_kor_u1_L05_challenge','lesson_challenge','K1-1-u1-C2',3,'mc','auto','ㅌ + ㅏ 는 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":5,"kind":"mc","stem":"ㅌ + ㅏ 는 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㅌ","v":"ㅏ","s":null},"options":[{"t":"타","correct":true},{"t":"터","mis":"K1-1-u1-X02"},{"t":"탸","mis":"K1-1-u1-X03"}],"explanation":["자음자 ㅌ과 모음자 ㅏ가 만나면 「타」예요.","ㅏ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":3,"variant_rule":{"jamo":{"ask":"build","cons":["ㅌ","ㄷ","ㅋ","ㄱ","ㅍ","ㅂ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ"],"mis":{"flip":"X02","stroke":"X03","cons":"X04"},"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_challenge#6','kor',1,1,'u1','L05','g1_1_kor_u1_L05_challenge','lesson_challenge','K1-1-u1-C7',3,'mc','auto','기본 음절표에서 글자를 찾아 그림에 알맞은 낱말 「모□」를 완성하면 □에 들어갈 글자는?',ARRAY['K1-1-u1-X02','K1-1-u1-X04']::text[],true,'{"seq":6,"concept":"K1-1-u1-C7","difficulty":3,"kind":"mc","stem":"기본 음절표에서 글자를 찾아 그림에 알맞은 낱말 「모□」를 완성하면 □에 들어갈 글자는?","options":[{"t":"자","correct":true},{"t":"저","mis":"K1-1-u1-X02"},{"t":"차","mis":"K1-1-u1-X04"}],"explanation":["그림은 「모자」예요.","ㅈ 줄과 ㅏ 칸의 「자」를 찾아요.","자음자와 모음자를 다 봐요."],"asset":{"type":"scene","icon":"🎩"},"variant_rule":{"alt":[{"stem":"기본 음절표에서 글자를 찾아 그림에 알맞은 낱말 「시□」를 완성하면 □에 들어갈 글자는?","options":[{"t":"소","correct":true},{"t":"수","mis":"K1-1-u1-X02"},{"t":"조","mis":"K1-1-u1-X04"}],"explanation":["그림은 놀이터의 「시소」예요.","ㅅ 줄과 ㅗ 칸의 「소」를 찾아요.","자음자와 모음자를 다 봐요."],"asset":{"type":"scene","icon":"⚖️","text":"놀이터에서 둘이 오르락내리락 타는 것"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_challenge#7','kor',1,1,'u1','L05','g1_1_kor_u1_L05_challenge','lesson_challenge','K1-1-u1-C3',3,'match','auto','글자와 그 글자의 짜임을 바르게 이으세요.','{}'::text[],true,'{"seq":7,"concept":"K1-1-u1-C3","difficulty":3,"kind":"match","stem":"글자와 그 글자의 짜임을 바르게 이으세요.","pairs":[{"l":"기","r":"ㄱ 오른쪽에 ㅣ"},{"l":"차","r":"ㅊ 오른쪽에 ㅏ"},{"l":"토","r":"ㅌ 아래쪽에 ㅗ"}],"mis":"K1-1-u1-X05","explanation":["ㅣ·ㅏ는 오른쪽에 서요.","ㅗ는 아래에 쌓여요.","모음자 모양을 보고 이어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글자와 그 글자의 짜임을 바르게 이으세요.","pairs":[{"l":"포","r":"ㅍ 아래쪽에 ㅗ"},{"l":"리","r":"ㄹ 오른쪽에 ㅣ"},{"l":"누","r":"ㄴ 아래쪽에 ㅜ"}],"explanation":["ㅗ·ㅜ는 아래에 쌓여요.","ㅣ는 오른쪽에 서요.","모음자 모양을 보고 이어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_challenge#8','kor',1,1,'u1','L05','g1_1_kor_u1_L05_challenge','lesson_challenge','K1-1-u1-C4',4,'mc','auto','기본 음절표에서 「비누」의 「비」를 찾는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X07']::text[],true,'{"seq":8,"concept":"K1-1-u1-C4","difficulty":4,"kind":"mc","stem":"기본 음절표에서 「비누」의 「비」를 찾는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"ㅂ 줄을 따라가다 ㅣ 칸에서 멈춰요","correct":true},{"t":"ㅣ 줄을 따라가다 ㅂ 칸에서 멈춰요","mis":"K1-1-u1-X01"},{"t":"ㅂ 줄 바로 옆 칸이면 아무 칸이나 돼요","mis":"K1-1-u1-X07"}],"explanation":["줄은 자음자 ㅂ, 칸은 모음자 ㅣ예요.","두 곳이 만나는 칸이 「비」예요.","줄 따라, 칸에서 멈추기."],"asset":{"type":"syl_table","cons":["ㄴ","ㅂ","ㅅ"],"vows":["ㅏ","ㅜ","ㅣ"]},"variant_rule":{"alt":[{"stem":"기본 음절표에서 「비누」의 「누」를 찾는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"ㄴ 줄을 따라가다 ㅜ 칸에서 멈춰요","correct":true},{"t":"ㅜ 줄을 따라가다 ㄴ 칸에서 멈춰요","mis":"K1-1-u1-X01"},{"t":"ㄴ 줄 바로 옆 칸이면 아무 칸이나 돼요","mis":"K1-1-u1-X07"}],"explanation":["줄은 자음자 ㄴ, 칸은 모음자 ㅜ예요.","두 곳이 만나는 칸이 「누」예요.","줄 따라, 칸에서 멈추기."],"asset":{"type":"syl_table","cons":["ㄴ","ㅂ","ㅅ"],"vows":["ㅏ","ㅜ","ㅣ"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_challenge#9','kor',1,1,'u1','L05','g1_1_kor_u1_L05_challenge','lesson_challenge','K1-1-u1-C2',4,'essay','teacher','「가」는 어떤 소리와 어떤 소리가 만나 소리가 나는지, 자음자와 모음자의 소리를 생각하며 말해 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u1-C2","difficulty":4,"kind":"essay","stem":"「가」는 어떤 소리와 어떤 소리가 만나 소리가 나는지, 자음자와 모음자의 소리를 생각하며 말해 보세요.","answer_guide":{"answer":"예: ㄱ[그]를 짧게, ㅏ[아]를 길게 이어서 소리 내면 [가]가 돼요. 자음자는 혼자서는 소리가 나지 않고 모음자를 만나야 소리가 나요. — ㄱ과 ㅏ의 소리를 이어 낸다는 것과, 자음자는 혼자 소리 나지 않는다는 것을 말하면 맞아요.","scoring_points":["ㄱ과 ㅏ가 만난다고 말했는가","두 소리를 이어서 [가]가 된다고 말했는가","자음자는 혼자서 소리가 나지 않는다고 말했는가"]},"explanation":["ㄱ[그] + ㅏ[아] → [가].","자음자는 짧게, 모음자는 길게 이어요.","자음자는 모음자를 만나야 소리가 나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_challenge#10','kor',1,1,'u1','L05','g1_1_kor_u1_L05_challenge','lesson_challenge','K1-1-u1-C4',4,'mc','auto','음절표에서 ? 칸에 들어갈 글자는 무엇인가요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":10,"kind":"mc","stem":"음절표에서 ? 칸에 들어갈 글자는 무엇인가요?","asset":{"type":"syl_table","cons":["ㄱ","ㄹ","ㅂ","ㅍ"],"vows":["ㅓ","ㅗ","ㅜ","ㅠ"],"q":[1,3]},"options":[{"t":"류","correct":true},{"t":"료","mis":"K1-1-u1-X02"},{"t":"루","mis":"K1-1-u1-X03"}],"explanation":["? 칸은 자음자 ㄹ 줄과 모음자 ㅠ 칸이 만나는 곳이에요.","ㄹ과 ㅠ가 만나면 「류」예요.","왼쪽 자음자 줄을 따라가다 위쪽 모음자 칸에서 멈춰요."],"concept":"K1-1-u1-C4","difficulty":4,"variant_rule":{"jamo":{"ask":"table","cons":["ㄱ","ㄴ","ㄹ","ㅁ","ㅅ","ㅎ"],"vows":["ㅑ","ㅕ","ㅛ","ㅠ"],"mis":{"grid":"X07","flip":"X02","stroke":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_basic#1','kor',1,1,'u1','L07','g1_1_kor_u1_L07_basic','lesson_basic','K1-1-u1-C5',1,'mc','auto','책을 읽을 때 바른 자세는 어느 것인가요?',ARRAY['K1-1-u1-X10']::text[],true,'{"seq":1,"concept":"K1-1-u1-C5","difficulty":1,"kind":"mc","stem":"책을 읽을 때 바른 자세는 어느 것인가요?","options":[{"t":"허리를 곧게 펴고 책과 눈 사이를 알맞게 띄워요","correct":true},{"t":"턱을 괴고 책에 얼굴을 바짝 대요","mis":"K1-1-u1-X10"},{"t":"바닥에 엎드려서 읽어요","mis":"K1-1-u1-X10"}],"explanation":["허리를 펴고 알맞게 띄워야 눈과 허리가 편해요.","턱 괴기·엎드리기는 바른 자세가 아니에요.","허리 펴기, 알맞게 띄우기."],"asset":{"type":"scene","icon":"📖"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 책을 읽을 때 바른 자세는 어느 것인가요?","options":[{"t":"두 발을 바닥에 붙이고 허리를 펴고 앉아요","correct":true},{"t":"의자에 비스듬히 누워 읽어요","mis":"K1-1-u1-X10"},{"t":"다리를 꼬고 몸을 기울여 읽어요","mis":"K1-1-u1-X10"}],"explanation":["두 발은 바닥에, 허리는 곧게.","눕거나 기울이면 바른 자세가 아니에요.","등 펴기, 두 발 바닥."],"asset":{"type":"scene","icon":"📖"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_basic#2','kor',1,1,'u1','L07','g1_1_kor_u1_L07_basic','lesson_basic','K1-1-u1-C5',1,'mc','auto','글씨를 쓸 때 바른 자세는 어느 것인가요?',ARRAY['K1-1-u1-X11']::text[],true,'{"seq":2,"concept":"K1-1-u1-C5","difficulty":1,"kind":"mc","stem":"글씨를 쓸 때 바른 자세는 어느 것인가요?","options":[{"t":"연필을 바르게 쥐고 다른 손으로 공책을 눌러요","correct":true},{"t":"공책을 손에 들고 써요","mis":"K1-1-u1-X11"},{"t":"몸을 옆으로 기울여 써요","mis":"K1-1-u1-X11"}],"explanation":["공책을 눌러야 글씨가 흔들리지 않아요.","들고 쓰거나 기울이면 글씨가 삐뚤어져요.","쥔 손, 누른 손, 곧은 허리."],"asset":{"type":"scene","icon":"✏️"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글씨를 쓸 때 바른 자세는 어느 것인가요?","options":[{"t":"허리를 펴고 공책과 눈 사이를 알맞게 띄워요","correct":true},{"t":"공책에 얼굴을 바짝 대고 써요","mis":"K1-1-u1-X11"},{"t":"엎드려서 써요","mis":"K1-1-u1-X11"}],"explanation":["알맞게 띄워야 눈이 편해요.","얼굴을 대거나 엎드리면 바른 자세가 아니에요.","쥔 손, 누른 손, 곧은 허리."],"asset":{"type":"scene","icon":"✏️"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_basic#3','kor',1,1,'u1','L07','g1_1_kor_u1_L07_basic','lesson_basic','K1-1-u1-C2',1,'mc','auto','자음자 ㄱ과 모음자 ㅣ가 만나면 어떤 글자가 되나요?',ARRAY['K1-1-u1-X06','K1-1-u1-X04']::text[],true,'{"seq":3,"kind":"mc","stem":"자음자 ㄱ과 모음자 ㅣ가 만나면 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㄱ","v":"ㅣ","s":null,"lay":true},"options":[{"t":"기","correct":true},{"t":"그","mis":"K1-1-u1-X06"},{"t":"키","mis":"K1-1-u1-X04"}],"explanation":["자음자 ㄱ과 모음자 ㅣ가 만나면 「기」예요.","ㅣ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":1,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅣ","ㅡ"],"mis":{"rot":"X06","cons":"X04"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_basic#4','kor',1,1,'u1','L07','g1_1_kor_u1_L07_basic','lesson_basic','K1-1-u1-C2',1,'mc','auto','자음자 ㅎ과 모음자 ㅏ가 만나면 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":4,"kind":"mc","stem":"자음자 ㅎ과 모음자 ㅏ가 만나면 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㅎ","v":"ㅏ","s":null,"lay":true},"options":[{"t":"하","correct":true},{"t":"허","mis":"K1-1-u1-X02"},{"t":"햐","mis":"K1-1-u1-X03"}],"explanation":["자음자 ㅎ과 모음자 ㅏ가 만나면 「하」예요.","ㅏ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":1,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅣ"],"mis":{"flip":"X02","stroke":"X03","cons":"X04"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_basic#5','kor',1,1,'u1','L07','g1_1_kor_u1_L07_basic','lesson_basic','K1-1-u1-C5',2,'ox','auto','「나무야」를 소리 내어 읽을 때는 빨리 읽을수록 좋아요.',ARRAY['K1-1-u1-X15']::text[],true,'{"seq":5,"concept":"K1-1-u1-C5","difficulty":2,"kind":"ox","stem":"「나무야」를 소리 내어 읽을 때는 빨리 읽을수록 좋아요.","answer":"X","reason_options":[{"t":"또박또박 읽어야 듣는 사람이 잘 알아들으니까","correct":true},{"t":"빨리 읽어야 책을 많이 읽으니까","mis":"K1-1-u1-X15"}],"mis":"K1-1-u1-X15","explanation":["또박또박 읽어요.","빨리만 읽으면 글자를 빠뜨려요.","글자 하나하나 정확하게."],"variant_rule":{"alt":[{"stem":"글자를 읽을 때 그림을 보고 짐작해서 읽어도 괜찮아요.","answer":"X","reason_options":[{"t":"글자 하나하나를 보고 읽어야 바르게 읽으니까","correct":true},{"t":"그림이 글자보다 더 정확하니까","mis":"K1-1-u1-X15"}],"explanation":["그림은 도움일 뿐이에요.","글자를 하나씩 짚으며 읽어요.","짐작하지 않기."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_basic#6','kor',1,1,'u1','L07','g1_1_kor_u1_L07_basic','lesson_basic','K1-1-u1-C5',2,'mc','auto','「가」를 쓰는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u1-X12']::text[],true,'{"seq":6,"concept":"K1-1-u1-C5","difficulty":2,"kind":"mc","stem":"「가」를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"ㄱ을 먼저 쓰고 ㅏ를 써요","correct":true},{"t":"ㅏ를 먼저 쓰고 ㄱ을 써요","mis":"K1-1-u1-X12"},{"t":"ㅏ의 짧은 획을 가장 먼저 써요","mis":"K1-1-u1-X12"}],"explanation":["자음자를 먼저, 모음자를 나중에 써요.","ㅏ는 긴 세로획 다음에 짧은 획.","자음자 먼저."],"variant_rule":{"alt":[{"stem":"「나」를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"ㄴ을 먼저 쓰고 ㅏ를 써요","correct":true},{"t":"ㅏ를 먼저 쓰고 ㄴ을 써요","mis":"K1-1-u1-X12"},{"t":"ㅏ의 짧은 획을 가장 먼저 써요","mis":"K1-1-u1-X12"}],"explanation":["자음자를 먼저, 모음자를 나중에 써요.","ㅏ는 긴 세로획 다음에 짧은 획.","자음자 먼저."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_basic#7','kor',1,1,'u1','L07','g1_1_kor_u1_L07_basic','lesson_basic','K1-1-u1-C5',2,'mc','auto','한글 놀이에서 배운 대로 연필을 바르게 잡는 방법은 어느 것인가요?',ARRAY['K1-1-u1-X11']::text[],true,'{"seq":7,"concept":"K1-1-u1-C5","difficulty":2,"kind":"mc","stem":"한글 놀이에서 배운 대로 연필을 바르게 잡는 방법은 어느 것인가요?","options":[{"t":"엄지와 집게손가락으로 잡고 가운뎃손가락으로 받쳐요","correct":true},{"t":"주먹으로 연필을 꽉 쥐어요","mis":"K1-1-u1-X11"},{"t":"연필 맨 끝만 살짝 잡아요","mis":"K1-1-u1-X11"}],"explanation":["세 손가락으로 잡고 받쳐야 글씨가 바르게 써져요.","주먹으로 쥐거나 끝만 잡으면 글씨가 흔들려요.","바르게 잡고, 바르게 앉아요."],"asset":{"type":"scene","icon":"✏️"},"variant_rule":{"alt":[{"stem":"글씨를 쓸 때 연필을 잡지 않은 다른 손은 어떻게 하나요?","options":[{"t":"공책을 살며시 눌러요","correct":true},{"t":"무릎 위에 올려 둬요","mis":"K1-1-u1-X11"},{"t":"턱을 괴어요","mis":"K1-1-u1-X10"}],"explanation":["다른 손으로 공책을 눌러야 공책이 움직이지 않아요.","무릎에 두거나 턱을 괴면 바른 자세가 아니에요.","쥔 손, 누른 손."],"asset":{"type":"scene","icon":"✍️"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_basic#8','kor',1,1,'u1','L07','g1_1_kor_u1_L07_basic','lesson_basic','K1-1-u1-C2',2,'mc','auto','ㄴ + ㅗ 는 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X06']::text[],true,'{"seq":8,"kind":"mc","stem":"ㄴ + ㅗ 는 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㄴ","v":"ㅗ","s":null},"options":[{"t":"노","correct":true},{"t":"누","mis":"K1-1-u1-X02"},{"t":"나","mis":"K1-1-u1-X06"}],"explanation":["자음자 ㄴ과 모음자 ㅗ가 만나면 「노」예요.","ㅗ는 가로로 길어서 자음자 아래에 쌓여요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":2,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅗ","ㅜ","ㅏ"],"mis":{"flip":"X02","rot":"X06","cons":"X04"},"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_basic#9','kor',1,1,'u1','L07','g1_1_kor_u1_L07_basic','lesson_basic','K1-1-u1-C5',2,'error','auto','하준이가 읽기 자세를 점검했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_basic#10','kor',1,1,'u1','L07','g1_1_kor_u1_L07_basic','lesson_basic','K1-1-u1-C5',3,'mc','auto','모음자 ㅗ를 쓰는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u1-X12']::text[],true,'{"seq":10,"concept":"K1-1-u1-C5","difficulty":3,"kind":"mc","stem":"모음자 ㅗ를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"짧은 세로획을 먼저, 긴 가로획을 나중에 그어요","correct":true},{"t":"긴 가로획을 먼저, 짧은 세로획을 나중에 그어요","mis":"K1-1-u1-X12"},{"t":"긴 가로획을 오른쪽에서 왼쪽으로 그어요","mis":"K1-1-u1-X12"}],"explanation":["ㅗ는 위의 짧은 세로획부터.","그다음 긴 가로획을 왼쪽에서 오른쪽으로.","위에서 아래로."],"variant_rule":{"alt":[{"stem":"모음자 ㅜ를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"긴 가로획을 먼저, 짧은 세로획을 나중에 그어요","correct":true},{"t":"짧은 세로획을 먼저, 긴 가로획을 나중에 그어요","mis":"K1-1-u1-X12"},{"t":"짧은 세로획을 아래에서 위로 그어요","mis":"K1-1-u1-X12"}],"explanation":["ㅜ는 위의 긴 가로획부터.","그다음 짧은 세로획을 위에서 아래로.","위에서 아래로."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_challenge#1','kor',1,1,'u1','L07','g1_1_kor_u1_L07_challenge','lesson_challenge','K1-1-u1-C5',2,'mc','auto','또박또박 읽기로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u1-X15']::text[],false,'{"seq":1,"concept":"K1-1-u1-C5","difficulty":2,"kind":"mc","stem":"또박또박 읽기로 알맞은 것은 어느 것인가요?","options":[{"t":"글자 하나하나를 정확한 소리로 읽어요","correct":true},{"t":"그림을 보고 어떤 낱말일지 짐작해 읽어요","mis":"K1-1-u1-X15"},{"t":"빨리 읽으려고 글자를 건너뛰어요","mis":"K1-1-u1-X15"}],"explanation":["글자마다 정확한 소리로.","짐작하거나 건너뛰면 틀리게 읽어요.","손가락으로 짚으며 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_challenge#2','kor',1,1,'u1','L07','g1_1_kor_u1_L07_challenge','lesson_challenge','K1-1-u1-C2',2,'mc','auto','자음자 ㄱ과 모음자 ㅓ가 만나면 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":2,"kind":"mc","stem":"자음자 ㄱ과 모음자 ㅓ가 만나면 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㄱ","v":"ㅓ","s":null,"lay":true},"options":[{"t":"거","correct":true},{"t":"가","mis":"K1-1-u1-X02"},{"t":"겨","mis":"K1-1-u1-X03"}],"explanation":["자음자 ㄱ과 모음자 ㅓ가 만나면 「거」예요.","ㅓ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":2,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅣ"],"mis":{"flip":"X02","stroke":"X03","cons":"X04"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_challenge#3','kor',1,1,'u1','L07','g1_1_kor_u1_L07_challenge','lesson_challenge','K1-1-u1-C5',3,'ox','auto','ㅜ를 쓸 때는 긴 가로획을 먼저 긋고 짧은 세로획을 나중에 그어요.',ARRAY['K1-1-u1-X12']::text[],true,'{"seq":3,"concept":"K1-1-u1-C5","difficulty":3,"kind":"ox","stem":"ㅜ를 쓸 때는 긴 가로획을 먼저 긋고 짧은 세로획을 나중에 그어요.","answer":"O","reason_options":[{"t":"위에 있는 가로획부터 쓰고 그 아래로 세로획이 내려오니까","correct":true},{"t":"짧은 획은 언제나 먼저 쓰니까","mis":"K1-1-u1-X12"}],"mis":"K1-1-u1-X12","explanation":["ㅜ: 가로획 → 세로획.","위에서 아래로 써요.","획순은 「위에서 아래로」."],"variant_rule":{"alt":[{"stem":"ㅗ를 쓸 때는 긴 가로획을 먼저 긋고 짧은 세로획을 나중에 그어요.","answer":"X","reason_options":[{"t":"ㅗ는 위에 있는 짧은 세로획을 먼저 쓰니까","correct":true},{"t":"긴 획은 언제나 먼저 쓰니까","mis":"K1-1-u1-X12"}],"explanation":["ㅗ: 세로획 → 가로획.","위에서 아래로 써요.","위에 있는 획부터."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_challenge#4','kor',1,1,'u1','L07','g1_1_kor_u1_L07_challenge','lesson_challenge','K1-1-u1-C5',3,'mc','auto','「무」를 쓰는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u1-X12','K1-1-u1-X05']::text[],true,'{"seq":4,"concept":"K1-1-u1-C5","difficulty":3,"kind":"mc","stem":"「무」를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"ㅁ을 위에 먼저 쓰고, 그 아래에 ㅜ를 써요","correct":true},{"t":"ㅜ를 먼저 쓰고 그 위에 ㅁ을 써요","mis":"K1-1-u1-X12"},{"t":"ㅁ을 쓰고 그 오른쪽에 ㅜ를 써요","mis":"K1-1-u1-X05"}],"explanation":["자음자 ㅁ을 먼저 위쪽에.","ㅜ는 가로로 길어서 아래에.","자음자 먼저, 자리도 바르게."],"variant_rule":{"alt":[{"stem":"「보」를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"ㅂ을 위에 먼저 쓰고, 그 아래에 ㅗ를 써요","correct":true},{"t":"ㅗ를 먼저 쓰고 그 위에 ㅂ을 써요","mis":"K1-1-u1-X12"},{"t":"ㅂ을 쓰고 그 오른쪽에 ㅗ를 써요","mis":"K1-1-u1-X05"}],"explanation":["자음자 ㅂ을 먼저 위쪽에.","ㅗ는 가로로 길어서 아래에.","자음자 먼저, 자리도 바르게."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
