INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_challenge#7','kor',1,1,'u1','L07','g1_1_kor_u1_L07_challenge','lesson_challenge','K1-1-u1-C7',3,'mc','auto','글자 카드 「모자」를 또박또박 바르게 읽은 것은 어느 것인가요?',ARRAY['K1-1-u1-X02','K1-1-u1-X06']::text[],true,'{"seq":7,"concept":"K1-1-u1-C7","difficulty":3,"kind":"mc","stem":"글자 카드 「모자」를 또박또박 바르게 읽은 것은 어느 것인가요?","options":[{"t":"모 · 자","correct":true},{"t":"머 · 자","mis":"K1-1-u1-X02"},{"t":"마 · 자","mis":"K1-1-u1-X06"}],"explanation":["ㅁ 아래에 ㅗ — 「모」, ㅈ 옆에 ㅏ — 「자」.","ㅓ나 ㅏ로 읽으면 모음자를 잘못 본 거예요.","글자마다 모음자를 보고 읽어요."],"asset":{"type":"scene","icon":"🎩"},"variant_rule":{"alt":[{"stem":"글자 카드 「두부」를 또박또박 바르게 읽은 것은 어느 것인가요?","options":[{"t":"두 · 부","correct":true},{"t":"도 · 부","mis":"K1-1-u1-X02"},{"t":"더 · 부","mis":"K1-1-u1-X06"}],"explanation":["ㄷ 아래에 ㅜ — 「두」.","ㅗ나 ㅓ로 읽으면 모음자를 잘못 본 거예요.","글자마다 모음자를 보고 읽어요."],"asset":{"type":"scene","icon":"🍲"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_challenge#8','kor',1,1,'u1','L07','g1_1_kor_u1_L07_challenge','lesson_challenge','K1-1-u1-C5',4,'mc','auto','「소」를 쓰는 차례로 바른 것은 어느 것인가요?',ARRAY['K1-1-u1-X12']::text[],true,'{"seq":8,"concept":"K1-1-u1-C5","difficulty":4,"kind":"mc","stem":"「소」를 쓰는 차례로 바른 것은 어느 것인가요?","options":[{"t":"ㅅ → ㅗ의 짧은 세로획 → ㅗ의 긴 가로획","correct":true},{"t":"ㅗ의 긴 가로획 → ㅅ → ㅗ의 짧은 세로획","mis":"K1-1-u1-X12"},{"t":"ㅅ → ㅗ의 긴 가로획 → ㅗ의 짧은 세로획","mis":"K1-1-u1-X12"}],"explanation":["자음자 ㅅ을 먼저 써요.","ㅗ는 짧은 세로획, 긴 가로획 차례.","자음자 먼저, 위에서 아래로."],"variant_rule":{"alt":[{"stem":"「누」를 쓰는 차례로 바른 것은 어느 것인가요?","options":[{"t":"ㄴ → ㅜ의 긴 가로획 → ㅜ의 짧은 세로획","correct":true},{"t":"ㅜ의 짧은 세로획 → ㄴ → ㅜ의 긴 가로획","mis":"K1-1-u1-X12"},{"t":"ㄴ → ㅜ의 짧은 세로획 → ㅜ의 긴 가로획","mis":"K1-1-u1-X12"}],"explanation":["자음자 ㄴ을 먼저 써요.","ㅜ는 긴 가로획, 짧은 세로획 차례.","자음자 먼저, 위에서 아래로."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_challenge#9','kor',1,1,'u1','L07','g1_1_kor_u1_L07_challenge','lesson_challenge','K1-1-u1-C5',4,'essay','teacher','바른 자세로 글씨를 써야 하는 까닭을 두 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u1-C5","difficulty":4,"kind":"essay","stem":"바른 자세로 글씨를 써야 하는 까닭을 두 가지 쓰세요.","answer_guide":{"answer":"예: 바른 자세로 쓰면 글씨가 반듯하게 써져요. 오래 써도 허리와 눈이 덜 아파요. — 글씨(반듯함·알아보기 쉬움)와 몸(허리·눈·손)에 대한 까닭을 하나씩 대면 맞아요.","scoring_points":["글씨가 반듯해진다는 까닭이 있는가","몸(허리·눈·손)이 편하다는 까닭이 있는가","두 가지를 서로 다르게 썼는가"]},"explanation":["글씨가 반듯해져요.","몸이 덜 힘들어요.","까닭 두 가지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_challenge#10','kor',1,1,'u1','L07','g1_1_kor_u1_L07_challenge','lesson_challenge','K1-1-u1-C5',4,'mc','auto','또박또박 읽기를 돕는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u1-X15','K1-1-u1-X10']::text[],false,'{"seq":10,"concept":"K1-1-u1-C5","difficulty":4,"kind":"mc","stem":"또박또박 읽기를 돕는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"손가락으로 글자를 하나씩 짚으며 읽어요","correct":true},{"t":"그림만 보고 내용을 짐작해 말해요","mis":"K1-1-u1-X15"},{"t":"책을 눈 가까이 대고 빨리 읽어요","mis":"K1-1-u1-X10"}],"explanation":["짚으며 읽으면 글자를 빠뜨리지 않아요.","짐작하거나 바짝 대고 빨리 읽으면 틀려요.","하나씩 짚기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L09_basic#1','kor',1,1,'u1','L09','g1_1_kor_u1_L09_basic','lesson_basic','K1-1-u1-C6',1,'mc','auto','「새」에서 모음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X13']::text[],true,'{"seq":1,"kind":"mc","stem":"「새」에서 모음자는 어느 것인가요?","asset":{"type":"jamo","s":"새","eq":false,"lay":"blank"},"options":[{"t":"ㅐ","correct":true},{"t":"ㅅ","mis":"K1-1-u1-X01"},{"t":"ㅔ","mis":"K1-1-u1-X13"}],"explanation":["「새」는 자음자 ㅅ과 모음자 ㅐ가 만난 글자예요.","모음자는 ㅐ예요 — 오른쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C6","difficulty":1,"variant_rule":{"jamo":{"ask":"vow","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅐ","ㅔ","ㅒ","ㅖ"],"mis":{"role":"X01","ae":"X13"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L09_basic#2','kor',1,1,'u1','L09','g1_1_kor_u1_L09_basic','lesson_basic','K1-1-u1-C6',1,'mc','auto','「과」에서 모음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X14']::text[],true,'{"seq":2,"kind":"mc","stem":"「과」에서 모음자는 어느 것인가요?","asset":{"type":"jamo","s":"과","eq":false,"lay":"blank"},"options":[{"t":"ㅘ","correct":true},{"t":"ㄱ","mis":"K1-1-u1-X01"},{"t":"ㅗ","mis":"K1-1-u1-X14"}],"explanation":["「과」는 자음자 ㄱ과 모음자 ㅘ가 만난 글자예요.","모음자는 ㅘ예요 — 아래와 오른쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C6","difficulty":1,"variant_rule":{"jamo":{"ask":"vow","cons":["ㄱ","ㅎ","ㅈ","ㄷ","ㅅ"],"vows":["ㅘ","ㅝ","ㅚ","ㅟ","ㅙ","ㅢ"],"mis":{"role":"X01","comb":"X14"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L09_basic#3','kor',1,1,'u1','L09','g1_1_kor_u1_L09_basic','lesson_basic','K1-1-u1-C6',1,'mc','auto','자음자 ㄱ과 모음자 ㅐ가 만나면 어떤 글자가 되나요?',ARRAY['K1-1-u1-X13']::text[],true,'{"seq":3,"kind":"mc","stem":"자음자 ㄱ과 모음자 ㅐ가 만나면 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㄱ","v":"ㅐ","s":null},"options":[{"t":"개","correct":true},{"t":"게","mis":"K1-1-u1-X13"},{"t":"걔","mis":"K1-1-u1-X13"}],"explanation":["자음자 ㄱ과 모음자 ㅐ가 만나면 「개」예요.","ㅐ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C6","difficulty":1,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅐ","ㅔ","ㅒ","ㅖ"],"mis":{"ae":"X13","cons":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L09_basic#4','kor',1,1,'u1','L09','g1_1_kor_u1_L09_basic','lesson_basic','K1-1-u1-C6',1,'mc','auto','두 모음자가 합쳐져 만들어진 모음자는 어느 것인가요?',ARRAY['K1-1-u1-X03','K1-1-u1-X14']::text[],true,'{"seq":4,"concept":"K1-1-u1-C6","difficulty":1,"kind":"mc","stem":"두 모음자가 합쳐져 만들어진 모음자는 어느 것인가요?","options":[{"t":"ㅘ","correct":true},{"t":"ㅑ","mis":"K1-1-u1-X03"},{"t":"ㅗ","mis":"K1-1-u1-X14"}],"explanation":["ㅘ는 ㅗ와 ㅏ가 합쳐진 모음자예요.","ㅑ는 짧은 획이 둘인 모음자, ㅗ는 한쪽만이에요.","두 모음자가 붙었나 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 두 모음자가 합쳐져 만들어진 모음자는 어느 것인가요?","options":[{"t":"ㅝ","correct":true},{"t":"ㅕ","mis":"K1-1-u1-X03"},{"t":"ㅜ","mis":"K1-1-u1-X14"}],"explanation":["ㅝ는 ㅜ와 ㅓ가 합쳐진 모음자예요.","ㅕ는 짧은 획이 둘인 모음자, ㅜ는 한쪽만이에요.","두 모음자가 붙었나 봐요."]},{"stem":"이번에는 다른 보기예요. 두 모음자가 합쳐져 만들어진 모음자는 어느 것인가요?","options":[{"t":"ㅢ","correct":true},{"t":"ㅠ","mis":"K1-1-u1-X03"},{"t":"ㅡ","mis":"K1-1-u1-X14"}],"explanation":["ㅢ는 ㅡ와 ㅣ가 합쳐진 모음자예요.","ㅠ는 짧은 획이 둘인 모음자, ㅡ는 한쪽만이에요.","두 모음자가 붙었나 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L09_basic#5','kor',1,1,'u1','L09','g1_1_kor_u1_L09_basic','lesson_basic','K1-1-u1-C6',2,'mc','auto','자음자 ㅇ과 모음자 ㅟ가 만나면 어떤 글자가 되나요?',ARRAY['K1-1-u1-X14']::text[],true,'{"seq":5,"kind":"mc","stem":"자음자 ㅇ과 모음자 ㅟ가 만나면 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㅇ","v":"ㅟ","s":null,"lay":true},"options":[{"t":"위","correct":true},{"t":"우","mis":"K1-1-u1-X14"},{"t":"이","mis":"K1-1-u1-X14"}],"explanation":["자음자 ㅇ과 모음자 ㅟ가 만나면 「위」예요.","ㅟ는 자음자의 아래와 오른쪽을 함께 감싸요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C6","difficulty":2,"variant_rule":{"jamo":{"ask":"build","cons":["ㅇ","ㄱ","ㅈ","ㅎ","ㄷ"],"vows":["ㅘ","ㅝ","ㅚ","ㅟ","ㅙ","ㅢ"],"mis":{"comb":"X14","cons":"X04"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
