INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L09_basic#7','kor',1,1,'u1','L09','g1_1_kor_u1_L09_basic','lesson_basic','K1-1-u1-C8',2,'match','auto','모음자와 그 이름을 바르게 이으세요.','{}'::text[],true,'{"seq":7,"concept":"K1-1-u1-C8","difficulty":2,"kind":"match","stem":"모음자와 그 이름을 바르게 이으세요.","pairs":[{"l":"ㅐ","r":"애"},{"l":"ㅔ","r":"에"},{"l":"ㅚ","r":"외"}],"mis":"K1-1-u1-X17","explanation":["모음자의 이름은 그 모음자의 소리와 같아요.","ㅐ는 「애」, ㅔ는 「에」, ㅚ는 「외」예요.","거울을 보며 소리 내어 말해 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모음자와 그 이름을 바르게 이으세요.","pairs":[{"l":"ㅟ","r":"위"},{"l":"ㅘ","r":"와"},{"l":"ㅙ","r":"왜"}],"explanation":["모음자의 이름은 그 모음자의 소리와 같아요.","ㅟ는 「위」, ㅘ는 「와」, ㅙ는 「왜」예요.","거울을 보며 소리 내어 말해 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L09_basic#8','kor',1,1,'u1','L09','g1_1_kor_u1_L09_basic','lesson_basic','K1-1-u1-C6',2,'match','auto','모음자와 그 모음자가 들어간 낱말을 바르게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"K1-1-u1-C6","difficulty":2,"kind":"match","stem":"모음자와 그 모음자가 들어간 낱말을 바르게 이으세요.","pairs":[{"l":"ㅘ","r":"기와"},{"l":"ㅙ","r":"돼지"},{"l":"ㅚ","r":"참외"}],"mis":"K1-1-u1-X14","explanation":["기와의 「와」에 ㅘ, 돼지의 「돼」에 ㅙ가 있어요.","참외의 「외」에 ㅚ가 있어요.","합친 모음자는 두 모음자를 다 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모음자와 그 모음자가 들어간 낱말을 바르게 이으세요.","pairs":[{"l":"ㅝ","r":"태권도"},{"l":"ㅟ","r":"바위"},{"l":"ㅢ","r":"의자"}],"explanation":["태권도의 「권」에 ㅝ, 바위의 「위」에 ㅟ가 있어요.","의자의 「의」에 ㅢ가 있어요.","합친 모음자는 두 모음자를 다 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L09_basic#9','kor',1,1,'u1','L09','g1_1_kor_u1_L09_basic','lesson_basic','K1-1-u1-C6',2,'ox','auto','「의자」의 「의」에는 모음자 ㅢ가 들어 있어요.',ARRAY['K1-1-u1-X14']::text[],true,'{"seq":9,"concept":"K1-1-u1-C6","difficulty":2,"kind":"ox","stem":"「의자」의 「의」에는 모음자 ㅢ가 들어 있어요.","answer":"O","reason_options":[{"t":"「의」는 자음자 ㅇ과 모음자 ㅢ가 만난 글자니까","correct":true},{"t":"「의」는 모음자 ㅡ 하나만 있는 글자니까","mis":"K1-1-u1-X14"}],"mis":"K1-1-u1-X14","explanation":["의 = ㅇ + ㅢ.","ㅢ는 ㅡ와 ㅣ가 합쳐진 모음자예요.","합친 모음자는 둘 다 봐요."],"asset":{"type":"scene","icon":"🪑"},"variant_rule":{"alt":[{"stem":"「사과」의 「과」에는 모음자 ㅏ만 들어 있어요.","answer":"X","reason_options":[{"t":"「과」의 모음자는 ㅗ와 ㅏ가 합쳐진 ㅘ니까","correct":true},{"t":"ㅗ는 자음자니까","mis":"K1-1-u1-X14"}],"explanation":["과 = ㄱ + ㅘ.","ㅘ는 ㅗ와 ㅏ가 합쳐졌어요.","합친 모음자는 둘 다 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L09_basic#10','kor',1,1,'u1','L09','g1_1_kor_u1_L09_basic','lesson_basic','K1-1-u1-C6',3,'mc','auto','「돼」에서 모음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X14']::text[],true,'{"seq":10,"kind":"mc","stem":"「돼」에서 모음자는 어느 것인가요?","asset":{"type":"jamo","s":"돼","eq":false,"lay":"blank"},"options":[{"t":"ㅙ","correct":true},{"t":"ㄷ","mis":"K1-1-u1-X01"},{"t":"ㅗ","mis":"K1-1-u1-X14"}],"explanation":["「돼」는 자음자 ㄷ과 모음자 ㅙ가 만난 글자예요.","모음자는 ㅙ예요 — 아래와 오른쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C6","difficulty":3,"variant_rule":{"jamo":{"ask":"vow","cons":["ㄷ","ㄱ","ㅎ","ㅈ","ㅅ"],"vows":["ㅘ","ㅝ","ㅚ","ㅟ","ㅙ","ㅢ"],"mis":{"role":"X01","comb":"X14"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L09_challenge#1','kor',1,1,'u1','L09','g1_1_kor_u1_L09_challenge','lesson_challenge','K1-1-u1-C6',2,'mc','auto','자음자 ㄱ과 모음자 ㅘ가 만나면 어떤 글자가 되나요?',ARRAY['K1-1-u1-X14']::text[],true,'{"seq":1,"kind":"mc","stem":"자음자 ㄱ과 모음자 ㅘ가 만나면 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㄱ","v":"ㅘ","s":null},"options":[{"t":"과","correct":true},{"t":"고","mis":"K1-1-u1-X14"},{"t":"가","mis":"K1-1-u1-X14"}],"explanation":["자음자 ㄱ과 모음자 ㅘ가 만나면 「과」예요.","ㅘ는 자음자의 아래와 오른쪽을 함께 감싸요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C6","difficulty":2,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅘ","ㅝ","ㅚ","ㅟ","ㅙ","ㅢ"],"mis":{"comb":"X14","cons":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
