INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L09_challenge#3','kor',1,1,'u1','L09','g1_1_kor_u1_L09_challenge','lesson_challenge','K1-1-u1-C6',3,'error','auto','준서가 「시계」를 「시게」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u1-X13','K1-1-u1-X04']::text[],true,'{"seq":3,"concept":"K1-1-u1-C6","difficulty":3,"kind":"error","stem":"준서가 「시계」를 「시게」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"ㅖ 대신 ㅔ를 썼어요","correct":true,"mis_target":"K1-1-u1-X13"},{"t":"ㅅ 대신 ㅈ을 써야 해요","mis":"K1-1-u1-X04"},{"t":"「계」는 「개」라고 써야 해요","mis":"K1-1-u1-X13"}],"explanation":["「계」의 모음자는 ㅖ예요.","ㅔ와 ㅖ는 짧은 획 하나가 달라요.","모음자 모양을 견주어요."],"asset":{"type":"scene","icon":"⏰"},"variant_rule":{"alt":[{"stem":"하린이가 「무지개」를 「무지게」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"ㅐ 대신 ㅔ를 썼어요","correct":true,"mis_target":"K1-1-u1-X13"},{"t":"ㅈ 대신 ㅊ을 써야 해요","mis":"K1-1-u1-X04"},{"t":"「개」는 「걔」라고 써야 해요","mis":"K1-1-u1-X13"}],"explanation":["「개」의 모음자는 ㅐ예요.","ㅐ와 ㅔ는 모양이 달라요.","모음자 모양을 견주어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L09_challenge#4','kor',1,1,'u1','L09','g1_1_kor_u1_L09_challenge','lesson_challenge','K1-1-u1-C6',3,'mc','auto','모음자 ㅐ는 어떤 두 모음자가 붙은 모양일까요?',ARRAY['K1-1-u1-X13','K1-1-u1-X14']::text[],true,'{"seq":4,"concept":"K1-1-u1-C6","difficulty":3,"kind":"mc","stem":"모음자 ㅐ는 어떤 두 모음자가 붙은 모양일까요?","options":[{"t":"ㅏ와 ㅣ","correct":true},{"t":"ㅓ와 ㅣ","mis":"K1-1-u1-X13"},{"t":"ㅗ와 ㅣ","mis":"K1-1-u1-X14"}],"explanation":["ㅏ 옆에 ㅣ가 붙으면 ㅐ.","ㅓ와 ㅣ는 ㅔ, ㅗ와 ㅣ는 ㅚ예요.","앞의 모음자를 먼저 찾아요."],"variant_rule":{"alt":[{"stem":"모음자 ㅔ는 어떤 두 모음자가 붙은 모양일까요?","options":[{"t":"ㅓ와 ㅣ","correct":true},{"t":"ㅏ와 ㅣ","mis":"K1-1-u1-X13"},{"t":"ㅜ와 ㅣ","mis":"K1-1-u1-X14"}],"explanation":["ㅓ 옆에 ㅣ가 붙으면 ㅔ.","ㅏ와 ㅣ는 ㅐ, ㅜ와 ㅣ는 ㅟ예요.","앞의 모음자를 먼저 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L09_challenge#5','kor',1,1,'u1','L09','g1_1_kor_u1_L09_challenge','lesson_challenge','K1-1-u1-C8',3,'mc','auto','「병원」의 「원」에 들어 있는 모음자 ㅝ의 이름은 무엇인가요?',ARRAY['K1-1-u1-X17','K1-1-u1-X14']::text[],true,'{"seq":5,"concept":"K1-1-u1-C8","difficulty":3,"kind":"mc","stem":"「병원」의 「원」에 들어 있는 모음자 ㅝ의 이름은 무엇인가요?","options":[{"t":"워","correct":true},{"t":"와","mis":"K1-1-u1-X17"},{"t":"우","mis":"K1-1-u1-X14"}],"explanation":["ㅝ의 이름은 「워」예요.","「와」는 ㅘ의 이름이고, 「우」는 ㅜ만 본 거예요.","모음자 이름은 그 소리 그대로."],"asset":{"type":"scene","icon":"🏥"},"variant_rule":{"alt":[{"stem":"「의사」의 「의」에 들어 있는 모음자 ㅢ의 이름은 무엇인가요?","options":[{"t":"의","correct":true},{"t":"이","mis":"K1-1-u1-X17"},{"t":"으","mis":"K1-1-u1-X14"}],"explanation":["ㅢ의 이름은 「의」예요.","「이」는 ㅣ의 이름이고, 「으」는 ㅡ만 본 거예요.","모음자 이름은 그 소리 그대로."],"asset":{"type":"scene","icon":"🧑‍⚕️"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L09_challenge#6','kor',1,1,'u1','L09','g1_1_kor_u1_L09_challenge','lesson_challenge','K1-1-u1-C6',3,'mc','auto','모음자 ㅢ가 들어 있는 낱말은 어느 것인가요?',ARRAY['K1-1-u1-X14']::text[],true,'{"seq":6,"concept":"K1-1-u1-C6","difficulty":3,"kind":"mc","stem":"모음자 ㅢ가 들어 있는 낱말은 어느 것인가요?","options":[{"t":"의사","correct":true},{"t":"이사","mis":"K1-1-u1-X14"},{"t":"스키","mis":"K1-1-u1-X14"}],"explanation":["「의」는 ㅇ과 ㅢ가 만난 글자예요.","「이사」의 「이」는 ㅣ만, 「스키」는 ㅡ와 ㅣ가 다른 글자에 따로 있어요.","한 글자 안에 ㅡ와 ㅣ가 함께."],"variant_rule":{"alt":[{"stem":"모음자 ㅟ가 들어 있는 낱말은 어느 것인가요?","options":[{"t":"가위","correct":true},{"t":"가이","mis":"K1-1-u1-X14"},{"t":"구이","mis":"K1-1-u1-X14"}],"explanation":["「위」는 ㅇ과 ㅟ가 만난 글자예요.","「가이」는 ㅣ만, 「구이」는 ㅜ와 ㅣ가 다른 글자에 따로 있어요.","한 글자 안에 ㅜ와 ㅣ가 함께."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L09_challenge#7','kor',1,1,'u1','L09','g1_1_kor_u1_L09_challenge','lesson_challenge','K1-1-u1-C6',3,'mc','auto','ㄷ + ㅙ 는 어떤 글자가 되나요?',ARRAY['K1-1-u1-X14']::text[],true,'{"seq":7,"kind":"mc","stem":"ㄷ + ㅙ 는 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㄷ","v":"ㅙ","s":null},"options":[{"t":"돼","correct":true},{"t":"도","mis":"K1-1-u1-X14"},{"t":"대","mis":"K1-1-u1-X14"}],"explanation":["자음자 ㄷ과 모음자 ㅙ가 만나면 「돼」예요.","ㅙ는 자음자의 아래와 오른쪽을 함께 감싸요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C6","difficulty":3,"variant_rule":{"jamo":{"ask":"build","cons":["ㄷ","ㄱ","ㅎ","ㅈ","ㅅ"],"vows":["ㅙ","ㅞ","ㅚ","ㅟ","ㅘ","ㅝ"],"mis":{"comb":"X14","cons":"X04"},"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L09_challenge#8','kor',1,1,'u1','L09','g1_1_kor_u1_L09_challenge','lesson_challenge','K1-1-u1-C6',4,'mc','auto','모음자 하나만 바꾸어 「개」를 「게」로 만들었어요. 무엇을 바꾸었나요?',ARRAY['K1-1-u1-X04','K1-1-u1-X13']::text[],true,'{"seq":8,"concept":"K1-1-u1-C6","difficulty":4,"kind":"mc","stem":"모음자 하나만 바꾸어 「개」를 「게」로 만들었어요. 무엇을 바꾸었나요?","options":[{"t":"ㅐ를 ㅔ로","correct":true},{"t":"ㄱ을 ㅋ으로","mis":"K1-1-u1-X04"},{"t":"ㅐ를 ㅒ로","mis":"K1-1-u1-X13"}],"explanation":["개(ㄱ+ㅐ) → 게(ㄱ+ㅔ).","자음자는 그대로, 모음자만 바뀌었어요.","바뀐 자리만 찾아요."],"variant_rule":{"alt":[{"stem":"모음자 하나만 바꾸어 「배」를 「베」로 만들었어요. 무엇을 바꾸었나요?","options":[{"t":"ㅐ를 ㅔ로","correct":true},{"t":"ㅂ을 ㅍ으로","mis":"K1-1-u1-X04"},{"t":"ㅐ를 ㅒ로","mis":"K1-1-u1-X13"}],"explanation":["배(ㅂ+ㅐ) → 베(ㅂ+ㅔ).","자음자는 그대로, 모음자만 바뀌었어요.","바뀐 자리만 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L09_challenge#9','kor',1,1,'u1','L09','g1_1_kor_u1_L09_challenge','lesson_challenge','K1-1-u1-C6',4,'essay','teacher','「사과」의 「과」와 「사가」의 「가」는 어떻게 다른지 모음자로 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u1-C6","difficulty":4,"kind":"essay","stem":"「사과」의 「과」와 「사가」의 「가」는 어떻게 다른지 모음자로 설명해 보세요.","answer_guide":{"answer":"예: 「과」는 ㄱ에 ㅗ와 ㅏ가 합쳐진 ㅘ가 붙었고, 「가」는 ㄱ에 ㅏ만 붙었어요. 그래서 「과」에는 ㅗ가 더 있어요. — 두 글자의 모음자(ㅘ와 ㅏ)를 바르게 말하고, ㅘ가 ㅗ+ㅏ라는 것을 말하면 맞아요.","scoring_points":["「과」의 모음자를 ㅘ라고 말했는가","「가」의 모음자를 ㅏ라고 말했는가","ㅘ가 ㅗ와 ㅏ가 합쳐진 것이라고 말했는가"]},"explanation":["과 = ㄱ + ㅘ.","가 = ㄱ + ㅏ.","ㅘ = ㅗ + ㅏ."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L09_challenge#10','kor',1,1,'u1','L09','g1_1_kor_u1_L09_challenge','lesson_challenge','K1-1-u1-C6',4,'sa','auto','「외」에서 모음자를 쓰세요.','{}'::text[],true,'{"seq":10,"kind":"sa","stem":"「외」에서 모음자를 쓰세요.","asset":{"type":"jamo","s":"외","eq":false,"lay":"blank"},"answer":["ㅚ"],"explanation":["「외」는 자음자 ㅇ과 모음자 ㅚ가 만난 글자예요.","모음자는 ㅚ예요 — 아래와 오른쪽에 있어요.","글자를 둘로 나누어 모음자만 써요."],"concept":"K1-1-u1-C6","difficulty":4,"variant_rule":{"jamo":{"ask":"vow","cons":["ㅇ","ㄱ","ㅎ","ㅈ","ㅅ"],"vows":["ㅘ","ㅝ","ㅚ","ㅟ","ㅙ","ㅢ"],"mis":{"role":"X01","comb":"X14"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_basic#1','kor',1,1,'u1','L13','g1_1_kor_u1_L13_basic','lesson_basic','K1-1-u1-C2',1,'mc','auto','자음자 ㄴ과 모음자 ㅜ가 만나면 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":1,"kind":"mc","stem":"자음자 ㄴ과 모음자 ㅜ가 만나면 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㄴ","v":"ㅜ","s":null},"options":[{"t":"누","correct":true},{"t":"노","mis":"K1-1-u1-X02"},{"t":"뉴","mis":"K1-1-u1-X03"}],"explanation":["자음자 ㄴ과 모음자 ㅜ가 만나면 「누」예요.","ㅜ는 가로로 길어서 자음자 아래에 쌓여요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":1,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅗ","ㅜ"],"mis":{"flip":"X02","stroke":"X03","rot":"X06"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_basic#2','kor',1,1,'u1','L13','g1_1_kor_u1_L13_basic','lesson_basic','K1-1-u1-C7',1,'mc','auto','칠판의 자음자 ㄴ ㅂ 과 모음자 ㅣ ㅜ 가 들어간, 씻을 때 쓰는 물건은 어느 것인가요?',ARRAY['K1-1-u1-X09','K1-1-u1-X08']::text[],true,'{"seq":2,"concept":"K1-1-u1-C7","difficulty":1,"kind":"mc","stem":"칠판의 자음자 ㄴ ㅂ 과 모음자 ㅣ ㅜ 가 들어간, 씻을 때 쓰는 물건은 어느 것인가요?","options":[{"t":"비누","correct":true},{"t":"누비","mis":"K1-1-u1-X09"},{"t":"비니","mis":"K1-1-u1-X08"}],"explanation":["ㅂ+ㅣ = 비, ㄴ+ㅜ = 누 — 비누예요.","「누비」는 차례가 바뀌었고, 「비니」는 ㅜ를 보지 않았어요.","자음자와 모음자를 짝 지어 차례대로."],"asset":{"type":"scene","icon":"🧼"},"variant_rule":{"alt":[{"stem":"칠판의 자음자 ㄱ ㅈ 과 모음자 ㅏ ㅣ 가 들어간 보라색 채소는 어느 것인가요?","options":[{"t":"가지","correct":true},{"t":"지가","mis":"K1-1-u1-X09"},{"t":"가자","mis":"K1-1-u1-X08"}],"explanation":["ㄱ+ㅏ = 가, ㅈ+ㅣ = 지 — 가지예요.","「지가」는 차례가 바뀌었고, 「가자」는 ㅣ를 보지 않았어요.","자음자와 모음자를 짝 지어 차례대로."],"asset":{"type":"scene","icon":"🍆"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_basic#3','kor',1,1,'u1','L13','g1_1_kor_u1_L13_basic','lesson_basic','K1-1-u1-C7',1,'mc','auto','그림에 알맞은 낱말 카드는 어느 것인가요?',ARRAY['K1-1-u1-X09','K1-1-u1-X14']::text[],true,'{"seq":3,"concept":"K1-1-u1-C7","difficulty":1,"kind":"mc","stem":"그림에 알맞은 낱말 카드는 어느 것인가요?","options":[{"t":"사과","correct":true},{"t":"과사","mis":"K1-1-u1-X09"},{"t":"사가","mis":"K1-1-u1-X14"}],"explanation":["빨간 과일은 「사과」예요.","「과사」는 차례가 바뀌었고, 「사가」는 ㅘ를 ㅏ로 썼어요.","그림 뜻 + 차례 + 모음자."],"asset":{"type":"scene","icon":"🍎"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림에 알맞은 낱말 카드는 어느 것인가요?","options":[{"t":"키위","correct":true},{"t":"위키","mis":"K1-1-u1-X09"},{"t":"키이","mis":"K1-1-u1-X14"}],"explanation":["초록 속살 과일은 「키위」예요.","「위키」는 차례가 바뀌었고, 「키이」는 ㅟ를 ㅣ로 썼어요.","그림 뜻 + 차례 + 모음자."],"asset":{"type":"scene","icon":"🥝"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_basic#4','kor',1,1,'u1','L13','g1_1_kor_u1_L13_basic','lesson_basic','K1-1-u1-C1',1,'mc','auto','「후」에서 자음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X04']::text[],true,'{"seq":4,"kind":"mc","stem":"「후」에서 자음자는 어느 것인가요?","asset":{"type":"jamo","s":"후","eq":false,"lay":"blank"},"options":[{"t":"ㅎ","correct":true},{"t":"ㅜ","mis":"K1-1-u1-X01"},{"t":"ㅇ","mis":"K1-1-u1-X04"}],"explanation":["「후」는 자음자 ㅎ과 모음자 ㅜ가 만난 글자예요.","자음자는 ㅎ이에요 — 위쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C1","difficulty":1,"variant_rule":{"jamo":{"ask":"cons","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ"],"mis":{"role":"X01","cons":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_basic#5','kor',1,1,'u1','L13','g1_1_kor_u1_L13_basic','lesson_basic','K1-1-u1-C2',2,'ox','auto','낱말 알아맞히기 놀이를 할 때 모음자 카드를 다른 방향으로 돌려 놓아도 같은 글자가 돼요.',ARRAY['K1-1-u1-X06']::text[],true,'{"seq":5,"concept":"K1-1-u1-C2","difficulty":2,"kind":"ox","stem":"낱말 알아맞히기 놀이를 할 때 모음자 카드를 다른 방향으로 돌려 놓아도 같은 글자가 돼요.","answer":"X","reason_options":[{"t":"ㅗ를 돌리면 ㅜ가 되는 것처럼 다른 모음자가 되니까","correct":true},{"t":"모음자는 어느 방향이든 소리가 같으니까","mis":"K1-1-u1-X06"}],"mis":"K1-1-u1-X06","explanation":["ㅗ를 거꾸로 돌리면 ㅜ, 옆으로 돌리면 ㅏ가 돼요.","그래서 선생님이 보여 준 모습 그대로 두고 놀이해요.","카드는 돌리지 않아요."],"variant_rule":{"alt":[{"stem":"모음자 카드 ㅏ를 옆으로 돌려 놓으면 ㅗ처럼 보여요.","answer":"O","reason_options":[{"t":"ㅏ를 돌리면 짧은 획이 위로 가서 ㅗ 모양이 되니까","correct":true},{"t":"모음자는 돌려도 모양이 그대로니까","mis":"K1-1-u1-X06"}],"explanation":["ㅏ를 돌리면 ㅗ 모양이 돼요.","그래서 카드를 돌리지 않고 보이는 그대로 놓아요.","카드는 돌리지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_basic#6','kor',1,1,'u1','L13','g1_1_kor_u1_L13_basic','lesson_basic','K1-1-u1-C7',2,'mc','auto','글자 탐정 놀이 — 「거울」의 「거」와 「미로」의 「미」를 모으면 어떤 낱말이 될까요?',ARRAY['K1-1-u1-X09','K1-1-u1-X08']::text[],true,'{"seq":6,"concept":"K1-1-u1-C7","difficulty":2,"kind":"mc","stem":"글자 탐정 놀이 — 「거울」의 「거」와 「미로」의 「미」를 모으면 어떤 낱말이 될까요?","options":[{"t":"거미","correct":true},{"t":"미거","mis":"K1-1-u1-X09"},{"t":"거로","mis":"K1-1-u1-X08"}],"explanation":["거 + 미 → 거미예요.","「미거」는 차례가 바뀌었고, 「거로」는 다른 글자를 골랐어요.","찾을 글자를 차례대로 모아요."],"asset":{"type":"scene","icon":"🕷️"},"variant_rule":{"alt":[{"stem":"글자 탐정 놀이 — 「바다」의 「바」와 「지도」의 「지」를 모으면 어떤 낱말이 될까요?","options":[{"t":"바지","correct":true},{"t":"지바","mis":"K1-1-u1-X09"},{"t":"바도","mis":"K1-1-u1-X08"}],"explanation":["바 + 지 → 바지예요.","「지바」는 차례가 바뀌었고, 「바도」는 다른 글자를 골랐어요.","찾을 글자를 차례대로 모아요."],"asset":{"type":"scene","icon":"👖"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_basic#7','kor',1,1,'u1','L13','g1_1_kor_u1_L13_basic','lesson_basic','K1-1-u1-C7',2,'match','auto','모은 글자 카드와 만든 낱말을 바르게 이으세요.','{}'::text[],true,'{"seq":7,"concept":"K1-1-u1-C7","difficulty":2,"kind":"match","stem":"모은 글자 카드와 만든 낱말을 바르게 이으세요.","pairs":[{"l":"후 + 추","r":"후추"},{"l":"타 + 조","r":"타조"},{"l":"다 + 리 + 미","r":"다리미"}],"mis":"K1-1-u1-X09","explanation":["카드 차례 그대로 모아요.","후 → 추, 타 → 조, 다 → 리 → 미.","왼쪽 카드부터."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모은 글자 카드와 만든 낱말을 바르게 이으세요.","pairs":[{"l":"자 + 두","r":"자두"},{"l":"여 + 치","r":"여치"},{"l":"피 + 아 + 노","r":"피아노"}],"explanation":["카드 차례 그대로 모아요.","자 → 두, 여 → 치, 피 → 아 → 노.","왼쪽 카드부터."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_basic#8','kor',1,1,'u1','L13','g1_1_kor_u1_L13_basic','lesson_basic','K1-1-u1-C2',2,'mc','auto','자음자 ㅈ과 모음자 ㅏ가 만나면 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":8,"kind":"mc","stem":"자음자 ㅈ과 모음자 ㅏ가 만나면 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㅈ","v":"ㅏ","s":null,"lay":true},"options":[{"t":"자","correct":true},{"t":"저","mis":"K1-1-u1-X02"},{"t":"쟈","mis":"K1-1-u1-X03"}],"explanation":["자음자 ㅈ과 모음자 ㅏ가 만나면 「자」예요.","ㅏ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":2,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅣ"],"mis":{"flip":"X02","stroke":"X03","cons":"X04"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_basic#9','kor',1,1,'u1','L13','g1_1_kor_u1_L13_basic','lesson_basic','K1-1-u1-C7',2,'ox','auto','글자 카드 「누」와 「비」를 「누비」 차례로 모아도 「비누」가 돼요.',ARRAY['K1-1-u1-X09']::text[],true,'{"seq":9,"concept":"K1-1-u1-C7","difficulty":2,"kind":"ox","stem":"글자 카드 「누」와 「비」를 「누비」 차례로 모아도 「비누」가 돼요.","answer":"X","reason_options":[{"t":"모으는 차례가 바뀌면 다른 말이 되니까","correct":true},{"t":"같은 카드를 쓰면 차례는 상관없으니까","mis":"K1-1-u1-X09"}],"mis":"K1-1-u1-X09","explanation":["비누 ≠ 누비.","차례가 뜻을 바꿔요.","왼쪽부터 차례대로."],"variant_rule":{"alt":[{"stem":"글자 카드 「리」와 「다」를 「리다」 차례로 모아도 「다리」가 돼요.","answer":"X","reason_options":[{"t":"모으는 차례가 바뀌면 다른 말이 되니까","correct":true},{"t":"같은 카드를 쓰면 차례는 상관없으니까","mis":"K1-1-u1-X09"}],"explanation":["다리 ≠ 리다.","차례가 뜻을 바꿔요.","왼쪽부터 차례대로."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_basic#10','kor',1,1,'u1','L13','g1_1_kor_u1_L13_basic','lesson_basic','K1-1-u1-C7',3,'mc','auto','카드 ㅈ · ㅏ · ㄷ · ㅜ 네 장으로 만들 수 있는 과일 이름은 어느 것인가요?',ARRAY['K1-1-u1-X09','K1-1-u1-X02']::text[],true,'{"seq":10,"concept":"K1-1-u1-C7","difficulty":3,"kind":"mc","stem":"카드 ㅈ · ㅏ · ㄷ · ㅜ 네 장으로 만들 수 있는 과일 이름은 어느 것인가요?","options":[{"t":"자두","correct":true},{"t":"두자","mis":"K1-1-u1-X09"},{"t":"자도","mis":"K1-1-u1-X02"}],"explanation":["ㅈ+ㅏ = 자, ㄷ+ㅜ = 두 — 자두.","「두자」는 차례가 바뀌었고, 「자도」는 ㅜ를 ㅗ로 바꿨어요.","카드 모양 그대로, 차례대로."],"asset":{"type":"scene","icon":"🍑"},"variant_rule":{"alt":[{"stem":"카드 ㅌ · ㅏ · ㅈ · ㅗ 네 장으로 만들 수 있는 동물 이름은 어느 것인가요?","options":[{"t":"타조","correct":true},{"t":"조타","mis":"K1-1-u1-X09"},{"t":"타주","mis":"K1-1-u1-X02"}],"explanation":["ㅌ+ㅏ = 타, ㅈ+ㅗ = 조 — 타조.","「조타」는 차례가 바뀌었고, 「타주」는 ㅗ를 ㅜ로 바꿨어요.","카드 모양 그대로, 차례대로."],"asset":{"type":"scene","icon":"🐦"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_challenge#1','kor',1,1,'u1','L13','g1_1_kor_u1_L13_challenge','lesson_challenge','K1-1-u1-C7',2,'mc','auto','그림에 알맞은 낱말 카드는 어느 것인가요?',ARRAY['K1-1-u1-X13','K1-1-u1-X09']::text[],true,'{"seq":1,"concept":"K1-1-u1-C7","difficulty":2,"kind":"mc","stem":"그림에 알맞은 낱말 카드는 어느 것인가요?","options":[{"t":"조개","correct":true},{"t":"조게","mis":"K1-1-u1-X13"},{"t":"개조","mis":"K1-1-u1-X09"}],"explanation":["바닷가의 조개 — 「개」의 모음자는 ㅐ.","「조게」는 ㅐ를 ㅔ로 썼고, 「개조」는 차례가 바뀌었어요.","모음자와 차례 모두."],"asset":{"type":"scene","icon":"🐚"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림에 알맞은 낱말 카드는 어느 것인가요?","options":[{"t":"돼지","correct":true},{"t":"되지","mis":"K1-1-u1-X14"},{"t":"지돼","mis":"K1-1-u1-X09"}],"explanation":["꿀꿀 돼지 — 「돼」의 모음자는 ㅙ.","「되지」는 ㅙ를 ㅚ로 썼고, 「지돼」는 차례가 바뀌었어요.","모음자와 차례 모두."],"asset":{"type":"scene","icon":"🐷"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_challenge#2','kor',1,1,'u1','L13','g1_1_kor_u1_L13_challenge','lesson_challenge','K1-1-u1-C4',2,'mc','auto','음절표에서 ? 칸에 들어갈 글자는 무엇인가요?',ARRAY['K1-1-u1-X06','K1-1-u1-X07']::text[],true,'{"seq":2,"kind":"mc","stem":"음절표에서 ? 칸에 들어갈 글자는 무엇인가요?","asset":{"type":"syl_table","cons":["ㄱ","ㅋ","ㅌ"],"vows":["ㅏ","ㅗ","ㅣ"],"q":[1,1]},"options":[{"t":"코","correct":true},{"t":"카","mis":"K1-1-u1-X06"},{"t":"키","mis":"K1-1-u1-X07"}],"explanation":["? 칸은 자음자 ㅋ 줄과 모음자 ㅗ 칸이 만나는 곳이에요.","ㅋ과 ㅗ가 만나면 「코」예요.","왼쪽 자음자 줄을 따라가다 위쪽 모음자 칸에서 멈춰요."],"concept":"K1-1-u1-C4","difficulty":2,"variant_rule":{"jamo":{"ask":"table","cons":["ㄱ","ㄴ","ㄷ","ㅁ","ㅂ","ㅅ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ"],"mis":{"grid":"X07","rot":"X06"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_challenge#3','kor',1,1,'u1','L13','g1_1_kor_u1_L13_challenge','lesson_challenge','K1-1-u1-C7',3,'mc','auto','카드 ㄷ · ㅗ · ㅌ · ㅗ · ㄹ · ㅣ 로 만든 낱말은 어느 것인가요?',ARRAY['K1-1-u1-X09','K1-1-u1-X02']::text[],true,'{"seq":3,"concept":"K1-1-u1-C7","difficulty":3,"kind":"mc","stem":"카드 ㄷ · ㅗ · ㅌ · ㅗ · ㄹ · ㅣ 로 만든 낱말은 어느 것인가요?","options":[{"t":"도토리","correct":true},{"t":"토도리","mis":"K1-1-u1-X09"},{"t":"도터리","mis":"K1-1-u1-X02"}],"explanation":["ㄷ+ㅗ, ㅌ+ㅗ, ㄹ+ㅣ — 도토리.","「토도리」는 차례가 바뀌었고, 「도터리」는 ㅗ를 ㅓ로 썼어요.","카드 차례대로 두 장씩."],"asset":{"type":"scene","icon":"🌰"},"variant_rule":{"alt":[{"stem":"카드 ㄱ · ㅗ · ㄱ · ㅜ · ㅁ · ㅏ 로 만든 낱말은 어느 것인가요?","options":[{"t":"고구마","correct":true},{"t":"구고마","mis":"K1-1-u1-X09"},{"t":"고고마","mis":"K1-1-u1-X02"}],"explanation":["ㄱ+ㅗ, ㄱ+ㅜ, ㅁ+ㅏ — 고구마.","「구고마」는 차례가 바뀌었고, 「고고마」는 ㅜ를 ㅗ로 썼어요.","카드 차례대로 두 장씩."],"asset":{"type":"scene","icon":"🍠"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_challenge#4','kor',1,1,'u1','L13','g1_1_kor_u1_L13_challenge','lesson_challenge','K1-1-u1-C7',3,'error','auto','은우가 나비 그림을 보고 카드로 「비나」를 만들었어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u1-X09','K1-1-u1-X02','K1-1-u1-X04']::text[],true,'{"seq":4,"concept":"K1-1-u1-C7","difficulty":3,"kind":"error","stem":"은우가 나비 그림을 보고 카드로 「비나」를 만들었어요. 무엇이 잘못되었나요?","options":[{"t":"글자를 모은 차례가 바뀌었어요 — 「나비」예요","correct":true,"mis_target":"K1-1-u1-X09"},{"t":"모음자 ㅏ를 ㅓ로 바꾸어야 해요","mis":"K1-1-u1-X02"},{"t":"자음자 ㄴ을 ㄷ으로 바꾸어야 해요","mis":"K1-1-u1-X04"}],"explanation":["카드는 맞게 골랐어요.","「나」를 먼저, 「비」를 나중에.","왼쪽부터 차례대로."],"asset":{"type":"scene","icon":"🦋"},"variant_rule":{"alt":[{"stem":"지안이가 기차 그림을 보고 카드로 「차기」를 만들었어요. 무엇이 잘못되었나요?","options":[{"t":"글자를 모은 차례가 바뀌었어요 — 「기차」예요","correct":true,"mis_target":"K1-1-u1-X09"},{"t":"모음자 ㅣ를 ㅡ로 바꾸어야 해요","mis":"K1-1-u1-X06"},{"t":"자음자 ㅊ을 ㅈ으로 바꾸어야 해요","mis":"K1-1-u1-X04"}],"explanation":["카드는 맞게 골랐어요.","「기」를 먼저, 「차」를 나중에.","왼쪽부터 차례대로."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_challenge#5','kor',1,1,'u1','L13','g1_1_kor_u1_L13_challenge','lesson_challenge','K1-1-u1-C2',3,'mc','auto','ㅊ + ㅣ 는 어떤 글자가 되나요?',ARRAY['K1-1-u1-X06','K1-1-u1-X04']::text[],true,'{"seq":5,"kind":"mc","stem":"ㅊ + ㅣ 는 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㅊ","v":"ㅣ","s":null},"options":[{"t":"치","correct":true},{"t":"츠","mis":"K1-1-u1-X06"},{"t":"지","mis":"K1-1-u1-X04"}],"explanation":["자음자 ㅊ과 모음자 ㅣ가 만나면 「치」예요.","ㅣ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":3,"variant_rule":{"jamo":{"ask":"build","cons":["ㅊ","ㅈ","ㄱ","ㄷ","ㅂ","ㅎ"],"vows":["ㅣ","ㅡ"],"mis":{"rot":"X06","cons":"X04"},"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_challenge#6','kor',1,1,'u1','L13','g1_1_kor_u1_L13_challenge','lesson_challenge','K1-1-u1-C7',3,'mc','auto','칠판의 자음자 ㄷ ㄹ ㅁ 과 모음자 ㅏ ㅣ ㅣ 가 들어간, 옷을 펴는 물건은 어느 것인가요?',ARRAY['K1-1-u1-X09','K1-1-u1-X08']::text[],true,'{"seq":6,"concept":"K1-1-u1-C7","difficulty":3,"kind":"mc","stem":"칠판의 자음자 ㄷ ㄹ ㅁ 과 모음자 ㅏ ㅣ ㅣ 가 들어간, 옷을 펴는 물건은 어느 것인가요?","options":[{"t":"다리미","correct":true},{"t":"리다미","mis":"K1-1-u1-X09"},{"t":"다리마","mis":"K1-1-u1-X08"}],"explanation":["다(ㄷ+ㅏ), 리(ㄹ+ㅣ), 미(ㅁ+ㅣ) — 다리미예요.","「리다미」는 차례가 바뀌었고, 「다리마」는 모음자를 잘못 짝 지었어요.","세 글자도 차례대로."],"variant_rule":{"alt":[{"stem":"칠판의 자음자 ㅎ ㅁ ㄴ ㅋ 과 모음자 ㅏ ㅗ ㅣ ㅏ 가 들어간 악기는 어느 것인가요?","options":[{"t":"하모니카","correct":true},{"t":"모하니카","mis":"K1-1-u1-X09"},{"t":"하마니코","mis":"K1-1-u1-X08"}],"explanation":["하(ㅎ+ㅏ), 모(ㅁ+ㅗ), 니(ㄴ+ㅣ), 카(ㅋ+ㅏ) — 하모니카.","「모하니카」는 차례가 바뀌었고, 「하마니코」는 모음자를 잘못 짝 지었어요.","네 글자도 차례대로."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_challenge#7','kor',1,1,'u1','L13','g1_1_kor_u1_L13_challenge','lesson_challenge','K1-1-u1-C7',3,'sa','auto','그림에 알맞은 낱말을 카드 ㄴ · ㅗ · ㄹ · ㅜ 로 만들어 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"K1-1-u1-C7","difficulty":3,"kind":"sa","stem":"그림에 알맞은 낱말을 카드 ㄴ · ㅗ · ㄹ · ㅜ 로 만들어 쓰세요.","answer":["노루"],"explanation":["ㄴ+ㅗ = 노, ㄹ+ㅜ = 루.","차례대로 모으면 「노루」.","카드 두 장씩 모아요."],"asset":{"type":"scene","icon":"🦌"},"variant_rule":{"alt":[{"stem":"그림에 알맞은 낱말을 카드 ㅇ · ㅕ · ㅊ · ㅣ 로 만들어 쓰세요.","answer":["여치"],"explanation":["ㅇ+ㅕ = 여, ㅊ+ㅣ = 치.","차례대로 모으면 「여치」.","카드 두 장씩 모아요."],"asset":{"type":"scene","icon":"🦗"}},{"stem":"그림에 알맞은 낱말을 카드 ㅅ · ㅏ · ㅈ · ㅏ 로 만들어 쓰세요.","answer":["사자"],"explanation":["ㅅ+ㅏ = 사, ㅈ+ㅏ = 자.","차례대로 모으면 「사자」.","카드 두 장씩 모아요."],"asset":{"type":"scene","icon":"🦁"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_challenge#8','kor',1,1,'u1','L13','g1_1_kor_u1_L13_challenge','lesson_challenge','K1-1-u1-C7',4,'mc','auto','글자 카드 「고」, 「구」, 「마」 세 장을 모두 써서 만든 낱말은 어느 것인가요?',ARRAY['K1-1-u1-X09']::text[],true,'{"seq":8,"concept":"K1-1-u1-C7","difficulty":4,"kind":"mc","stem":"글자 카드 「고」, 「구」, 「마」 세 장을 모두 써서 만든 낱말은 어느 것인가요?","options":[{"t":"고구마","correct":true},{"t":"구고마","mis":"K1-1-u1-X09"},{"t":"고마구","mis":"K1-1-u1-X09"}],"explanation":["고 → 구 → 마, 고구마.","다른 것은 차례가 바뀌었어요.","뜻이 되는 차례 찾기."],"asset":{"type":"scene","icon":"🍠"},"variant_rule":{"alt":[{"stem":"글자 카드 「리」, 「다」, 「미」 세 장을 모두 써서 만든 낱말은 어느 것인가요?","options":[{"t":"다리미","correct":true},{"t":"리다미","mis":"K1-1-u1-X09"},{"t":"다미리","mis":"K1-1-u1-X09"}],"explanation":["다 → 리 → 미, 다리미.","다른 것은 차례가 바뀌었어요.","뜻이 되는 차례 찾기."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_challenge#9','kor',1,1,'u1','L13','g1_1_kor_u1_L13_challenge','lesson_challenge','K1-1-u1-C7',4,'essay','teacher','낱말 알아맞히기 놀이에서 친구들에게 낼 문제를 만들어요. 받침이 없는 낱말 하나를 골라 자음자와 모음자로 나누어 쓰고, 답도 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u1-C7","difficulty":4,"kind":"essay","stem":"낱말 알아맞히기 놀이에서 친구들에게 낼 문제를 만들어요. 받침이 없는 낱말 하나를 골라 자음자와 모음자로 나누어 쓰고, 답도 함께 쓰세요.","answer_guide":{"answer":"예: 문제 — 자음자 ㅍ ㅇ ㄴ, 모음자 ㅣ ㅏ ㅗ / 답 — 피아노(ㅍ+ㅣ, ㅇ+ㅏ, ㄴ+ㅗ). — 받침이 없는 낱말을 고르고, 자음자와 모음자를 빠짐없이 바르게 나누어 쓰면 맞아요.","scoring_points":["받침이 없는 낱말을 골랐는가","자음자와 모음자를 빠짐없이 바르게 나누었는가","글자마다 어떤 자음자와 모음자가 만나는지 답을 썼는가"]},"explanation":["받침이 없는 낱말을 골라요.","자음자와 모음자로 나누어 문제를 내요.","답은 글자마다 자음자 + 모음자."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_challenge#10','kor',1,1,'u1','L13','g1_1_kor_u1_L13_challenge','lesson_challenge','K1-1-u1-C4',4,'mc','auto','음절표에서 ? 칸에 들어갈 글자는 무엇인가요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":10,"kind":"mc","stem":"음절표에서 ? 칸에 들어갈 글자는 무엇인가요?","asset":{"type":"syl_table","cons":["ㄴ","ㅂ","ㅍ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ"],"q":[2,3]},"options":[{"t":"푸","correct":true},{"t":"포","mis":"K1-1-u1-X02"},{"t":"퓨","mis":"K1-1-u1-X03"}],"explanation":["? 칸은 자음자 ㅍ 줄과 모음자 ㅜ 칸이 만나는 곳이에요.","ㅍ과 ㅜ가 만나면 「푸」예요.","왼쪽 자음자 줄을 따라가다 위쪽 모음자 칸에서 멈춰요."],"concept":"K1-1-u1-C4","difficulty":4,"variant_rule":{"jamo":{"ask":"table","cons":["ㄱ","ㄴ","ㄷ","ㅂ","ㅍ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅕ"],"mis":{"grid":"X07","flip":"X02","stroke":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_a#1','kor',1,1,'u1','','g1_1_kor_u1_review_a','unit_review','K1-1-u1-C1',1,'mc','auto','「보」에서 자음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X04']::text[],true,'{"seq":1,"kind":"mc","stem":"「보」에서 자음자는 어느 것인가요?","asset":{"type":"jamo","s":"보","eq":false,"lay":"blank"},"options":[{"t":"ㅂ","correct":true},{"t":"ㅗ","mis":"K1-1-u1-X01"},{"t":"ㅍ","mis":"K1-1-u1-X04"}],"explanation":["「보」는 자음자 ㅂ과 모음자 ㅗ가 만난 글자예요.","자음자는 ㅂ이에요 — 위쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C1","difficulty":1,"variant_rule":{"jamo":{"ask":"cons","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ"],"mis":{"role":"X01","cons":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
