INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_a#13','kor',1,1,'u1','','g1_1_kor_u1_review_a','unit_review','K1-1-u1-C4',2,'mc','auto','음절표에서 ㄷ 줄을 따라 차례대로 읽은 것은 어느 것인가요?',ARRAY['K1-1-u1-X07','K1-1-u1-X02']::text[],false,'{"seq":13,"concept":"K1-1-u1-C4","difficulty":2,"kind":"mc","stem":"음절표에서 ㄷ 줄을 따라 차례대로 읽은 것은 어느 것인가요?","options":[{"t":"다 · 더 · 도 · 두","correct":true},{"t":"나 · 다 · 바","mis":"K1-1-u1-X07"},{"t":"다 · 더 · 두 · 도","mis":"K1-1-u1-X02"}],"explanation":["ㄷ 줄은 다·더·도·두예요.","다른 하나는 ㅏ 칸을 위에서 아래로 읽은 거예요.","줄은 옆으로 읽어요."],"asset":{"type":"syl_table","cons":["ㄴ","ㄷ","ㅂ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_a#14','kor',1,1,'u1','','g1_1_kor_u1_review_a','unit_review','K1-1-u1-C5',2,'mc','auto','「가」를 쓰는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u1-X12']::text[],false,'{"seq":14,"concept":"K1-1-u1-C5","difficulty":2,"kind":"mc","stem":"「가」를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"ㄱ을 먼저 쓰고 ㅏ를 써요","correct":true},{"t":"ㅏ를 먼저 쓰고 ㄱ을 써요","mis":"K1-1-u1-X12"},{"t":"ㄱ을 아래에서 위로 써요","mis":"K1-1-u1-X12"}],"explanation":["자음자를 먼저, 모음자를 나중에.","모음자의 획도 위에서 아래로, 왼쪽에서 오른쪽으로.","자음자 먼저."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_a#15','kor',1,1,'u1','','g1_1_kor_u1_review_a','unit_review','K1-1-u1-C6',2,'match','auto','두 모음자를 합쳐 만든 모음자를 바르게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"K1-1-u1-C6","difficulty":2,"kind":"match","stem":"두 모음자를 합쳐 만든 모음자를 바르게 이으세요.","pairs":[{"l":"ㅗ + ㅏ","r":"ㅘ"},{"l":"ㅜ + ㅓ","r":"ㅝ"},{"l":"ㅡ + ㅣ","r":"ㅢ"}],"mis":"K1-1-u1-X14","explanation":["두 모음자를 다 봐요.","앞의 모음자 + 뒤의 모음자.","합친 모음자 = 두 모음자."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_a#16','kor',1,1,'u1','','g1_1_kor_u1_review_a','unit_review','K1-1-u1-C6',2,'ox','auto','「게」의 모음자는 ㅐ예요.',ARRAY['K1-1-u1-X13']::text[],false,'{"seq":16,"concept":"K1-1-u1-C6","difficulty":2,"kind":"ox","stem":"「게」의 모음자는 ㅐ예요.","answer":"X","reason_options":[{"t":"「게」는 ㄱ과 ㅔ가 만난 글자니까","correct":true},{"t":"ㅐ와 ㅔ는 같은 모음자니까","mis":"K1-1-u1-X13"}],"mis":"K1-1-u1-X13","explanation":["게 = ㄱ + ㅔ.","ㅐ와 ㅔ는 다른 모음자예요.","앞의 모음자를 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_a#17','kor',1,1,'u1','','g1_1_kor_u1_review_a','unit_review','K1-1-u1-C7',3,'ox','auto','「거솨」는 뜻이 없는 낱말이에요. 그래도 글자를 하나하나 짚으며 그대로 읽어요.',ARRAY['K1-1-u1-X15']::text[],false,'{"seq":17,"concept":"K1-1-u1-C7","difficulty":3,"kind":"ox","stem":"「거솨」는 뜻이 없는 낱말이에요. 그래도 글자를 하나하나 짚으며 그대로 읽어요.","answer":"O","reason_options":[{"t":"자음자와 모음자를 보고 짐작하지 않고 또박또박 읽어야 하니까","correct":true},{"t":"뜻이 없으면 비슷한 아는 낱말로 바꿔 읽으면 되니까","mis":"K1-1-u1-X15"}],"mis":"K1-1-u1-X15","explanation":["거솨 = ㄱ·ㅓ + ㅅ·ㅘ.","뜻을 몰라도 자음자와 모음자 소리를 합치면 읽을 수 있어요.","빠르기보다 정확하게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_a#18','kor',1,1,'u1','','g1_1_kor_u1_review_a','unit_review','K1-1-u1-C2',3,'error','auto','소이가 자음자 ㄱ과 모음자 ㅓ를 모아 「가」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X04','K1-1-u1-X03']::text[],false,'{"seq":18,"concept":"K1-1-u1-C2","difficulty":3,"kind":"error","stem":"소이가 자음자 ㄱ과 모음자 ㅓ를 모아 「가」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"모음자의 방향을 바꾸어 썼어요 — ㄱ과 ㅓ는 「거」예요","correct":true,"mis_target":"K1-1-u1-X02"},{"t":"자음자를 ㅋ으로 써야 해요 — 「커」예요","mis":"K1-1-u1-X04"},{"t":"짧은 획이 하나 모자라요 — 「겨」예요","mis":"K1-1-u1-X03"}],"explanation":["ㄱ + ㅓ = 거.","「가」와 「거」는 다른 글자예요.","자음자와 모음자를 하나씩 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_a#19','kor',1,1,'u1','','g1_1_kor_u1_review_a','unit_review','K1-1-u1-C3',3,'error','auto','민재가 「노」를 쓸 때 ㅗ를 ㄴ 오른쪽에 붙여 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u1-X05','K1-1-u1-X02','K1-1-u1-X04']::text[],false,'{"seq":19,"concept":"K1-1-u1-C3","difficulty":3,"kind":"error","stem":"민재가 「노」를 쓸 때 ㅗ를 ㄴ 오른쪽에 붙여 썼어요. 무엇이 잘못되었나요?","options":[{"t":"ㅗ는 ㄴ 아래쪽에 써야 해요","correct":true,"mis_target":"K1-1-u1-X05"},{"t":"ㅗ 대신 ㅜ를 써야 해요","mis":"K1-1-u1-X02"},{"t":"ㄴ 대신 ㄷ을 써야 해요","mis":"K1-1-u1-X04"}],"explanation":["ㅗ는 가로로 길어서 아래에 쌓여요.","모음자는 맞게 골랐고 자리만 틀렸어요.","모음자 모양이 자리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_a#20','kor',1,1,'u1','','g1_1_kor_u1_review_a','unit_review','K1-1-u1-C6',3,'mc','auto','ㄱ + ㅘ 는 어떤 글자가 되나요?',ARRAY['K1-1-u1-X14']::text[],true,'{"seq":20,"kind":"mc","stem":"ㄱ + ㅘ 는 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㄱ","v":"ㅘ","s":null},"options":[{"t":"과","correct":true},{"t":"고","mis":"K1-1-u1-X14"},{"t":"가","mis":"K1-1-u1-X14"}],"explanation":["자음자 ㄱ과 모음자 ㅘ가 만나면 「과」예요.","ㅘ는 자음자의 아래와 오른쪽을 함께 감싸요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C6","difficulty":3,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅐ","ㅔ","ㅒ","ㅖ","ㅘ","ㅝ","ㅚ","ㅟ","ㅙ","ㅢ"],"mis":{"ae":"X13","comb":"X14","cons":"X04"},"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_a#21','kor',1,1,'u1','','g1_1_kor_u1_review_a','unit_review','K1-1-u1-C7',3,'mc','auto','카드 ㄷ · ㅐ · ㅊ · ㅜ 네 장으로 만들 수 있는 열매은 어느 것인가요?',ARRAY['K1-1-u1-X09','K1-1-u1-X13']::text[],false,'{"seq":21,"concept":"K1-1-u1-C7","difficulty":3,"kind":"mc","stem":"카드 ㄷ · ㅐ · ㅊ · ㅜ 네 장으로 만들 수 있는 열매은 어느 것인가요?","options":[{"t":"대추","correct":true},{"t":"추대","mis":"K1-1-u1-X09"},{"t":"데추","mis":"K1-1-u1-X13"}],"explanation":["ㄷ+ㅐ = 대, ㅊ+ㅜ = 추 — 대추.","「추대」는 차례가 바뀌었고, 「데추」는 모음자를 잘못 보았어요.","자음자마다 모음자 짝을 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_a#22','kor',1,1,'u1','','g1_1_kor_u1_review_a','unit_review','K1-1-u1-C5',3,'error','auto','지유가 읽기 자세를 점검했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_a#23','kor',1,1,'u1','','g1_1_kor_u1_review_a','unit_review','K1-1-u1-C4',4,'sa','auto','음절표에서 ? 칸에 들어갈 글자를 쓰세요.','{}'::text[],true,'{"seq":23,"kind":"sa","stem":"음절표에서 ? 칸에 들어갈 글자를 쓰세요.","asset":{"type":"syl_table","cons":["ㄱ","ㄹ","ㅂ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅛ"],"q":[1,3]},"answer":["료"],"explanation":["? 칸은 자음자 ㄹ 줄과 모음자 ㅛ 칸이 만나는 곳이에요.","ㄹ과 ㅛ가 만나면 「료」예요.","왼쪽 자음자 줄을 따라가다 위쪽 모음자 칸에서 멈춰요."],"concept":"K1-1-u1-C4","difficulty":4,"variant_rule":{"jamo":{"ask":"table","cons":["ㄱ","ㄴ","ㄹ","ㅁ","ㅅ","ㅎ"],"vows":["ㅑ","ㅕ","ㅛ","ㅠ"],"mis":{"grid":"X07","flip":"X02","stroke":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_a#24','kor',1,1,'u1','','g1_1_kor_u1_review_a','unit_review','K1-1-u1-C7',4,'essay','teacher','카드 ㄱ · ㅁ · ㅏ · ㅗ 를 골라 낱말을 두 개 만들고, 글자마다 어떤 자음자와 모음자를 모았는지 말해 보세요. (카드는 여러 번 써도 돼요)','{}'::text[],false,'{"seq":24,"concept":"K1-1-u1-C7","difficulty":4,"kind":"essay","stem":"카드 ㄱ · ㅁ · ㅏ · ㅗ 를 골라 낱말을 두 개 만들고, 글자마다 어떤 자음자와 모음자를 모았는지 말해 보세요. (카드는 여러 번 써도 돼요)","answer_guide":{"answer":"예: 「고모」(ㄱ+ㅗ, ㅁ+ㅗ)와 「가마」(ㄱ+ㅏ, ㅁ+ㅏ) — 뜻이 있는 낱말 두 개를 만들고 글자마다 자음자+모음자를 바르게 말하면 맞아요.","scoring_points":["뜻이 있는 낱말을 두 개 만들었는가","글자마다 자음자와 모음자를 바르게 말했는가","글자를 차례대로 모았는가"]},"explanation":["낱말 두 개.","글자마다 자음자 + 모음자.","차례대로 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_a#25','kor',1,1,'u1','','g1_1_kor_u1_review_a','unit_review','K1-1-u1-C2',4,'mc','auto','카드 ㄴ · ㅁ · ㅏ · ㅗ 가운데 두 장을 골라 만들 수 없는 글자는 어느 것인가요?',ARRAY['K1-1-u1-X02']::text[],false,'{"seq":25,"concept":"K1-1-u1-C2","difficulty":4,"kind":"mc","stem":"카드 ㄴ · ㅁ · ㅏ · ㅗ 가운데 두 장을 골라 만들 수 없는 글자는 어느 것인가요?","options":[{"t":"누","correct":true},{"t":"노","mis":"K1-1-u1-X02"},{"t":"모","mis":"K1-1-u1-X02"}],"explanation":["「누」에 필요한 카드가 없어요.","「노」와 「모」는 만들 수 있어요.","자음자 하나 + 모음자 하나."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_b#1','kor',1,1,'u1','','g1_1_kor_u1_review_b','unit_review','K1-1-u1-C1',1,'mc','auto','「라」에서 자음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X04']::text[],true,'{"seq":1,"kind":"mc","stem":"「라」에서 자음자는 어느 것인가요?","asset":{"type":"jamo","s":"라","eq":false,"lay":"blank"},"options":[{"t":"ㄹ","correct":true},{"t":"ㅏ","mis":"K1-1-u1-X01"},{"t":"ㄷ","mis":"K1-1-u1-X04"}],"explanation":["「라」는 자음자 ㄹ과 모음자 ㅏ가 만난 글자예요.","자음자는 ㄹ이에요 — 왼쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C1","difficulty":1,"variant_rule":{"jamo":{"ask":"cons","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ"],"mis":{"role":"X01","cons":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_b#2','kor',1,1,'u1','','g1_1_kor_u1_review_b','unit_review','K1-1-u1-C8',1,'mc','auto','모음자 ㅛ의 이름은 무엇인가요?',ARRAY['K1-1-u1-X03','K1-1-u1-X02']::text[],false,'{"seq":2,"concept":"K1-1-u1-C8","difficulty":1,"kind":"mc","stem":"모음자 ㅛ의 이름은 무엇인가요?","options":[{"t":"요","correct":true},{"t":"오","mis":"K1-1-u1-X03"},{"t":"유","mis":"K1-1-u1-X02"}],"explanation":["ㅛ의 이름은 「요」예요.","「오」는 ㅗ, 「유」는 ㅠ의 이름이에요.","모음자 이름은 소리 그대로, 자음자는 이름이 따로 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_b#3','kor',1,1,'u1','','g1_1_kor_u1_review_b','unit_review','K1-1-u1-C2',1,'mc','auto','자음자 ㄴ과 모음자 ㅓ가 만나면 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":3,"kind":"mc","stem":"자음자 ㄴ과 모음자 ㅓ가 만나면 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㄴ","v":"ㅓ","s":null,"lay":true},"options":[{"t":"너","correct":true},{"t":"나","mis":"K1-1-u1-X02"},{"t":"녀","mis":"K1-1-u1-X03"}],"explanation":["자음자 ㄴ과 모음자 ㅓ가 만나면 「너」예요.","ㅓ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":1,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ"],"mis":{"flip":"X02","stroke":"X03","rot":"X06","cons":"X04"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_b#4','kor',1,1,'u1','','g1_1_kor_u1_review_b','unit_review','K1-1-u1-C3',1,'mc','auto','「나」에서 자음자 ㄴ은 어디에 있나요?',ARRAY['K1-1-u1-X05','K1-1-u1-X01']::text[],true,'{"seq":4,"kind":"mc","stem":"「나」에서 자음자 ㄴ은 어디에 있나요?","asset":{"type":"jamo","s":"나","eq":false},"options":[{"t":"왼쪽","correct":true},{"t":"위쪽","mis":"K1-1-u1-X05"},{"t":"오른쪽","mis":"K1-1-u1-X01"}],"explanation":["「나」는 옆으로 나란히 만든 글자예요.","ㅏ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","그래서 자음자 ㄴ은 왼쪽에 있어요."],"concept":"K1-1-u1-C3","difficulty":1,"variant_rule":{"jamo":{"ask":"place","role":"c","cons":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅈ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ","ㅡ"],"mis":{"place":"X05","role":"X01"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
