INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_b#10','kor',1,1,'u1','','g1_1_kor_u1_review_b','unit_review','K1-1-u1-C2',2,'mc','auto','ㅈ + ㅗ 는 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":10,"kind":"mc","stem":"ㅈ + ㅗ 는 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㅈ","v":"ㅗ","s":null},"options":[{"t":"조","correct":true},{"t":"주","mis":"K1-1-u1-X02"},{"t":"죠","mis":"K1-1-u1-X03"}],"explanation":["자음자 ㅈ과 모음자 ㅗ가 만나면 「조」예요.","ㅗ는 가로로 길어서 자음자 아래에 쌓여요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":2,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅑ","ㅕ","ㅛ","ㅠ"],"mis":{"flip":"X02","stroke":"X03","rot":"X06","cons":"X04"},"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_b#11','kor',1,1,'u1','','g1_1_kor_u1_review_b','unit_review','K1-1-u1-C3',2,'mc','auto','「머」에서 모음자 ㅓ는 어디에 있나요?',ARRAY['K1-1-u1-X05','K1-1-u1-X01']::text[],true,'{"seq":11,"kind":"mc","stem":"「머」에서 모음자 ㅓ는 어디에 있나요?","asset":{"type":"jamo","s":"머","eq":false},"options":[{"t":"오른쪽","correct":true},{"t":"아래쪽","mis":"K1-1-u1-X05"},{"t":"왼쪽","mis":"K1-1-u1-X01"}],"explanation":["「머」는 옆으로 나란히 만든 글자예요.","ㅓ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","그래서 모음자 ㅓ는 오른쪽에 있어요."],"concept":"K1-1-u1-C3","difficulty":2,"variant_rule":{"jamo":{"ask":"place","role":"v","cons":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅈ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ","ㅡ"],"mis":{"place":"X05","role":"X01"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_b#12','kor',1,1,'u1','','g1_1_kor_u1_review_b','unit_review','K1-1-u1-C3',2,'mc','auto','옆으로 나란히 만든 글자는 어느 것인가요?',ARRAY['K1-1-u1-X05']::text[],false,'{"seq":12,"concept":"K1-1-u1-C3","difficulty":2,"kind":"mc","stem":"옆으로 나란히 만든 글자는 어느 것인가요?","options":[{"t":"머","correct":true},{"t":"모","mis":"K1-1-u1-X05"},{"t":"므","mis":"K1-1-u1-X05"}],"explanation":["「머」는 ㅁ 오른쪽에 ㅓ.","「모」·「므」는 위아래로.","세로로 긴 모음자는 옆에."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_b#13','kor',1,1,'u1','','g1_1_kor_u1_review_b','unit_review','K1-1-u1-C4',2,'mc','auto','음절표에서 ㅅ 줄을 따라 차례대로 읽은 것은 어느 것인가요?',ARRAY['K1-1-u1-X07','K1-1-u1-X02']::text[],false,'{"seq":13,"concept":"K1-1-u1-C4","difficulty":2,"kind":"mc","stem":"음절표에서 ㅅ 줄을 따라 차례대로 읽은 것은 어느 것인가요?","options":[{"t":"사 · 서 · 소 · 수","correct":true},{"t":"가 · 사 · 자","mis":"K1-1-u1-X07"},{"t":"사 · 서 · 수 · 소","mis":"K1-1-u1-X02"}],"explanation":["ㅅ 줄은 사·서·소·수예요.","다른 하나는 ㅏ 칸을 위에서 아래로 읽은 거예요.","줄은 옆으로 읽어요."],"asset":{"type":"syl_table","cons":["ㄱ","ㅅ","ㅈ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_b#14','kor',1,1,'u1','','g1_1_kor_u1_review_b','unit_review','K1-1-u1-C5',2,'mc','auto','「도」를 쓰는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u1-X12']::text[],false,'{"seq":14,"concept":"K1-1-u1-C5","difficulty":2,"kind":"mc","stem":"「도」를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"ㄷ을 먼저 쓰고 ㅗ를 써요","correct":true},{"t":"ㅗ를 먼저 쓰고 ㄷ을 써요","mis":"K1-1-u1-X12"},{"t":"ㄷ을 아래에서 위로 써요","mis":"K1-1-u1-X12"}],"explanation":["자음자를 먼저, 모음자를 나중에.","모음자의 획도 위에서 아래로, 왼쪽에서 오른쪽으로.","자음자 먼저."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_b#15','kor',1,1,'u1','','g1_1_kor_u1_review_b','unit_review','K1-1-u1-C6',2,'match','auto','두 모음자를 합쳐 만든 모음자를 바르게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"K1-1-u1-C6","difficulty":2,"kind":"match","stem":"두 모음자를 합쳐 만든 모음자를 바르게 이으세요.","pairs":[{"l":"ㅗ + ㅣ","r":"ㅚ"},{"l":"ㅜ + ㅣ","r":"ㅟ"},{"l":"ㅗ + ㅐ","r":"ㅙ"}],"mis":"K1-1-u1-X14","explanation":["두 모음자를 다 봐요.","앞의 모음자 + 뒤의 모음자.","합친 모음자 = 두 모음자."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_b#16','kor',1,1,'u1','','g1_1_kor_u1_review_b','unit_review','K1-1-u1-C6',2,'ox','auto','「개」의 모음자는 ㅐ예요.',ARRAY['K1-1-u1-X13']::text[],false,'{"seq":16,"concept":"K1-1-u1-C6","difficulty":2,"kind":"ox","stem":"「개」의 모음자는 ㅐ예요.","answer":"O","reason_options":[{"t":"「개」는 ㄱ과 ㅐ가 만난 글자니까","correct":true},{"t":"ㅐ는 ㅓ와 ㅣ가 붙은 모양이니까","mis":"K1-1-u1-X13"}],"mis":"K1-1-u1-X13","explanation":["개 = ㄱ + ㅐ.","ㅐ는 ㅏ와 ㅣ가 붙은 모양이에요.","앞의 모음자를 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_b#17','kor',1,1,'u1','','g1_1_kor_u1_review_b','unit_review','K1-1-u1-C7',3,'ox','auto','「투퀴」는 뜻이 없는 낱말이에요. 그래도 글자를 하나하나 짚으며 그대로 읽어요.',ARRAY['K1-1-u1-X15']::text[],false,'{"seq":17,"concept":"K1-1-u1-C7","difficulty":3,"kind":"ox","stem":"「투퀴」는 뜻이 없는 낱말이에요. 그래도 글자를 하나하나 짚으며 그대로 읽어요.","answer":"O","reason_options":[{"t":"자음자와 모음자를 보고 짐작하지 않고 또박또박 읽어야 하니까","correct":true},{"t":"뜻이 없으면 비슷한 아는 낱말로 바꿔 읽으면 되니까","mis":"K1-1-u1-X15"}],"mis":"K1-1-u1-X15","explanation":["투퀴 = ㅌ·ㅜ + ㅋ·ㅟ.","뜻을 몰라도 자음자와 모음자 소리를 합치면 읽을 수 있어요.","빠르기보다 정확하게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_b#18','kor',1,1,'u1','','g1_1_kor_u1_review_b','unit_review','K1-1-u1-C2',3,'error','auto','도하가 자음자 ㅂ과 모음자 ㅗ를 모아 「포」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u1-X04','K1-1-u1-X02','K1-1-u1-X03']::text[],false,'{"seq":18,"concept":"K1-1-u1-C2","difficulty":3,"kind":"error","stem":"도하가 자음자 ㅂ과 모음자 ㅗ를 모아 「포」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"자음자를 ㅍ으로 바꾸어 썼어요 — ㅂ과 ㅗ는 「보」예요","correct":true,"mis_target":"K1-1-u1-X04"},{"t":"모음자의 방향을 바꾸어 썼어요 — 「부」예요","mis":"K1-1-u1-X02"},{"t":"짧은 획이 하나 모자라요 — 「뵤」예요","mis":"K1-1-u1-X03"}],"explanation":["ㅂ + ㅗ = 보.","「포」와 「보」는 다른 글자예요.","자음자와 모음자를 하나씩 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_b#19','kor',1,1,'u1','','g1_1_kor_u1_review_b','unit_review','K1-1-u1-C3',3,'error','auto','수아가 「더」를 쓸 때 ㅓ를 ㄷ 아래쪽에 붙여 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u1-X05','K1-1-u1-X02','K1-1-u1-X04']::text[],false,'{"seq":19,"concept":"K1-1-u1-C3","difficulty":3,"kind":"error","stem":"수아가 「더」를 쓸 때 ㅓ를 ㄷ 아래쪽에 붙여 썼어요. 무엇이 잘못되었나요?","options":[{"t":"ㅓ는 ㄷ 오른쪽에 써야 해요","correct":true,"mis_target":"K1-1-u1-X05"},{"t":"ㅓ 대신 ㅏ를 써야 해요","mis":"K1-1-u1-X02"},{"t":"ㄷ 대신 ㅌ을 써야 해요","mis":"K1-1-u1-X04"}],"explanation":["ㅓ는 세로로 길어서 옆에 서요.","모음자는 맞게 골랐고 자리만 틀렸어요.","모음자 모양이 자리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_b#20','kor',1,1,'u1','','g1_1_kor_u1_review_b','unit_review','K1-1-u1-C6',3,'mc','auto','ㅅ + ㅐ 는 어떤 글자가 되나요?',ARRAY['K1-1-u1-X13']::text[],true,'{"seq":20,"kind":"mc","stem":"ㅅ + ㅐ 는 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㅅ","v":"ㅐ","s":null},"options":[{"t":"새","correct":true},{"t":"세","mis":"K1-1-u1-X13"},{"t":"섀","mis":"K1-1-u1-X13"}],"explanation":["자음자 ㅅ과 모음자 ㅐ가 만나면 「새」예요.","ㅐ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C6","difficulty":3,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅐ","ㅔ","ㅒ","ㅖ","ㅘ","ㅝ","ㅚ","ㅟ","ㅙ","ㅢ"],"mis":{"ae":"X13","comb":"X14","cons":"X04"},"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_b#21','kor',1,1,'u1','','g1_1_kor_u1_review_b','unit_review','K1-1-u1-C7',3,'mc','auto','카드 ㅁ · ㅗ · ㄱ · ㅘ 네 장으로 만들 수 있는 열매은 어느 것인가요?',ARRAY['K1-1-u1-X09','K1-1-u1-X14']::text[],false,'{"seq":21,"concept":"K1-1-u1-C7","difficulty":3,"kind":"mc","stem":"카드 ㅁ · ㅗ · ㄱ · ㅘ 네 장으로 만들 수 있는 열매은 어느 것인가요?","options":[{"t":"모과","correct":true},{"t":"과모","mis":"K1-1-u1-X09"},{"t":"모가","mis":"K1-1-u1-X14"}],"explanation":["ㅁ+ㅗ = 모, ㄱ+ㅘ = 과 — 모과.","「과모」는 차례가 바뀌었고, 「모가」는 모음자를 잘못 보았어요.","자음자마다 모음자 짝을 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_b#22','kor',1,1,'u1','','g1_1_kor_u1_review_b','unit_review','K1-1-u1-C5',3,'error','auto','태오가 쓰기 자세를 점검했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_b#23','kor',1,1,'u1','','g1_1_kor_u1_review_b','unit_review','K1-1-u1-C4',4,'sa','auto','음절표에서 ? 칸에 들어갈 글자를 쓰세요.','{}'::text[],true,'{"seq":23,"kind":"sa","stem":"음절표에서 ? 칸에 들어갈 글자를 쓰세요.","asset":{"type":"syl_table","cons":["ㄴ","ㅁ","ㅅ","ㅈ"],"vows":["ㅑ","ㅓ","ㅜ","ㅠ"],"q":[3,3]},"answer":["쥬"],"explanation":["? 칸은 자음자 ㅈ 줄과 모음자 ㅠ 칸이 만나는 곳이에요.","ㅈ과 ㅠ가 만나면 「쥬」예요.","왼쪽 자음자 줄을 따라가다 위쪽 모음자 칸에서 멈춰요."],"concept":"K1-1-u1-C4","difficulty":4,"variant_rule":{"jamo":{"ask":"table","cons":["ㄱ","ㄴ","ㄹ","ㅁ","ㅅ","ㅎ"],"vows":["ㅑ","ㅕ","ㅛ","ㅠ"],"mis":{"grid":"X07","flip":"X02","stroke":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_b#24','kor',1,1,'u1','','g1_1_kor_u1_review_b','unit_review','K1-1-u1-C7',4,'essay','teacher','카드 ㄴ · ㅂ · ㅏ · ㅣ 를 골라 낱말을 두 개 만들고, 글자마다 어떤 자음자와 모음자를 모았는지 말해 보세요. (카드는 여러 번 써도 돼요)','{}'::text[],false,'{"seq":24,"concept":"K1-1-u1-C7","difficulty":4,"kind":"essay","stem":"카드 ㄴ · ㅂ · ㅏ · ㅣ 를 골라 낱말을 두 개 만들고, 글자마다 어떤 자음자와 모음자를 모았는지 말해 보세요. (카드는 여러 번 써도 돼요)","answer_guide":{"answer":"예: 「나비」(ㄴ+ㅏ, ㅂ+ㅣ)와 「바나나」(ㅂ+ㅏ, ㄴ+ㅏ, ㄴ+ㅏ) — 뜻이 있는 낱말 두 개를 만들고 글자마다 자음자+모음자를 바르게 말하면 맞아요.","scoring_points":["뜻이 있는 낱말을 두 개 만들었는가","글자마다 자음자와 모음자를 바르게 말했는가","글자를 차례대로 모았는가"]},"explanation":["낱말 두 개.","글자마다 자음자 + 모음자.","차례대로 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_b#25','kor',1,1,'u1','','g1_1_kor_u1_review_b','unit_review','K1-1-u1-C2',4,'mc','auto','카드 ㄱ · ㅅ · ㅓ · ㅣ 가운데 두 장을 골라 만들 수 없는 글자는 어느 것인가요?',ARRAY['K1-1-u1-X02','K1-1-u1-X01']::text[],false,'{"seq":25,"concept":"K1-1-u1-C2","difficulty":4,"kind":"mc","stem":"카드 ㄱ · ㅅ · ㅓ · ㅣ 가운데 두 장을 골라 만들 수 없는 글자는 어느 것인가요?","options":[{"t":"가","correct":true},{"t":"거","mis":"K1-1-u1-X02"},{"t":"시","mis":"K1-1-u1-X01"}],"explanation":["「가」에 필요한 카드가 없어요.","「거」와 「시」는 만들 수 있어요.","자음자 하나 + 모음자 하나."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#1','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C1',1,'mc','auto','「지」에서 자음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X04']::text[],true,'{"seq":1,"kind":"mc","stem":"「지」에서 자음자는 어느 것인가요?","asset":{"type":"jamo","s":"지","eq":false,"lay":"blank"},"options":[{"t":"ㅈ","correct":true},{"t":"ㅣ","mis":"K1-1-u1-X01"},{"t":"ㅊ","mis":"K1-1-u1-X04"}],"explanation":["「지」는 자음자 ㅈ과 모음자 ㅣ가 만난 글자예요.","자음자는 ㅈ이에요 — 왼쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C1","difficulty":1,"variant_rule":{"jamo":{"ask":"cons","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ"],"mis":{"role":"X01","cons":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#2','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C8',1,'mc','auto','자음자 ㅅ의 이름은 무엇인가요?',ARRAY['K1-1-u1-X17','K1-1-u1-X04']::text[],false,'{"seq":2,"concept":"K1-1-u1-C8","difficulty":1,"kind":"mc","stem":"자음자 ㅅ의 이름은 무엇인가요?","options":[{"t":"시옷","correct":true},{"t":"스","mis":"K1-1-u1-X17"},{"t":"지읒","mis":"K1-1-u1-X04"}],"explanation":["ㅅ의 이름은 「시옷」이에요.","「스」는 소리이고, 「지읒」은 ㅈ의 이름이에요.","모음자 이름은 소리 그대로, 자음자는 이름이 따로 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#3','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C2',1,'mc','auto','자음자 ㅁ과 모음자 ㅏ가 만나면 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":3,"kind":"mc","stem":"자음자 ㅁ과 모음자 ㅏ가 만나면 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㅁ","v":"ㅏ","s":null,"lay":true},"options":[{"t":"마","correct":true},{"t":"머","mis":"K1-1-u1-X02"},{"t":"먀","mis":"K1-1-u1-X03"}],"explanation":["자음자 ㅁ과 모음자 ㅏ가 만나면 「마」예요.","ㅏ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":1,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ"],"mis":{"flip":"X02","stroke":"X03","rot":"X06","cons":"X04"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#4','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C3',1,'mc','auto','「무」에서 자음자 ㅁ은 어디에 있나요?',ARRAY['K1-1-u1-X05','K1-1-u1-X01']::text[],true,'{"seq":4,"kind":"mc","stem":"「무」에서 자음자 ㅁ은 어디에 있나요?","asset":{"type":"jamo","s":"무","eq":false},"options":[{"t":"위쪽","correct":true},{"t":"왼쪽","mis":"K1-1-u1-X05"},{"t":"아래쪽","mis":"K1-1-u1-X01"}],"explanation":["「무」는 위아래로 쌓아서 만든 글자예요.","ㅜ는 가로로 길어서 자음자 아래에 쌓여요.","그래서 자음자 ㅁ은 위쪽에 있어요."],"concept":"K1-1-u1-C3","difficulty":1,"variant_rule":{"jamo":{"ask":"place","role":"c","cons":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅈ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ","ㅡ"],"mis":{"place":"X05","role":"X01"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#5','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C4',1,'mc','auto','음절표에서 ? 칸에 들어갈 글자는 무엇인가요?',ARRAY['K1-1-u1-X06','K1-1-u1-X07']::text[],true,'{"seq":5,"kind":"mc","stem":"음절표에서 ? 칸에 들어갈 글자는 무엇인가요?","asset":{"type":"syl_table","cons":["ㄴ","ㄹ","ㅈ"],"vows":["ㅏ","ㅗ","ㅜ"],"q":[1,1]},"options":[{"t":"로","correct":true},{"t":"라","mis":"K1-1-u1-X06"},{"t":"루","mis":"K1-1-u1-X07"}],"explanation":["? 칸은 자음자 ㄹ 줄과 모음자 ㅗ 칸이 만나는 곳이에요.","ㄹ과 ㅗ가 만나면 「로」예요.","왼쪽 자음자 줄을 따라가다 위쪽 모음자 칸에서 멈춰요."],"concept":"K1-1-u1-C4","difficulty":1,"variant_rule":{"jamo":{"ask":"table","cons":["ㄱ","ㄴ","ㄷ","ㅁ","ㅂ","ㅅ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ"],"mis":{"grid":"X07","rot":"X06"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#6','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C5',1,'mc','auto','책을 읽을 때 바른 자세는 어느 것인가요?',ARRAY['K1-1-u1-X10']::text[],false,'{"seq":6,"concept":"K1-1-u1-C5","difficulty":1,"kind":"mc","stem":"책을 읽을 때 바른 자세는 어느 것인가요?","options":[{"t":"두 발을 바닥에 붙이고 허리를 펴요","correct":true},{"t":"의자에 비스듬히 누워요","mis":"K1-1-u1-X10"},{"t":"다리를 꼬고 몸을 기울여요","mis":"K1-1-u1-X10"}],"explanation":["두 발 바닥, 허리 펴기.","눕거나 기울이면 바른 자세가 아니에요.","바른 자세로 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#7','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C6',1,'mc','auto','「과」에서 모음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X14']::text[],true,'{"seq":7,"kind":"mc","stem":"「과」에서 모음자는 어느 것인가요?","asset":{"type":"jamo","s":"과","eq":false,"lay":"blank"},"options":[{"t":"ㅘ","correct":true},{"t":"ㄱ","mis":"K1-1-u1-X01"},{"t":"ㅗ","mis":"K1-1-u1-X14"}],"explanation":["「과」는 자음자 ㄱ과 모음자 ㅘ가 만난 글자예요.","모음자는 ㅘ예요 — 아래와 오른쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C6","difficulty":1,"variant_rule":{"jamo":{"ask":"vow","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅐ","ㅔ","ㅒ","ㅖ","ㅘ","ㅝ","ㅚ","ㅟ","ㅙ","ㅢ"],"mis":{"role":"X01","ae":"X13","comb":"X14"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#8','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C7',1,'mc','auto','그림에 알맞은 낱말 카드는 어느 것인가요?',ARRAY['K1-1-u1-X09','K1-1-u1-X14']::text[],false,'{"seq":8,"concept":"K1-1-u1-C7","difficulty":1,"kind":"mc","stem":"그림에 알맞은 낱말 카드는 어느 것인가요?","options":[{"t":"키위","correct":true},{"t":"위키","mis":"K1-1-u1-X09"},{"t":"키우","mis":"K1-1-u1-X14"}],"explanation":["그림은 「키위」예요.","「위키」는 차례가 바뀌었고, 「키우」는 모음자를 잘못 보았어요.","그림 뜻 + 글자 차례 + 모음자."],"asset":{"type":"scene","icon":"🥝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#9','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C1',2,'mc','auto','「로」에서 모음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X02']::text[],true,'{"seq":9,"kind":"mc","stem":"「로」에서 모음자는 어느 것인가요?","asset":{"type":"jamo","s":"로","eq":false,"lay":"blank"},"options":[{"t":"ㅗ","correct":true},{"t":"ㄹ","mis":"K1-1-u1-X01"},{"t":"ㅜ","mis":"K1-1-u1-X02"}],"explanation":["「로」는 자음자 ㄹ과 모음자 ㅗ가 만난 글자예요.","모음자는 ㅗ예요 — 아래쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C1","difficulty":2,"variant_rule":{"jamo":{"ask":"vow","cons":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅈ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅑ","ㅕ"],"mis":{"role":"X01","flip":"X02","stroke":"X03","rot":"X06"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#10','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C2',2,'mc','auto','ㅎ + ㅓ 는 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":10,"kind":"mc","stem":"ㅎ + ㅓ 는 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㅎ","v":"ㅓ","s":null},"options":[{"t":"허","correct":true},{"t":"하","mis":"K1-1-u1-X02"},{"t":"혀","mis":"K1-1-u1-X03"}],"explanation":["자음자 ㅎ과 모음자 ㅓ가 만나면 「허」예요.","ㅓ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":2,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅑ","ㅕ","ㅛ","ㅠ"],"mis":{"flip":"X02","stroke":"X03","rot":"X06","cons":"X04"},"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#11','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C3',2,'mc','auto','「수」에서 모음자 ㅜ는 어디에 있나요?',ARRAY['K1-1-u1-X05','K1-1-u1-X01']::text[],true,'{"seq":11,"kind":"mc","stem":"「수」에서 모음자 ㅜ는 어디에 있나요?","asset":{"type":"jamo","s":"수","eq":false},"options":[{"t":"아래쪽","correct":true},{"t":"오른쪽","mis":"K1-1-u1-X05"},{"t":"위쪽","mis":"K1-1-u1-X01"}],"explanation":["「수」는 위아래로 쌓아서 만든 글자예요.","ㅜ는 가로로 길어서 자음자 아래에 쌓여요.","그래서 모음자 ㅜ는 아래쪽에 있어요."],"concept":"K1-1-u1-C3","difficulty":2,"variant_rule":{"jamo":{"ask":"place","role":"v","cons":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅈ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ","ㅡ"],"mis":{"place":"X05","role":"X01"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#12','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C3',2,'mc','auto','위아래로 쌓아서 만든 글자는 어느 것인가요?',ARRAY['K1-1-u1-X05']::text[],false,'{"seq":12,"concept":"K1-1-u1-C3","difficulty":2,"kind":"mc","stem":"위아래로 쌓아서 만든 글자는 어느 것인가요?","options":[{"t":"투","correct":true},{"t":"타","mis":"K1-1-u1-X05"},{"t":"티","mis":"K1-1-u1-X05"}],"explanation":["「투」는 ㅌ 아래에 ㅜ.","「타」·「티」는 옆으로 나란히.","가로로 긴 모음자는 아래에."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#13','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C4',2,'mc','auto','음절표에서 ㅎ 줄을 따라 차례대로 읽은 것은 어느 것인가요?',ARRAY['K1-1-u1-X07','K1-1-u1-X02']::text[],false,'{"seq":13,"concept":"K1-1-u1-C4","difficulty":2,"kind":"mc","stem":"음절표에서 ㅎ 줄을 따라 차례대로 읽은 것은 어느 것인가요?","options":[{"t":"하 · 허 · 호 · 후","correct":true},{"t":"라 · 마 · 하","mis":"K1-1-u1-X07"},{"t":"하 · 허 · 후 · 호","mis":"K1-1-u1-X02"}],"explanation":["ㅎ 줄은 하·허·호·후예요.","다른 하나는 ㅏ 칸을 위에서 아래로 읽은 거예요.","줄은 옆으로 읽어요."],"asset":{"type":"syl_table","cons":["ㄹ","ㅁ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#14','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C5',2,'mc','auto','「나」를 쓰는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u1-X12']::text[],false,'{"seq":14,"concept":"K1-1-u1-C5","difficulty":2,"kind":"mc","stem":"「나」를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"ㄴ을 먼저 쓰고 ㅏ를 써요","correct":true},{"t":"ㅏ를 먼저 쓰고 ㄴ을 써요","mis":"K1-1-u1-X12"},{"t":"ㄴ을 아래에서 위로 써요","mis":"K1-1-u1-X12"}],"explanation":["자음자를 먼저, 모음자를 나중에.","모음자의 획도 위에서 아래로, 왼쪽에서 오른쪽으로.","자음자 먼저."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#15','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C6',2,'match','auto','두 모음자를 합쳐 만든 모음자를 바르게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"K1-1-u1-C6","difficulty":2,"kind":"match","stem":"두 모음자를 합쳐 만든 모음자를 바르게 이으세요.","pairs":[{"l":"ㅜ + ㅔ","r":"ㅞ"},{"l":"ㅗ + ㅏ","r":"ㅘ"},{"l":"ㅜ + ㅣ","r":"ㅟ"}],"mis":"K1-1-u1-X14","explanation":["두 모음자를 다 봐요.","앞의 모음자 + 뒤의 모음자.","합친 모음자 = 두 모음자."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#16','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C6',2,'ox','auto','「베개」의 「베」에는 모음자 ㅐ가 들어 있어요.',ARRAY['K1-1-u1-X13']::text[],false,'{"seq":16,"concept":"K1-1-u1-C6","difficulty":2,"kind":"ox","stem":"「베개」의 「베」에는 모음자 ㅐ가 들어 있어요.","answer":"X","reason_options":[{"t":"「베」는 ㅂ과 ㅔ가 만난 글자니까","correct":true},{"t":"두 글자의 모음자는 늘 같으니까","mis":"K1-1-u1-X13"}],"mis":"K1-1-u1-X13","explanation":["베 = ㅂ + ㅔ, 개 = ㄱ + ㅐ.","두 글자 모음자가 달라요.","글자마다 따로 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#17','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C7',3,'ox','auto','「래초」는 뜻이 없는 낱말이에요. 그래도 글자를 하나하나 짚으며 그대로 읽어요.',ARRAY['K1-1-u1-X15']::text[],false,'{"seq":17,"concept":"K1-1-u1-C7","difficulty":3,"kind":"ox","stem":"「래초」는 뜻이 없는 낱말이에요. 그래도 글자를 하나하나 짚으며 그대로 읽어요.","answer":"O","reason_options":[{"t":"자음자와 모음자를 보고 짐작하지 않고 또박또박 읽어야 하니까","correct":true},{"t":"뜻이 없으면 비슷한 아는 낱말로 바꿔 읽으면 되니까","mis":"K1-1-u1-X15"}],"mis":"K1-1-u1-X15","explanation":["래초 = ㄹ·ㅐ + ㅊ·ㅗ.","뜻을 몰라도 자음자와 모음자 소리를 합치면 읽을 수 있어요.","빠르기보다 정확하게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#18','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C2',3,'error','auto','예나가 자음자 ㄴ과 모음자 ㅜ를 모아 「뉴」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u1-X03','K1-1-u1-X04','K1-1-u1-X02']::text[],false,'{"seq":18,"concept":"K1-1-u1-C2","difficulty":3,"kind":"error","stem":"예나가 자음자 ㄴ과 모음자 ㅜ를 모아 「뉴」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"짧은 획을 하나 더 썼어요 — ㄴ과 ㅜ는 「누」예요","correct":true,"mis_target":"K1-1-u1-X03"},{"t":"자음자를 ㄷ으로 써야 해요 — 「두」예요","mis":"K1-1-u1-X04"},{"t":"모음자의 방향을 바꾸어 썼어요 — 「노」예요","mis":"K1-1-u1-X02"}],"explanation":["ㄴ + ㅜ = 누.","「뉴」와 「누」는 다른 글자예요.","자음자와 모음자를 하나씩 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#19','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C3',3,'error','auto','지후가 「부」를 쓸 때 ㅜ를 ㅂ 오른쪽에 붙여 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u1-X05','K1-1-u1-X02','K1-1-u1-X04']::text[],false,'{"seq":19,"concept":"K1-1-u1-C3","difficulty":3,"kind":"error","stem":"지후가 「부」를 쓸 때 ㅜ를 ㅂ 오른쪽에 붙여 썼어요. 무엇이 잘못되었나요?","options":[{"t":"ㅜ는 ㅂ 아래쪽에 써야 해요","correct":true,"mis_target":"K1-1-u1-X05"},{"t":"ㅜ 대신 ㅗ를 써야 해요","mis":"K1-1-u1-X02"},{"t":"ㅂ 대신 ㅍ을 써야 해요","mis":"K1-1-u1-X04"}],"explanation":["ㅜ는 가로로 길어서 아래에 쌓여요.","모음자는 맞게 골랐고 자리만 틀렸어요.","모음자 모양이 자리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#20','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C6',3,'mc','auto','ㅎ + ㅚ 는 어떤 글자가 되나요?',ARRAY['K1-1-u1-X14']::text[],true,'{"seq":20,"kind":"mc","stem":"ㅎ + ㅚ 는 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㅎ","v":"ㅚ","s":null},"options":[{"t":"회","correct":true},{"t":"호","mis":"K1-1-u1-X14"},{"t":"히","mis":"K1-1-u1-X14"}],"explanation":["자음자 ㅎ과 모음자 ㅚ가 만나면 「회」예요.","ㅚ는 자음자의 아래와 오른쪽을 함께 감싸요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C6","difficulty":3,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅐ","ㅔ","ㅒ","ㅖ","ㅘ","ㅝ","ㅚ","ㅟ","ㅙ","ㅢ"],"mis":{"ae":"X13","comb":"X14","cons":"X04"},"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#21','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C7',3,'mc','auto','카드 ㅎ · ㅠ · ㅈ · ㅣ 네 장으로 만들 수 있는 물건은 어느 것인가요?',ARRAY['K1-1-u1-X09','K1-1-u1-X03']::text[],false,'{"seq":21,"concept":"K1-1-u1-C7","difficulty":3,"kind":"mc","stem":"카드 ㅎ · ㅠ · ㅈ · ㅣ 네 장으로 만들 수 있는 물건은 어느 것인가요?","options":[{"t":"휴지","correct":true},{"t":"지휴","mis":"K1-1-u1-X09"},{"t":"후지","mis":"K1-1-u1-X03"}],"explanation":["ㅎ+ㅠ = 휴, ㅈ+ㅣ = 지 — 휴지.","「지휴」는 차례가 바뀌었고, 「후지」는 모음자를 잘못 보았어요.","자음자마다 모음자 짝을 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
