INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_d#5','kor',1,1,'u1','','g1_1_kor_u1_review_d','unit_review','K1-1-u1-C4',1,'mc','auto','음절표에서 ? 칸에 들어갈 글자는 무엇인가요?',ARRAY['K1-1-u1-X06','K1-1-u1-X07']::text[],true,'{"seq":5,"kind":"mc","stem":"음절표에서 ? 칸에 들어갈 글자는 무엇인가요?","asset":{"type":"syl_table","cons":["ㄱ","ㅅ","ㅎ"],"vows":["ㅏ","ㅓ","ㅜ"],"q":[1,2]},"options":[{"t":"수","correct":true},{"t":"서","mis":"K1-1-u1-X06"},{"t":"사","mis":"K1-1-u1-X07"}],"explanation":["? 칸은 자음자 ㅅ 줄과 모음자 ㅜ 칸이 만나는 곳이에요.","ㅅ과 ㅜ가 만나면 「수」예요.","왼쪽 자음자 줄을 따라가다 위쪽 모음자 칸에서 멈춰요."],"concept":"K1-1-u1-C4","difficulty":1,"variant_rule":{"jamo":{"ask":"table","cons":["ㄱ","ㄴ","ㄷ","ㅁ","ㅂ","ㅅ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ"],"mis":{"grid":"X07","rot":"X06"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_d#6','kor',1,1,'u1','','g1_1_kor_u1_review_d','unit_review','K1-1-u1-C5',1,'mc','auto','글씨를 쓸 때 바른 자세는 어느 것인가요?',ARRAY['K1-1-u1-X11']::text[],false,'{"seq":6,"concept":"K1-1-u1-C5","difficulty":1,"kind":"mc","stem":"글씨를 쓸 때 바른 자세는 어느 것인가요?","options":[{"t":"허리를 펴고 공책과 눈 사이를 알맞게 띄워요","correct":true},{"t":"공책에 얼굴을 바짝 대요","mis":"K1-1-u1-X11"},{"t":"엎드려서 써요","mis":"K1-1-u1-X11"}],"explanation":["허리 펴기, 알맞게 띄우기.","얼굴을 대거나 엎드리면 바른 자세가 아니에요.","바른 자세로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_d#7','kor',1,1,'u1','','g1_1_kor_u1_review_d','unit_review','K1-1-u1-C6',1,'mc','auto','「위」에서 모음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X14']::text[],true,'{"seq":7,"kind":"mc","stem":"「위」에서 모음자는 어느 것인가요?","asset":{"type":"jamo","s":"위","eq":false,"lay":"blank"},"options":[{"t":"ㅟ","correct":true},{"t":"ㅇ","mis":"K1-1-u1-X01"},{"t":"ㅜ","mis":"K1-1-u1-X14"}],"explanation":["「위」는 자음자 ㅇ과 모음자 ㅟ가 만난 글자예요.","모음자는 ㅟ예요 — 아래와 오른쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C6","difficulty":1,"variant_rule":{"jamo":{"ask":"vow","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅐ","ㅔ","ㅒ","ㅖ","ㅘ","ㅝ","ㅚ","ㅟ","ㅙ","ㅢ"],"mis":{"role":"X01","ae":"X13","comb":"X14"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_d#8','kor',1,1,'u1','','g1_1_kor_u1_review_d','unit_review','K1-1-u1-C7',1,'mc','auto','그림에 알맞은 낱말 카드는 어느 것인가요?',ARRAY['K1-1-u1-X09','K1-1-u1-X13']::text[],false,'{"seq":8,"concept":"K1-1-u1-C7","difficulty":1,"kind":"mc","stem":"그림에 알맞은 낱말 카드는 어느 것인가요?","options":[{"t":"무지개","correct":true},{"t":"지무개","mis":"K1-1-u1-X09"},{"t":"무지게","mis":"K1-1-u1-X13"}],"explanation":["그림은 「무지개」예요.","「지무개」는 차례가 바뀌었고, 「무지게」는 모음자를 잘못 보았어요.","그림 뜻 + 글자 차례 + 모음자."],"asset":{"type":"scene","icon":"🌈"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_d#9','kor',1,1,'u1','','g1_1_kor_u1_review_d','unit_review','K1-1-u1-C1',2,'mc','auto','「셔」에서 모음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X02']::text[],true,'{"seq":9,"kind":"mc","stem":"「셔」에서 모음자는 어느 것인가요?","asset":{"type":"jamo","s":"셔","eq":false,"lay":"blank"},"options":[{"t":"ㅕ","correct":true},{"t":"ㅅ","mis":"K1-1-u1-X01"},{"t":"ㅑ","mis":"K1-1-u1-X02"}],"explanation":["「셔」는 자음자 ㅅ과 모음자 ㅕ가 만난 글자예요.","모음자는 ㅕ예요 — 오른쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C1","difficulty":2,"variant_rule":{"jamo":{"ask":"vow","cons":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅈ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅑ","ㅕ"],"mis":{"role":"X01","flip":"X02","stroke":"X03","rot":"X06"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_d#10','kor',1,1,'u1','','g1_1_kor_u1_review_d','unit_review','K1-1-u1-C2',2,'mc','auto','ㄱ + ㅠ 는 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":10,"kind":"mc","stem":"ㄱ + ㅠ 는 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㄱ","v":"ㅠ","s":null},"options":[{"t":"규","correct":true},{"t":"교","mis":"K1-1-u1-X02"},{"t":"구","mis":"K1-1-u1-X03"}],"explanation":["자음자 ㄱ과 모음자 ㅠ가 만나면 「규」예요.","ㅠ는 가로로 길어서 자음자 아래에 쌓여요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":2,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅑ","ㅕ","ㅛ","ㅠ"],"mis":{"flip":"X02","stroke":"X03","rot":"X06","cons":"X04"},"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_d#11','kor',1,1,'u1','','g1_1_kor_u1_review_d','unit_review','K1-1-u1-C3',2,'mc','auto','「리」에서 모음자 ㅣ는 어디에 있나요?',ARRAY['K1-1-u1-X05','K1-1-u1-X01']::text[],true,'{"seq":11,"kind":"mc","stem":"「리」에서 모음자 ㅣ는 어디에 있나요?","asset":{"type":"jamo","s":"리","eq":false},"options":[{"t":"오른쪽","correct":true},{"t":"아래쪽","mis":"K1-1-u1-X05"},{"t":"왼쪽","mis":"K1-1-u1-X01"}],"explanation":["「리」는 옆으로 나란히 만든 글자예요.","ㅣ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","그래서 모음자 ㅣ는 오른쪽에 있어요."],"concept":"K1-1-u1-C3","difficulty":2,"variant_rule":{"jamo":{"ask":"place","role":"v","cons":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅈ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ","ㅡ"],"mis":{"place":"X05","role":"X01"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_d#12','kor',1,1,'u1','','g1_1_kor_u1_review_d','unit_review','K1-1-u1-C3',2,'mc','auto','옆으로 나란히 만든 글자는 어느 것인가요?',ARRAY['K1-1-u1-X05']::text[],false,'{"seq":12,"concept":"K1-1-u1-C3","difficulty":2,"kind":"mc","stem":"옆으로 나란히 만든 글자는 어느 것인가요?","options":[{"t":"지","correct":true},{"t":"조","mis":"K1-1-u1-X05"},{"t":"주","mis":"K1-1-u1-X05"}],"explanation":["「지」는 ㅈ 오른쪽에 ㅣ.","「조」·「주」는 위아래로.","세로로 긴 모음자는 옆에."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_d#13','kor',1,1,'u1','','g1_1_kor_u1_review_d','unit_review','K1-1-u1-C4',2,'mc','auto','음절표에서 ㄴ 줄을 따라 차례대로 읽은 것은 어느 것인가요?',ARRAY['K1-1-u1-X07','K1-1-u1-X02']::text[],false,'{"seq":13,"concept":"K1-1-u1-C4","difficulty":2,"kind":"mc","stem":"음절표에서 ㄴ 줄을 따라 차례대로 읽은 것은 어느 것인가요?","options":[{"t":"나 · 너 · 노 · 누","correct":true},{"t":"나 · 바 · 자","mis":"K1-1-u1-X07"},{"t":"나 · 너 · 누 · 노","mis":"K1-1-u1-X02"}],"explanation":["ㄴ 줄은 나·너·노·누예요.","다른 하나는 ㅏ 칸을 위에서 아래로 읽은 거예요.","줄은 옆으로 읽어요."],"asset":{"type":"syl_table","cons":["ㄴ","ㅂ","ㅈ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_d#14','kor',1,1,'u1','','g1_1_kor_u1_review_d','unit_review','K1-1-u1-C5',2,'mc','auto','「부」를 쓰는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u1-X12']::text[],false,'{"seq":14,"concept":"K1-1-u1-C5","difficulty":2,"kind":"mc","stem":"「부」를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"ㅂ을 먼저 쓰고 ㅜ를 써요","correct":true},{"t":"ㅜ를 먼저 쓰고 ㅂ을 써요","mis":"K1-1-u1-X12"},{"t":"ㅂ을 아래에서 위로 써요","mis":"K1-1-u1-X12"}],"explanation":["자음자를 먼저, 모음자를 나중에.","모음자의 획도 위에서 아래로, 왼쪽에서 오른쪽으로.","자음자 먼저."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_d#15','kor',1,1,'u1','','g1_1_kor_u1_review_d','unit_review','K1-1-u1-C6',2,'match','auto','두 모음자를 합쳐 만든 모음자를 바르게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"K1-1-u1-C6","difficulty":2,"kind":"match","stem":"두 모음자를 합쳐 만든 모음자를 바르게 이으세요.","pairs":[{"l":"ㅡ + ㅣ","r":"ㅢ"},{"l":"ㅗ + ㅣ","r":"ㅚ"},{"l":"ㅜ + ㅓ","r":"ㅝ"}],"mis":"K1-1-u1-X14","explanation":["두 모음자를 다 봐요.","앞의 모음자 + 뒤의 모음자.","합친 모음자 = 두 모음자."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_d#16','kor',1,1,'u1','','g1_1_kor_u1_review_d','unit_review','K1-1-u1-C6',2,'ox','auto','「예」에는 모음자 ㅖ가 들어 있어요.',ARRAY['K1-1-u1-X16']::text[],false,'{"seq":16,"concept":"K1-1-u1-C6","difficulty":2,"kind":"ox","stem":"「예」에는 모음자 ㅖ가 들어 있어요.","answer":"O","reason_options":[{"t":"「예」는 ㅇ과 ㅖ가 만난 글자니까","correct":true},{"t":"「예」는 모음자 하나로만 된 글자니까","mis":"K1-1-u1-X16"}],"mis":"K1-1-u1-X16","explanation":["예 = ㅇ + ㅖ.","소리 없는 ㅇ도 자음자예요.","ㅖ는 ㅕ와 ㅣ가 붙은 모양."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_d#17','kor',1,1,'u1','','g1_1_kor_u1_review_d','unit_review','K1-1-u1-C7',3,'ox','auto','「듀붜」는 뜻이 없는 낱말이에요. 그래도 글자를 하나하나 짚으며 그대로 읽어요.',ARRAY['K1-1-u1-X15']::text[],false,'{"seq":17,"concept":"K1-1-u1-C7","difficulty":3,"kind":"ox","stem":"「듀붜」는 뜻이 없는 낱말이에요. 그래도 글자를 하나하나 짚으며 그대로 읽어요.","answer":"O","reason_options":[{"t":"자음자와 모음자를 보고 짐작하지 않고 또박또박 읽어야 하니까","correct":true},{"t":"뜻이 없으면 비슷한 아는 낱말로 바꿔 읽으면 되니까","mis":"K1-1-u1-X15"}],"mis":"K1-1-u1-X15","explanation":["듀붜 = ㄷ·ㅠ + ㅂ·ㅝ.","뜻을 몰라도 자음자와 모음자 소리를 합치면 읽을 수 있어요.","빠르기보다 정확하게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_d#18','kor',1,1,'u1','','g1_1_kor_u1_review_d','unit_review','K1-1-u1-C2',3,'error','auto','하루가 자음자 ㅈ과 모음자 ㅏ를 모아 「차」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u1-X04','K1-1-u1-X02','K1-1-u1-X06']::text[],false,'{"seq":18,"concept":"K1-1-u1-C2","difficulty":3,"kind":"error","stem":"하루가 자음자 ㅈ과 모음자 ㅏ를 모아 「차」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"자음자를 ㅊ으로 바꾸어 썼어요 — ㅈ과 ㅏ는 「자」예요","correct":true,"mis_target":"K1-1-u1-X04"},{"t":"모음자의 방향을 바꾸어 썼어요 — 「저」예요","mis":"K1-1-u1-X02"},{"t":"카드를 돌려 썼어요 — 「조」예요","mis":"K1-1-u1-X06"}],"explanation":["ㅈ + ㅏ = 자.","「차」와 「자」는 다른 글자예요.","자음자와 모음자를 하나씩 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_d#19','kor',1,1,'u1','','g1_1_kor_u1_review_d','unit_review','K1-1-u1-C3',3,'error','auto','서아가 「가」를 쓸 때 ㅏ를 ㄱ 아래쪽에 붙여 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u1-X05','K1-1-u1-X02','K1-1-u1-X04']::text[],false,'{"seq":19,"concept":"K1-1-u1-C3","difficulty":3,"kind":"error","stem":"서아가 「가」를 쓸 때 ㅏ를 ㄱ 아래쪽에 붙여 썼어요. 무엇이 잘못되었나요?","options":[{"t":"ㅏ는 ㄱ 오른쪽에 써야 해요","correct":true,"mis_target":"K1-1-u1-X05"},{"t":"ㅏ 대신 ㅓ를 써야 해요","mis":"K1-1-u1-X02"},{"t":"ㄱ 대신 ㅋ을 써야 해요","mis":"K1-1-u1-X04"}],"explanation":["ㅏ는 세로로 길어서 옆에 서요.","모음자는 맞게 골랐고 자리만 틀렸어요.","모음자 모양이 자리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_d#20','kor',1,1,'u1','','g1_1_kor_u1_review_d','unit_review','K1-1-u1-C6',3,'mc','auto','ㄱ + ㅖ 는 어떤 글자가 되나요?',ARRAY['K1-1-u1-X13']::text[],true,'{"seq":20,"kind":"mc","stem":"ㄱ + ㅖ 는 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㄱ","v":"ㅖ","s":null},"options":[{"t":"계","correct":true},{"t":"걔","mis":"K1-1-u1-X13"},{"t":"게","mis":"K1-1-u1-X13"}],"explanation":["자음자 ㄱ과 모음자 ㅖ가 만나면 「계」예요.","ㅖ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C6","difficulty":3,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅐ","ㅔ","ㅒ","ㅖ","ㅘ","ㅝ","ㅚ","ㅟ","ㅙ","ㅢ"],"mis":{"ae":"X13","comb":"X14","cons":"X04"},"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_d#21','kor',1,1,'u1','','g1_1_kor_u1_review_d','unit_review','K1-1-u1-C7',3,'mc','auto','카드 ㄱ · ㅣ · ㅇ · ㅘ 네 장으로 만들 수 있는 지붕에 얹는 것은 어느 것인가요?',ARRAY['K1-1-u1-X09','K1-1-u1-X14']::text[],false,'{"seq":21,"concept":"K1-1-u1-C7","difficulty":3,"kind":"mc","stem":"카드 ㄱ · ㅣ · ㅇ · ㅘ 네 장으로 만들 수 있는 지붕에 얹는 것은 어느 것인가요?","options":[{"t":"기와","correct":true},{"t":"와기","mis":"K1-1-u1-X09"},{"t":"기아","mis":"K1-1-u1-X14"}],"explanation":["ㄱ+ㅣ = 기, ㅇ+ㅘ = 와 — 기와.","「와기」는 차례가 바뀌었고, 「기아」는 모음자를 잘못 보았어요.","자음자마다 모음자 짝을 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_d#22','kor',1,1,'u1','','g1_1_kor_u1_review_d','unit_review','K1-1-u1-C5',3,'error','auto','유나가 쓰기 자세를 점검했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_d#23','kor',1,1,'u1','','g1_1_kor_u1_review_d','unit_review','K1-1-u1-C4',4,'sa','auto','음절표에서 ? 칸에 들어갈 글자를 쓰세요.','{}'::text[],true,'{"seq":23,"kind":"sa","stem":"음절표에서 ? 칸에 들어갈 글자를 쓰세요.","asset":{"type":"syl_table","cons":["ㄹ","ㅂ","ㅅ","ㅈ"],"vows":["ㅑ","ㅓ","ㅗ","ㅣ"],"q":[2,0]},"answer":["샤"],"explanation":["? 칸은 자음자 ㅅ 줄과 모음자 ㅑ 칸이 만나는 곳이에요.","ㅅ과 ㅑ가 만나면 「샤」예요.","왼쪽 자음자 줄을 따라가다 위쪽 모음자 칸에서 멈춰요."],"concept":"K1-1-u1-C4","difficulty":4,"variant_rule":{"jamo":{"ask":"table","cons":["ㄱ","ㄴ","ㄹ","ㅁ","ㅅ","ㅎ"],"vows":["ㅑ","ㅕ","ㅛ","ㅠ"],"mis":{"grid":"X07","flip":"X02","stroke":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_d#24','kor',1,1,'u1','','g1_1_kor_u1_review_d','unit_review','K1-1-u1-C7',4,'essay','teacher','카드 ㅅ · ㅈ · ㅏ · ㅜ 를 골라 낱말을 두 개 만들고, 글자마다 어떤 자음자와 모음자를 모았는지 말해 보세요. (카드는 여러 번 써도 돼요)','{}'::text[],false,'{"seq":24,"concept":"K1-1-u1-C7","difficulty":4,"kind":"essay","stem":"카드 ㅅ · ㅈ · ㅏ · ㅜ 를 골라 낱말을 두 개 만들고, 글자마다 어떤 자음자와 모음자를 모았는지 말해 보세요. (카드는 여러 번 써도 돼요)","answer_guide":{"answer":"예: 「사자」(ㅅ+ㅏ, ㅈ+ㅏ)와 「주사」(ㅈ+ㅜ, ㅅ+ㅏ) — 뜻이 있는 낱말 두 개를 만들고 글자마다 자음자+모음자를 바르게 말하면 맞아요.","scoring_points":["뜻이 있는 낱말을 두 개 만들었는가","글자마다 자음자와 모음자를 바르게 말했는가","글자를 차례대로 모았는가"]},"explanation":["낱말 두 개.","글자마다 자음자 + 모음자.","차례대로 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_d#25','kor',1,1,'u1','','g1_1_kor_u1_review_d','unit_review','K1-1-u1-C2',4,'mc','auto','카드 ㅈ · ㅎ · ㅏ · ㅡ 가운데 두 장을 골라 만들 수 없는 글자는 어느 것인가요?',ARRAY['K1-1-u1-X04','K1-1-u1-X01']::text[],false,'{"seq":25,"concept":"K1-1-u1-C2","difficulty":4,"kind":"mc","stem":"카드 ㅈ · ㅎ · ㅏ · ㅡ 가운데 두 장을 골라 만들 수 없는 글자는 어느 것인가요?","options":[{"t":"차","correct":true},{"t":"자","mis":"K1-1-u1-X04"},{"t":"흐","mis":"K1-1-u1-X01"}],"explanation":["「차」에 필요한 카드가 없어요.","「자」와 「흐」는 만들 수 있어요.","자음자 하나 + 모음자 하나."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
